schemas.schema-03-content.prisma:
/// Represents all main forum posts in the discussion board. Each post is
/// authored by either a member, moderator, or admin (referenced via foreign
/// keys to those user tables) and is optionally linked to a
/// discussion_board_category and platform configuration. This table stores
/// only raw content (title, body, attachment link(s)), category assignment,
/// and status. No voting, comment, or moderation data is included here,
/// which are managed by other components. Includes temporal fields for full
/// audit (creation, update, soft deletion) and supports future extension for
/// post versioning and snapshot. Complies with 3NF, with no
/// denormalized/cached vote or comment counts.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged member's {@link discussion_board_members.id}. Used when post
  /// author is a regular member.
  author_member_id String? @db.Uuid

  /// Belonged moderator's {@link discussion_board_moderators.id}. Used when
  /// post author is a moderator.
  author_moderator_id String? @db.Uuid

  /// Belonged admin's {@link discussion_board_admins.id}. Used when post
  /// author is an administrator.
  author_admin_id String? @db.Uuid

  /// Assigned post's category (optional). References {@link
  /// discussion_board_categories.id}.
  category_id String? @db.Uuid

  /// Platform configuration for post context (multi-instance/segmentation
  /// support). References {@link discussion_board_platform_configs.id}.
  platform_config_id String? @db.Uuid

  /// Post title. Maximum 100 characters. Required on all posts.
  title String

  /// Main post content/body. Maximum 4000 characters. Required field.
  body String

  /// Optional URI-encoded or JSON string listing post attachments (cloud link,
  /// images, files, etc.). Up to 5 attachments allowed per post.
  attachments String?

  /// Post status code: e.g., 'active', 'deleted', 'hidden', 'flagged'. Exact
  /// codes managed by business rules. Used for workflow visibility and
  /// moderation.
  status String

  /// Post creation timestamp (UTC).
  created_at DateTime @db.Timestamptz

  /// Post last update timestamp (UTC).
  updated_at DateTime @db.Timestamptz

  /// Post deletion timestamp (null if not deleted; soft delete logic).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  authorMember discussion_board_members? @relation(fields: [author_member_id], references: [id], onDelete: Cascade)
  authorModerator discussion_board_moderators? @relation(fields: [author_moderator_id], references: [id], onDelete: Cascade)
  authorAdmin discussion_board_admins? @relation(fields: [author_admin_id], references: [id], onDelete: Cascade)
  category discussion_board_categories? @relation(fields: [category_id], references: [id], onDelete: Cascade)
  platformConfig discussion_board_platform_configs? @relation(fields: [platform_config_id], references: [id], onDelete: Cascade)

  discussion_board_comments discussion_board_comments[]
  discussion_board_post_votes discussion_board_post_votes[]
  discussion_board_post_reports discussion_board_post_reports[]
  discussion_board_post_metrics discussion_board_post_metrics?

  @@index([author_member_id])
  @@index([author_moderator_id])
  @@index([author_admin_id])
  @@index([category_id])
  @@index([platform_config_id])
  @@index([status])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Stores all comments (including replies) linked to discussion board posts.
/// Each comment is authored by either a member, moderator, or admin
/// (referenced via foreign keys to user tables). Parent-child relationships
/// are supported through the thread_parent_comment_id field to allow for
/// hierarchical reply trees (single parent per comment; top-level comments
/// have null parent). Every comment references its source post. Content,
/// visibility status, and temporal/audit columns are included. No cached
/// vote or report data is present in this table. Strict normalization: only
/// raw comment data and relationships are stored. Entity includes fields for
/// full temporal audit and soft delete. 3NF enforced; all denormalization is
/// prohibited except in mv_ prefixed views.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The post associated with this comment. {@link discussion_board_posts.id}.
  post_id String @db.Uuid

  /// Comment author's member reference if the author is a regular member.
  /// {@link discussion_board_members.id}.
  author_member_id String? @db.Uuid

  /// Comment author's moderator reference (when a moderator authors; otherwise
  /// null). {@link discussion_board_moderators.id}.
  author_moderator_id String? @db.Uuid

  /// Comment author's admin reference (when an admin authors the comment;
  /// otherwise null). {@link discussion_board_admins.id}.
  author_admin_id String? @db.Uuid

  /// Self-referencing: parent comment's {@link discussion_board_comments.id}.
  /// Null if this is a top-level comment.
  thread_parent_comment_id String? @db.Uuid

  /// Comment content/body text. Maximum 1000 characters. Required for all
  /// comments (including replies).
  body String

  /// Current comment status: e.g., 'active', 'deleted', 'hidden', 'flagged'.
  /// Statuses follow business workflow.
  status String

  /// Timestamp when comment was written (UTC, required).
  created_at DateTime @db.Timestamptz

  /// Comment last updated timestamp (UTC, required).
  updated_at DateTime @db.Timestamptz

  /// Soft delete field: timestamp of deletion, or null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  authorMember discussion_board_members? @relation(fields: [author_member_id], references: [id], onDelete: Cascade)
  authorModerator discussion_board_moderators? @relation(fields: [author_moderator_id], references: [id], onDelete: Cascade)
  authorAdmin discussion_board_admins? @relation(fields: [author_admin_id], references: [id], onDelete: Cascade)
  parentComment discussion_board_comments? @relation("recursive", fields: [thread_parent_comment_id], references: [id], onDelete: Cascade)

  recursive discussion_board_comments[] @relation("recursive")
  discussion_board_comment_votes discussion_board_comment_votes[]
  discussion_board_comment_reports discussion_board_comment_reports[]

  @@index([post_id])
  @@index([author_member_id])
  @@index([author_moderator_id])
  @@index([author_admin_id])
  @@index([thread_parent_comment_id])
  @@index([status])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-interactions.prisma:
