  discussion_board_post_id String @db.Uuid

  /// Voter's {@link discussion_board_members.id} who cast the vote.
  discussion_board_member_id String @db.Uuid

  /// Whether the vote is an upvote (true) or a downvote (false).
  is_upvote Boolean

  /// Timestamp when this vote was created.
  created_at DateTime @db.Timestamptz

