  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for the vote interaction (null if active, set
  /// when deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussion_board_posts @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  member discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, discussion_board_member_id], map: "discussion_board_post_votes_discussion_board_post_id_d_b7f62771")
  @@index([discussion_board_post_id])
  @@index([discussion_board_member_id])
  @@index([created_at])
}

