  member discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_comment_id, discussion_board_member_id], map: "discussion_board_comment_votes_discussion_board_commen_1576db93")
