schemas.schema-05-reports.prisma:
/// Logs each abuse report submitted against a discussion board post. Stores
/// reporting user, post information, reason, type, status, handler, result,
/// and freeform message for audit and moderation. Enables tracking report
/// lifecycle from submission through resolution for all reported posts.
/// Relates to {@link discussion_board_posts}, {@link
/// discussion_board_members}, and moderation staff tables.
///
/// @namespace Reports
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target post that is being reported. {@link discussion_board_posts.id}
  discussion_board_post_id String @db.Uuid

  /// Reporting user who submitted the report. {@link
  /// discussion_board_members.id}
  discussion_board_member_id String @db.Uuid

  /// Admin or moderator who processed the report (if applicable). {@link
  /// discussion_board_admins.id}
  handler_admin_id String? @db.Uuid

  /// Coded reason for report (ex: spam, hate, personal info). Used for
  /// policy/statistics.
  reason_type String

  /// Freeform detailed explanation of the report by the user.
  reason_text String?

  /// Current state of this report: 'pending', 'in_review', 'action_taken',
