import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IStd } from "@ORGANIZATION/PROJECT-api/lib/structures/IStd";

/**
 * Validate successful soft-deletion (withdrawal) of a discussion board member account by the member themselves, audit effects, and proper forbidden/retry error flows.
 *
 * Steps:
 * 1. Register a new member and log in (to obtain authenticated session).
 * 2. Pre-check: Confirm member profile is accessible prior to withdrawal (GET /discussionBoard/member/members/{memberId}).
 * 3. Withdraw the member's own account using DELETE /discussionBoard/member/members/{memberId} as that member.
 * 4. Immediately after, re-check member profile (GET): should indicate deactivated (status = 'withdrawn', deleted_at populated).
 * 5. Log out (POST /auth/member/logout). Confirm success.
 * 6. Attempt to re-register with the same credentials: should fail (forbidden for duplicate email/nickname).
 * 7. Attempt to access member profile (GET) again as unauthenticated user: should return 'withdrawn' status profile or error dependent on API behavior.
 * 8. Attempt to withdraw the already withdrawn account again: should throw error.
 *
 * Business justifications:
 * - Ensures proper workflow for self-initiated withdrawal, honoring soft deletion / retention logic.
 * - Verifies post-withdrawal login/session protection and audit trail-like retention of history.
 * - Ensures historic audit access while disallowing normal interaction after withdrawal.
 */
export async function test_api_member_withdrawal_success_and_audit_trail(connection: api.IConnection) {
  // 1. Register a new member and obtain session
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const nickname = RandomGenerator.alphaNumeric(8);

  const regSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(regSession);
  const memberId = regSession.member.id;

  // 2. Pre-check: Confirm member profile accessible before withdrawal
  const memberProfile = await api.functional.discussionBoard.member.members.at(connection, { memberId });
  typia.assert(memberProfile);
  TestValidator.equals("member email matches")(memberProfile.email)(email);
  TestValidator.predicate("initial status active or pending_verification")(["active", "pending_verification"].includes(memberProfile.status));
  TestValidator.equals("deleted_at is null")((typeof memberProfile.deleted_at === "undefined" || memberProfile.deleted_at === null))(true);

  // 3. Withdraw the member's own account
  await api.functional.discussionBoard.member.members.erase(connection, { memberId });

  // 4. Immediately re-check profile – should show status withdrawn and deleted_at set
  const withdrawnProfile = await api.functional.discussionBoard.member.members.at(connection, { memberId });
  typia.assert(withdrawnProfile);
  TestValidator.equals("withdrawn")(withdrawnProfile.status)("withdrawn");
  TestValidator.predicate("deleted_at present")(typeof withdrawnProfile.deleted_at === "string" && withdrawnProfile.deleted_at.length > 0);

  // 5. Log out (should still work after withdrawal)
  const logoutResult = await api.functional.auth.member.logout.signOut(connection);
  typia.assert(logoutResult);
  TestValidator.equals("logout ok")(logoutResult.ok)(true);

  // 6. Attempt to re-register with identical credentials (should fail: duplicate email/nickname)
  TestValidator.error("duplicate email forbidden")(
    async () => {
      await api.functional.auth.member.register.signUp(connection, {
        body: {
          email,
          password,
          nickname
        } satisfies IDiscussionBoardMember.ICreate
      });
    }
  );

  // 7. Attempt GET again unauthenticated – may be visible as withdrawn or trigger forbidden
  const postWithdrawProfile = await api.functional.discussionBoard.member.members.at(connection, { memberId });
  typia.assert(postWithdrawProfile);
  TestValidator.equals("withdrawn status visible")(postWithdrawProfile.status)("withdrawn");

  // 8. Attempt to withdraw already withdrawn account (should error)
  TestValidator.error("cannot withdraw again")(
    async () => {
      await api.functional.discussionBoard.member.members.erase(connection, { memberId });
    }
  );
}

