/**
 * E2E test for admin search, filter, and pagination on moderator accounts in discussion board.
 *
 * 1. Register two admin users (for privilege/diversity).
 * 2. Register multiple moderator accounts with a variety of states and assignment timestamps. Assign moderators alternately by the two admins for filter/statistics test.
 * 3. As ADMIN:
 *   - Search moderators by email (exact and partial match) and validate the results.
 *   - Search by status ('active' at signup only, but test filter still).
 *   - Search by assigned_by_admin_email.
 *   - Search by assigned_at_from and assigned_at_to range.
 *   - Validate pagination (limit, page) and sorting (order_by/order_dir).
 *   - Combined filters: test mix of filters and cross-field conditions.
 * 4. Negative/edge cases:
 *   - Search with non-existent email/status/assigned_by_admin_email/assigned_at.
 *   - Search with invalid date format for assigned_at_from and expect an error.
 *   - Attempt to search as a moderator and ensure permission error.
 */
export async function test_api_moderator_search_filter_pagination(connection: api.IConnection) {
  // Register admin 1
  const adminEmail1 = typia.random<string & tags.Format<"email">>();
  const adminPW = "AdminPW1234!";
  const admin1 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail1, password: adminPW } });
  typia.assert(admin1);

  // Register admin 2
  const adminEmail2 = typia.random<string & tags.Format<"email">>();
  const admin2 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail2, password: adminPW } });
  typia.assert(admin2);

  // Register 6 moderators, alternate the assigning admin
  const moderators = await ArrayUtil.asyncRepeat(6)(async (i: number) => {
    const email = typia.random<string & tags.Format<"email">>();
    const assigned_by = i % 2 === 0 ? adminEmail1 : adminEmail2;
    const password = "ModPW1234!";
    const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
      body: { email, assigned_by_admin_email: assigned_by, password }
    });
    typia.assert(signUpResp);
    return signUpResp;
  });

  // Switch to Admin 1 context for privileged tests
  connection.headers = { ...connection.headers, Authorization: admin1.setHeaders.Authorization };

  // Search: by email (exact)
  const searchEmail = moderators[0].email;
  const output1 = await api.functional.discussionBoard.admin.moderators.search(connection, {
    body: { email: searchEmail },
  });
  typia.assert(output1);
  TestValidator.predicate("search by email is correct")(output1.data.every(m => m.email === searchEmail));

  // Search: partial email
  const partial = searchEmail.split("@")[0];
  const output1b = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { email: partial } });
  typia.assert(output1b);
  TestValidator.predicate("partial email match")(output1b.data.some(m => m.email === searchEmail));

  // Search: by status (all active at signup)
  const status = moderators[0].status;
  const outStatus = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { status } });
  typia.assert(outStatus);
  TestValidator.predicate("search by status")(outStatus.data.every(m => m.status === status));

  // Search: assigned_by_admin_email
  const outByAdmin1 = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_by_admin_email: adminEmail1 } });
  typia.assert(outByAdmin1);
  TestValidator.predicate("search by assigned_by_admin_email")(outByAdmin1.data.every(m => m.assigned_by_admin_email === adminEmail1));

  // Search: assigned_at_from (use assigned_at from a later moderator)
  const minAssignedAt = moderators[3].assigned_at;
  const outAssignedFrom = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: minAssignedAt } });
  typia.assert(outAssignedFrom);
  TestValidator.predicate("assigned_at_from")(outAssignedFrom.data.every(m => m.assigned_at >= minAssignedAt));

  // Search: assigned_at_to (use assigned_at from an earlier moderator)
  const maxAssignedAt = moderators[1].assigned_at;
  const outAssignedTo = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_to: maxAssignedAt } });
  typia.assert(outAssignedTo);
  TestValidator.predicate("assigned_at_to")(outAssignedTo.data.every(m => m.assigned_at <= maxAssignedAt));

  // Pagination
  const outPaginated = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { limit: 2, page: 2 } });
  typia.assert(outPaginated);
  TestValidator.equals("limit")(outPaginated.pagination.limit)(2);
  TestValidator.equals("page")(outPaginated.pagination.current)(2);

  // Order_by and order_dir
  const outOrdered = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { order_by: "assigned_at", order_dir: "desc" } });
  typia.assert(outOrdered);
  TestValidator.predicate("sorted desc")(outOrdered.data.every((val, idx, arr) => idx === 0 || arr[idx - 1].assigned_at >= val.assigned_at));

  // Combined filters (status+assigner+time window)
  const combo = await api.functional.discussionBoard.admin.moderators.search(connection, {
    body: {
      status,
      assigned_by_admin_email: adminEmail1,
      assigned_at_from: moderators[4].assigned_at,
      assigned_at_to: moderators[0].assigned_at,
      limit: 5,
    }
  });
  typia.assert(combo);
  TestValidator.predicate("combined filters")(combo.data.every(m => m.status === status && m.assigned_by_admin_email === adminEmail1 && m.assigned_at >= moderators[4].assigned_at && m.assigned_at <= moderators[0].assigned_at));

  // Negative: non-existent email
  const outNegEmail = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { email: "no-such-user@domain.com" } });
  typia.assert(outNegEmail);
  TestValidator.equals("empty result for unknown email")(outNegEmail.data.length)(0);

  // Negative: invalid status
  const outNegStatus = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { status: "doesnotexist" } });
  typia.assert(outNegStatus);
  TestValidator.equals("empty result for bad status")(outNegStatus.data.length)(0);

  // Negative: assigned_at_from in the far future
  const outNegRange = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "2099-01-01T00:00:00Z" } });
  typia.assert(outNegRange);
  TestValidator.equals("empty future filter")(outNegRange.data.length)(0);

  // Negative: garbage date string (should throw error, not validate error message)
  await TestValidator.error("garbage date throws")(async () =>
    api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "NOTADATE" } })
  );

  // Permission check: as moderator (should error)
  connection.headers = { ...connection.headers, Authorization: moderators[0].setHeaders.Authorization };
  await TestValidator.error("moderator forbidden to search")(async () =>
    api.functional.discussionBoard.admin.moderators.search(connection, { body: {} })
  );
}

