/**
 * Test admin's ability to retrieve a moderator's details by their UUID.
 *
 * Business case:
 * Ensures that an admin can fetch full details of a moderator account using the moderator's unique identifier (UUID). The test flow provisions a new admin, uses that admin to register a moderator, and then validates access control and data integrity. It also checks robust API permission enforcement by confirming that non-admins (i.e., moderator) cannot access this endpoint and that queries for non-existent IDs return errors.
 *
 * Steps:
 * 1. Register a new admin via /auth/admin/register, capturing the admin credentials and JWT access token.
 * 2. Register a new moderator as the admin, capturing the moderator's UUID and session token.
 * 3. Use the admin JWT to fetch the moderator's full details with /discussionBoard/admin/moderators/{moderatorId} and verify all expected profile/audit fields.
 * 4. Attempt to retrieve details for a non-existent moderator ID; assert that an error is thrown.
 * 5. Switch context to the moderator account and attempt the same GET; assert that access is forbidden (moderators cannot use this admin endpoint).
 */
export async function test_api_admin_fetch_moderator_details_by_id(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "admin-1234";
  const adminRegisterResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegisterResp);

  // 2. Register a moderator (as admin)
  connection.headers = { ...connection.headers, Authorization: adminRegisterResp.setHeaders.Authorization };
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "moderator-4321";
  const moderatorRegisterResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorRegisterResp);

  // 3. GET moderator details as admin
  const moderatorId = moderatorRegisterResp.moderator_id;
  const modDetails = await api.functional.discussionBoard.admin.moderators.at(connection, {
    moderatorId,
  });
