  TestValidator.equals("assigned_by_admin_email matches")(modDetails.assigned_by_admin_email)(adminEmail);
  TestValidator.equals("moderatorId matches")(modDetails.id)(moderatorId);
  TestValidator.equals("status is active")(modDetails.status)(moderatorRegisterResp.status);

  // 4. GET non-existent moderator (should error)
  await TestValidator.error("Non-existent moderator should return error")(
    () => api.functional.discussionBoard.admin.moderators.at(connection, {
      moderatorId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. GET moderator details as the moderator (should be forbidden)
  connection.headers = { ...connection.headers, Authorization: moderatorRegisterResp.setHeaders.Authorization };
  await TestValidator.error("Moderator cannot access admin endpoint")(
    () => api.functional.discussionBoard.admin.moderators.at(connection, {
      moderatorId,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate that a moderator can only access their own assignment and status via their moderatorId, and is forbidden from accessing other moderator records.
 *
 * Business context:
 * - Moderators must be able to view their own profile and assignment/status data for transparency and self-audit.
 * - Security enforcement: Each moderator should be prohibited from viewing others' moderator details, regardless of UUID knowledge.
 * - Audit: Requests for non-existent or deleted moderatorId should return error responses, not leak data.
 *
 * Step-by-step process:
 * 1. Register and authenticate as a new moderator; extract moderatorId and JWT.
 * 2. Fetch the moderator's own profile using the supplied UUID and validate all returned fields.
 * 3. Attempt to fetch a random other moderatorId (should be forbidden or not found).
 * 4. Attempt to fetch a non-existent (clearly invalid) UUID and validate not found error.
 * 5. (Soft-deleted case is omitted, as no API supports creating a soft-deleted record.)
 */
export async function test_api_moderator_self_assignment_record_access(
  connection: api.IConnection,
) {
  // 1. Register new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "SecureTest123!";

  // Registration (returns token in setHeaders)
  const registration = await api.functional.auth.moderator.register.signUp(
    connection,
    {
      body: {
        email: moderatorEmail,
        assigned_by_admin_email: adminEmail,
        password: moderatorPassword,
      } satisfies IModerator.SignUp,
    },
  );
  typia.assert(registration);
  // Set Authorization header for subsequent authenticated requests (if not auto-injected)
  connection.headers = {
    ...connection.headers,
    ...registration.setHeaders,
  };

  // 2. Fetch own moderator profile via UUID
  const selfProfile = await api.functional.discussionBoard.moderator.moderators.at(
    connection,
    {
      moderatorId: registration.moderator_id,
    },
  );
  typia.assert(selfProfile);
  TestValidator.equals("moderator id matches")(selfProfile.id)(registration.moderator_id);
  TestValidator.equals("email matches")(selfProfile.email)(registration.email);
  TestValidator.equals("admin who assigned matches")(selfProfile.assigned_by_admin_email)(adminEmail);
  TestValidator.equals("status active")(selfProfile.status)(registration.status);

  // 3. Attempt to fetch a random other moderatorId (should fail with forbidden/not found)
  const randomOtherModeratorId = typia.random<string & tags.Format<"uuid">>();
  if (randomOtherModeratorId !== registration.moderator_id) {
    await TestValidator.error("forbidden when accessing another moderatorId")(async () => {
      await api.functional.discussionBoard.moderator.moderators.at(connection, {
        moderatorId: randomOtherModeratorId,
      });
    });
  }

  // 4. Attempt to fetch a non-existent/clearly invalid moderatorId (zero UUID)
  const nonExistentModeratorId = "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">;
  await TestValidator.error("not found for non-existent moderatorId")(async () => {
    await api.functional.discussionBoard.moderator.moderators.at(connection, {
      moderatorId: nonExistentModeratorId,
    });
  });

  // 5. (Soft-deleted moderator test omitted as there is no supported API)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the admin's ability to update a moderator's status (active, revoked, suspended) and revocation timestamp.
 *
 * Scenario:
 * 1. Register a new admin account.
 * 2. Register a new moderator, assigned by the above admin.
 * 3. As admin, update moderator status to 'suspended'. Check result.
 * 4. As admin, update status to 'active'. Check result.
 * 5. As admin, set status to 'revoked' with a revocation timestamp. Check result.
 * 6. Attempt update as the moderator (insufficient privilege); expect error.
 * 7. Attempt to update with invalid data (invalid status); expect error.
 * 8. Attempt to update with missing required field (status omitted); expect validation error.
 */
export async function test_api_admin_update_moderator_status_and_assignment(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword!1";
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResp);

  // 2. Register moderator (assigned_by_admin_email set to admin's)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModPassword#2";
  const moderatorResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: adminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResp);
  const moderatorId = moderatorResp.moderator_id;

  // 3. Switch connection to admin (by setting Authorization header to admin token)
  connection.headers = { ...connection.headers, Authorization: adminResp.setHeaders.Authorization };

  // 4. Admin sets moderator status to 'suspended'
  let result = await api.functional.discussionBoard.admin.moderators.update(connection, {
    moderatorId,
    body: {
      status: "suspended",
    } satisfies IDiscussionBoardModerator.IUpdate,
  });
  typia.assert(result);
  TestValidator.equals("moderator status=suspended")(result.status)("suspended");

  // 5. Admin sets status to 'active'
  result = await api.functional.discussionBoard.admin.moderators.update(connection, {
    moderatorId,
    body: { status: "active" },
  });
  typia.assert(result);
  TestValidator.equals("moderator status=active")(result.status)("active");

  // 6. Admin sets status to 'revoked' with a revocation timestamp
  const revokedAt = new Date().toISOString();
  result = await api.functional.discussionBoard.admin.moderators.update(connection, {
    moderatorId,
    body: {
      status: "revoked",
      revoked_at: revokedAt,
    },
  });
  typia.assert(result);
  TestValidator.equals("moderator status=revoked")(result.status)("revoked");
  TestValidator.equals("revoked_at matches")(result.revoked_at)(revokedAt);

  // 7. Attempt update as the moderator (insufficient privilege) -- should yield error
  connection.headers = { ...connection.headers, Authorization: moderatorResp.setHeaders.Authorization };
  await TestValidator.error("Only admin can update moderator")(() => api.functional.discussionBoard.admin.moderators.update(
    connection,
    {
      moderatorId,
      body: {
        status: "suspended",
      },
    },
  ));

  // 8. Switch back to admin for invalid data scenarios
  connection.headers = { ...connection.headers, Authorization: adminResp.setHeaders.Authorization };
  // Attempt to update with invalid status
  await TestValidator.error("Invalid status value")(async () => {
    await api.functional.discussionBoard.admin.moderators.update(connection, {
      moderatorId,
      body: {
        status: "not-a-valid-status",
      },
    });
  });

  // 9. Attempt to update with missing required field (status omitted)
  await TestValidator.error("Missing required status field")(async () => {
    await api.functional.discussionBoard.admin.moderators.update(connection, {
      moderatorId,
      // @ts-expect-error - purposely omitting required field
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IVoidSuccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidSuccess";

/**
 * Test a successful admin password change flow.
 *
 * This test validates that an admin can change their password using the correct workflow and that authentication is enforced:
 *
 * 1. Create a unique admin via the register endpoint and obtain access token (JWT set).
 * 2. Log in as this admin using the original password to verify credentials (fresh login, getting a new set of tokens).
 * 3. While authenticated, call the password change endpoint /auth/admin/password with the correct current password and a new password string.
 * 4. Confirm the response is a success (no error thrown, empty success payload).
 * 5. Attempt to log in using the old password: must fail (error thrown, indicating password update took effect).
 * 6. Attempt to log in using the new password: must succeed (get a fresh JWT on success).
 *
 * This tests core password-change logic, session/auth enforcement, and guards against credential misuse issues.
 */
export async function test_api_admin_password_change_success(connection: api.IConnection) {
  // 1. Register new admin (unique email)
  const email: string & tags.Format<"email"> = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);
  const signUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(signUp);
  TestValidator.equals("registered email" )(signUp.email)(email);

  // 2. Fresh login with original password
  const signIn1 = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(signIn1);
  TestValidator.equals("login ok")(signIn1.email)(email);

  // 3. Change password while authenticated with valid JWT
  const newPassword: string = RandomGenerator.alphaNumeric(14);
  const change = await api.functional.auth.admin.password.changePassword(connection, {
    body: {
      oldPassword: password,
      newPassword,
    } satisfies IDiscussionBoardAdmin.IChangePassword,
  });
  typia.assert(change);
  // IVoidSuccess is empty; success means no exception thrown and typia check passes

  // 4. Attempt login with OLD password (should fail)
  await TestValidator.error("old password should not work after change")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email,
        password,
      } satisfies IDiscussionBoardAdmin.ILogin,
    });
  });

  // 5. Attempt login with NEW password (should succeed)
  const signIn2 = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password: newPassword,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(signIn2);
  TestValidator.equals("login with new password")(signIn2.email)(email);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
