import type { IVoidSuccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidSuccess";

/**
 * Validate that changing admin password with an incorrect current password fails.
 *
 * This test covers the negative security workflow where an admin attempts to change their password but supplies the wrong current password. The scenario guards against credential brute-forcing and exposes whether the endpoint gives safe error signaling without modifying data.
 *
 * Testing strategy:
 * 1. Register a new admin and obtain a valid JWT (admin signup).
 * 2. Attempt to change the password using an incorrect value for 'oldPassword' (the current password is different).
 * 3. Assert that an error is thrown (e.g., 400 or 401), and no password update occurs.
 * 4. Ensure the login with the original password still works after the failed attempt (password not changed by mistake).
 */
export async function test_api_admin_password_change_invalid_current_password(
  connection: api.IConnection,
) {
  // 1. Register new admin
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = typia.random<string & tags.Format<"password">>();
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Attempt to change password using incorrect oldPassword
  const wrongOldPassword: string = password + "X";
  const newPassword: string = typia.random<string & tags.Format<"password">>();
  TestValidator.error("Changing with wrong current password should fail")(
    async () => {
      await api.functional.auth.admin.password.changePassword(connection, {
        body: {
          oldPassword: wrongOldPassword,
          newPassword,
        } satisfies IDiscussionBoardAdmin.IChangePassword,
      });
    },
  );

  // 3. Ensure we can still log in with original password (proves password was not changed)
  const relogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(relogin);
  TestValidator.equals("same admin account after failed password change")(relogin.email)(admin.email);
}

