/**
 * Validate enforcement of password policy during admin password change attempts.
 *
 * This test verifies that if the new password provided by an authenticated administrator does not meet the system's complexity or minimum length requirements (e.g., '123'), the password change is rejected. Furthermore, after this failed attempt:
 * - Login with the invalid new password must fail.
 * - Login with the original password must still succeed.
 *
 * Steps:
 * 1. Register a new admin (random email, policy-compliant initial password).
 * 2. Login to obtain JWT/auth (required for password change endpoint).
 * 3. Attempt to change password using correct current password but invalid new password ('123').
 * 4. Ensure the password change operation fails due to validation.
 * 5. Attempt login with the invalid new password; must fail.
 * 6. Attempt login with the original password; must still succeed.
 */
export async function test_api_admin_password_change_invalid_new_password_format(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const oldPassword = RandomGenerator.alphaNumeric(10);
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: oldPassword,
    },
  });
