  // 2. Login to get JWT/session
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: oldPassword,
    },
  });
  typia.assert(loginResponse);

  // 3. Attempt password change with invalid new password ('123')
  const invalidPassword = "123";
  await TestValidator.error("invalid new password policy rejected")(() =>
