 *
 * 1. Create a new external authentication log entry as admin (dependency step) with valid data.
 * 2. Update specific fields (such as auth_channel, error_code, error_message, discussion_board_member_id) using the update API; verify that only provided fields are changed and the rest remain untouched.
 * 3. Assert that the returned log reflects updated values, unchanged fields retain their prior values, and updated_at is bumped.
 * 4. Attempt to update a non-existent external authentication log entry, expect error.
 * 5. [Optional] (If soft-delete is supported) Attempt to update a deleted log entry and expect error or denial.
 */
export async function test_api_external_auth_log_update_metadata_and_audit(connection: api.IConnection) {
