import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailLog";
import type { IPageIDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardEmailLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and paginating outgoing email logs as an admin.
 *
 * This test confirms that an admin can use multiple filters (recipient, type, status, date range) to query outgoing email logs, with correct pagination, and verifies that soft-deleted records are excluded. It also covers handling of malformed input producing errors. Only actual API/DtOs/fields are used, following type safety and E2E conventions.
 *
 * Steps:
 * 1. Setup test data: Use dependency endpoint to create several email logs with varied recipient, type, status, and send time values.
 * 2. Perform search queries:
 *    - Filter by recipient_email (expect only that recipient)
 *    - Filter by email_type and delivery_status (expect logs matching both)
 *    - Filter by sent_at date range (expect logs in range)
 *    - Paginate results (validate limit/page and correct entries returned)
 * 3. Confirm soft-deleted records are never included
 * 4. Test error case: malformed filter input (invalid page number)
 */
export async function test_api_email_logs_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Setup test data: create sample email logs
  const recipientEmails = [
    typia.random<string & tags.Format<"email">>(),
    typia.random<string & tags.Format<"email">>()
  ];
  const types = ["verification", "notification", "password_reset"];
  const statuses = ["SENT", "DELIVERED", "FAILED"];
  const now = new Date();

  // Create several diverse logs
  const createdLogs = await Promise.all(
    ArrayUtil.repeat(10)((index: number) =>
      (async () => {
        const email_type = RandomGenerator.pick(types);
        const delivery_status = RandomGenerator.pick(statuses);
        const sent_at = new Date(now.getTime() - index * 3600 * 1000).toISOString();
        const recipient_email = RandomGenerator.pick(recipientEmails);
        const subject = RandomGenerator.alphaNumeric(12);
        const log = await api.functional.discussionBoard.admin.emailLogs.create(connection, {
          body: {
            recipient_email,
            email_type,
            subject,
            sent_at,
            delivery_status,
          } satisfies IDiscussionBoardEmailLog.ICreate,
        });
        typia.assert(log);
        return log;
      })()
    )
  );

  // 2a. Search by recipient_email
  const testRecipient = recipientEmails[0];
  const resultByRecipient = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      recipient_email: testRecipient,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(resultByRecipient);
  TestValidator.predicate("results match recipient")(
    resultByRecipient.data.every((item) => item.recipient_email === testRecipient)
  );

  // 2b. Search by both email_type and delivery_status
  const testType = types[0];
  const testStatus = statuses[0];
  const typeStatusResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      email_type: testType,
      delivery_status: testStatus,
    },
  });
  typia.assert(typeStatusResult);
  TestValidator.predicate("results match type and status")(
    typeStatusResult.data.every((item) => item.email_type === testType && item.delivery_status === testStatus)
  );

  // 2c. Search by sent_at date range (last 6 hours)
  const fromDate = new Date(now.getTime() - 6 * 3600 * 1000).toISOString();
  const toDate = now.toISOString();
  const dateRangeResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate,
    },
  });
  typia.assert(dateRangeResult);
  TestValidator.predicate("results within date range")(
    dateRangeResult.data.every((item) => item.sent_at >= fromDate && item.sent_at <= toDate)
  );

  // 2d. Pagination: page=1, limit=2, should return 0, 1, or 2 entries
  const paged = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.predicate("pagination respected")(paged.data.length <= 2);

  // 3. Confirm soft-deleted records excluded (deleted_at must be null/absent)
  TestValidator.predicate("no soft-deleted logs")(
    paged.data.every((item) => !("deleted_at" in item) || item.deleted_at === null)
  );

  // 4. Error case: malformed filter input (e.g. negative page)
  await TestValidator.error("invalid page rejects")(
    async () => {
      await api.functional.discussionBoard.admin.emailLogs.search(connection, {
        body: {
          page: -1,
        },
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IStd } from "@ORGANIZATION/PROJECT-api/lib/structures/IStd";

/**
 * E2E test for member password change with valid and invalid credentials and status cases.
 *
 * This test validates the following scenarios:
 * 1. Successful password change with correct old password
 * 2. Failed password change with incorrect old password
 * 3. Failed password change with weak new password
 * 4. Failed password change when member account is suspended or withdrawn
 *
 * Steps:
 * 1. Register a new member (generating a unique email/password/nickname)
 * 2. Authenticate as the member and establish session
 * 3. Change password with correct old password → expect success, check confirmation
 * 4. Attempt to change password with wrong old password → expect runtime error
 * 5. Attempt to change password with weak/empty new password → expect runtime error (validation fail)
 * 6. Change member status (as admin) to suspended and withdrawn; after each, try password change → expect runtime error (permission/access denied)
 */
export async function test_api_member_password_change_with_valid_and_invalid_credentials(connection: api.IConnection) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(10);
  const nickname = RandomGenerator.name();
  const signUpRes = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password, nickname } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(signUpRes);
  TestValidator.equals("member email matches")(signUpRes.member.email)(email);
  TestValidator.equals("member nickname matches")(signUpRes.member.nickname)(nickname);

  // 2. Log in to establish session
  const loginRes = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(loginRes);

  // 3. Change password with correct old password
  const newPassword = RandomGenerator.alphaNumeric(15);
  const changeOk = await api.functional.auth.member.password.changePassword(connection, {
    body: { old_password: password, new_password: newPassword } satisfies IDiscussionBoardMember.IChangePassword,
  });
  typia.assert(changeOk);
  TestValidator.equals("confirm password change success")(changeOk.ok)(true);

  // Can login with the new password
  const reloginRes = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password: newPassword } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(reloginRes);
  TestValidator.equals("member id retained after pw update")(loginRes.member.id)(reloginRes.member.id);

  // 4. Attempt to change password with wrong old password (should fail)
  await TestValidator.error("changing pw with bad old pw fails")(async () => {
    await api.functional.auth.member.password.changePassword(connection, {
      body: { old_password: "incorrectpw", new_password: RandomGenerator.alphaNumeric(12) } satisfies IDiscussionBoardMember.IChangePassword,
    });
  });

  // 5. Attempt to change password with weak/empty new password (should fail)
  await TestValidator.error("change pw with empty new password fails")(async () => {
    await api.functional.auth.member.password.changePassword(connection, {
      body: { old_password: newPassword, new_password: "" } satisfies IDiscussionBoardMember.IChangePassword,
    });
  });

  // 6. Update member status to suspended, then try pw change (should fail)
  const adminStatusList = ["suspended", "withdrawn"];
  for (const status of adminStatusList) {
    const updateRes = await api.functional.discussionBoard.admin.members.update(connection, {
      memberId: loginRes.member.id,
      body: { status } satisfies IDiscussionBoardMember.IUpdate,
    });
    typia.assert(updateRes);
    TestValidator.equals(`member status updated to ${status}`)(updateRes.status)(status);
    await TestValidator.error(`pw change blocked when member is ${status}`)(async () => {
      await api.functional.auth.member.password.changePassword(connection, {
        body: { old_password: newPassword, new_password: RandomGenerator.alphaNumeric(16) } satisfies IDiscussionBoardMember.IChangePassword,
      });
    });
  }
}

