import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate admin-driven moderator registration (success & duplicate error).
 *
 * This test validates both the success path for creating a moderator as an admin, and the error path for attempting to register a moderator with a duplicate email. It ensures RBAC enforcement, unique constraint validation, session token issuance, and proper audit trails.
 *
 * Steps:
 * 1. Log in as an admin with valid credentials (needed for RBAC and as 'assigned_by_admin_email').
 * 2. Register a new moderator by calling the moderator signUp API with unique credentials, using the admin email for assignment.
 * 3. Verify the response includes moderator info (with unique moderator_id and email), status, assignment timestamp, a JWT token, and setHeaders with Authorization.
 * 4. Attempt to register a moderator again with the same email, expecting a failure (HTTP 409 or business logic error) due to unique email constraint. The error path should throw and be asserted.
 * 5. Confirm all steps do not leak tokens except via appropriate response headers, and that audit/job-trail properties are present in the response bodies as required.
 */
export async function test_api_moderator_registration_and_duplicate_email_error(
  connection: api.IConnection,
) {
  // Step 1: Admin login
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string & tags.Format<"password"> = RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">;
  const adminLoginInput: IDiscussionBoardAdmin.ILogin = {
    email: adminEmail,
    password: adminPassword,
  };
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, { body: adminLoginInput });
  typia.assert(adminAuth);
  TestValidator.equals("admin email matches")(adminAuth.email)(adminEmail);

  // Step 2: Register a new moderator with unique email
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(10);
  const moderatorSignUp: IModerator.SignUp = {
    email: moderatorEmail,
    password: moderatorPassword,
    assigned_by_admin_email: adminEmail,
  };
  const modResponse = await api.functional.auth.moderator.register.signUp(connection, { body: moderatorSignUp });
  typia.assert(modResponse);
  TestValidator.equals("moderator email matches")(modResponse.email)(moderatorEmail);
  TestValidator.equals("has moderator_id")(typeof modResponse.moderator_id)("string");
  TestValidator.predicate("has JWT token")(!!modResponse.token);
  TestValidator.equals("Authorization header present")(typeof modResponse.setHeaders.Authorization)("string");
  TestValidator.predicate("has assigned_at timestamp")(!!modResponse.assigned_at);
  TestValidator.equals("moderator status active")(modResponse.status)("active");

  // Step 3: Attempt duplicate moderator registration
  await TestValidator.error("duplicate email registration fails")(async () => {
    await api.functional.auth.moderator.register.signUp(connection, {
      body: {
        email: moderatorEmail,
        password: RandomGenerator.alphaNumeric(12),
        assigned_by_admin_email: adminEmail,
      },
    });
  });
}

