 *
 * This test verifies both successful and unsuccessful moderator login attempts and ensures audit log behaviors are correct (as far as can be implemented).
 *
 * Business Context:
 * - Moderators must be assigned by an admin, unique by email, and registered as active to login.
 * - Authorizing login issues a JWT token for active accounts.
 * - Login should fail for incorrect passwords, non-existent accounts, or if the moderator's status is not active (if supported).
 * - All attempts should update audit logs; however, direct verification of logs is out of scope unless API is available.
 *
 * Test Steps:
 * 1. Register a valid moderator account using a randomly generated email/password and admin assignment.
 * 2. Attempt successful login with the correct email/password.
 *     - Verify a JWT token and setHeaders come back in response.
 *     - Check that the moderator_id and email match registration.
 * 3. Attempt login with the same email but an incorrect password.
 *     - Ensure authentication fails with an error (catch by TestValidator.error).
 * 4. Attempt login with a random non-existent email (formatted as valid email).
 *     - Ensure authentication fails due to not-found and an error is raised.
 * 5. Future: If moderator status adjustment is available, change status to suspended/revoked and test those errors.
 */
export async function test_api_moderator_login_success_and_status_failure(connection: api.IConnection) {
  // 1. Register a valid moderator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const password = "TestPwd-1234";
  const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password
    } satisfies IModerator.SignUp
  });
  typia.assert(signUpResp);
  TestValidator.equals("moderator email echoed")(signUpResp.email)(moderatorEmail);
  TestValidator.equals("moderator status should be active")(signUpResp.status)("active");
  TestValidator.predicate("JWT returned")(typeof signUpResp.token === "string" && signUpResp.token.length > 10);
  TestValidator.predicate("JWT setHeaders has Authorization")(!!signUpResp.setHeaders?.Authorization);

  // 2. Successful login
  const signInResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password
    } satisfies IModerator.SignIn
  });
  typia.assert(signInResp);
