/**
 * Validate that an admin can successfully retrieve the full details of a policy change log entry by its ID (policyChangeLogId).
 *
 * This test serves to ensure that the audit logging mechanism for administrative policy/config changes in the discussion board is reliable and comprehensive.
 *
 * The procedure involves two main steps:
 * 1. Preparation: Create a new policy change log entry via the admin-only API to ensure a valid and fresh log record exists
 * 2. Retrieval: Retrieve this created log using its ID, and validate that all audit fields (i.e., actor_admin_id, before/after values, change_reason, field lineage) as well as general metadata (ID, timestamps, etc) match what was just written
 *
 * Verifies:
 * - that only admin can access this endpoint (precondition: only admin API functions are available)
 * - that the returned change log record includes all fields as specified in IDiscussionBoardPolicyChangeLog
 * - that created_at and all audit fields are persisted and returned accurately
 */
export async function test_api_policy_change_log_detail_access_by_admin(connection: api.IConnection) {
  // 1. Create a new policy change log entry (as admin)
  const newPolicyChangeLogBody: IDiscussionBoardPolicyChangeLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    policy_namespace: "moderation",
    target_table: "discussion_board_settings",
    target_field: "max_report_count",
    previous_value: "5",
    new_value: "10",
    change_reason: "Policy update as per compliance review."
  };
  const createdLog: IDiscussionBoardPolicyChangeLog = await api.functional.discussionBoard.admin.policyChangeLogs.create(connection, {
    body: newPolicyChangeLogBody
  });
