  const retrieved: IDiscussionBoardPolicyChangeLog = await api.functional.discussionBoard.admin.policyChangeLogs.at(connection, {
    policyChangeLogId: createdLog.id
  });
  typia.assert(retrieved);

  // 3. Field-by-field equality assertions
  TestValidator.equals("id matches")(retrieved.id)(createdLog.id);
  TestValidator.equals("actor_admin_id matches")(retrieved.actor_admin_id)(createdLog.actor_admin_id);
  TestValidator.equals("policy_namespace matches")(retrieved.policy_namespace)(createdLog.policy_namespace);
  TestValidator.equals("target_table matches")(retrieved.target_table)(createdLog.target_table);
  TestValidator.equals("target_field matches")(retrieved.target_field)(createdLog.target_field);
  TestValidator.equals("previous_value matches")(retrieved.previous_value)(createdLog.previous_value);
  TestValidator.equals("new_value matches")(retrieved.new_value)(createdLog.new_value);
  TestValidator.equals("change_reason matches")(retrieved.change_reason)(createdLog.change_reason);
  TestValidator.predicate("created_at exists")(typeof retrieved.created_at === "string" && retrieved.created_at.length > 0);
}

