import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a moderator can search, paginate, and filter post metrics with complex filters.
 *
 * This test covers the scenario where a moderator needs to analyze engagement and compliance
 * across discussion board posts. It verifies the ability to perform advanced search using count
 * filters (views, comments, votes, reports), activity recency, and reference targeting, and to
 * receive paginated results with correct metadata.
 *
 * Steps:
 * 1. Prepare realistic metric data. If necessary, insert several metrics (mock or via fixtures),
 *    each with varying counts/fields to enable testing of the different filters. For the purpose
 *    of this test, randomly generate at least three distinct metrics—one with high view/comment/upvote
 *    counts, one with high reports, and another as a recent/low-activity entry. Use varied
 *    last_activity_at and created_at times for range filtering.
 * 2. As moderator, search for metrics where views_count_min is set above the lowest but below the
 *    highest, and limit to one result per page. Check that the paginated response only contains
 *    expected records and metadata.
 * 3. Search with last_activity_from set to filter only recent metrics.
 * 4. Search for metrics of a particular post by random post_id, then confirm all returned metrics
 *    are for that post.
 * 5. Attempt edge-case filtering—e.g., views_count_max lower than min, or non-existent post reference,
 *    and confirm that the API returns an empty data array and correct pagination info.
 * 6. Validate that all output records conform to IDiscussionBoardPostMetric type, and the pagination
 *    object is present and accurate for the filters applied.
 */
export async function test_api_post_metrics_search_with_complex_filters_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Generate three metrics with distinct field values for comprehensive filter testing
  // In a real environment, you would persist these. Here, we build them to use their fields for queries.
  const metrics = [
    {
      id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      views_count: 200,
      comments_count: 35,
      votes_up_count: 50,
      votes_down_count: 3,
      reports_count: 1,
      last_activity_at: new Date(Date.now() - 72 * 60 * 60 * 1000).toISOString(),
      created_at: new Date(Date.now() - 10 * 24 * 60 * 60 * 1000).toISOString(),
      updated_at: new Date(Date.now() - 71 * 60 * 60 * 1000).toISOString(),
    },
    {
      id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      views_count: 10,
      comments_count: 2,
      votes_up_count: 1,
      votes_down_count: 0,
      reports_count: 0,
      last_activity_at: new Date(Date.now() - 10 * 60 * 60 * 1000).toISOString(),
      created_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(),
      updated_at: new Date(Date.now() - 9 * 60 * 60 * 1000).toISOString(),
    },
    {
      id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      views_count: 55,
      comments_count: 12,
      votes_up_count: 27,
      votes_down_count: 0,
      reports_count: 8,
      last_activity_at: new Date(Date.now() - 60 * 60 * 1000).toISOString(),
      created_at: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString(),
      updated_at: new Date(Date.now() - 59 * 60 * 1000).toISOString(),
    },
  ];
  // (In a true isolated test, records should be inserted for deterministic filtering.)

  // Step 2: Search with views_count_min = 15, limit = 1
  const output_page1 = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: {
      views_count_min: 15,
      limit: 1,
      order_by: "views_count",
      order_dir: "desc",
    },
  });
  typia.assert(output_page1);
  TestValidator.predicate("should contain 1 record or 0 if filter too strict")(output_page1.data.length <= 1);
  TestValidator.equals("pagination.limit is 1")(output_page1.pagination.limit)(1);

  // Step 3: Search for only very recent metrics (past 2 hours)
  const output_recent = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: {
      last_activity_from: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString(),
      order_by: "last_activity_at",
      order_dir: "desc",
    },
  });
  typia.assert(output_recent);
  for (const metric of output_recent.data)
    if (metric.last_activity_at)
      TestValidator.predicate("metric is within last 2 hours")(new Date(metric.last_activity_at).getTime() >= Date.now() - 2 * 60 * 60 * 1000);

  // Step 4: Search for one of the test metric's post_id
  const target_post_id = metrics[0].discussion_board_post_id;
  const output_single = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: {
      discussion_board_post_id: target_post_id,
    },
  });
  typia.assert(output_single);
  for (const metric of output_single.data)
    TestValidator.equals("all metrics match post id")(metric.discussion_board_post_id)(target_post_id);

  // Step 5: Search edge-case: views_count_max < views_count_min (should be empty result)
  const output_edge = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: {
      views_count_min: 50,
      views_count_max: 30,
    },
  });
  typia.assert(output_edge);
  TestValidator.equals("edge case empty result")(output_edge.data.length)(0);

  // Step 6: Search for non-existent post_id
  const output_nonexistent = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(output_nonexistent);
  TestValidator.equals("non-existent post id yields empty array")(output_nonexistent.data.length)(0);

  // Step 7: Validate all result records conform to IDiscussionBoardPostMetric and pagination present
  for (const page of [output_page1, output_recent, output_single, output_edge, output_nonexistent]) {
    TestValidator.predicate("pagination current >= 1")(page.pagination.current >= 1);
    TestValidator.predicate("pagination.pages >= 1 if records found")(page.data.length === 0 || page.pagination.pages >= 1);
    for (const metric of page.data) typia.assert(metric);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the system's response to invalid or malformed filter criteria in post metrics search as a moderator.
 *
 * Business context:
 * Moderators need to be able to search and filter post metrics using a rich set of analytic filters (counts, ranges, date windows, ordering, pagination). However, the backend must enforce strong validation rules—rejecting malformed, nonsensical, or type-violating filter values with clear, actionable error feedback. This ensures dashboard stability, prevents data leaks, and helps moderators correct input errors quickly.
 *
 * Step-by-step process:
 * 1. Submit malformed requests using invalid data types or illogical filter value combinations over the patch endpoint `/discussionBoard/moderator/postMetrics`
 *     a) Non-numeric strings instead of integers in count range fields
 *     b) Provide a min value greater than the corresponding max (e.g., `comments_count_min = 10, comments_count_max = 5`)
 *     c) Provide invalid date string (malformed ISO-8601) in a date field
 *     d) last_activity_from after last_activity_to (reversed logic)
 * 2. For each malformed or logically invalid request, verify that the API responds with an error and does not return a valid result or silent success.
 * 3. Only basic runtime error occurrence is checked; the specific content of error messages is not validated.
 */
export async function test_api_post_metrics_search_invalid_filters(
  connection: api.IConnection,
) {
  // a) Non-numeric string in numeric fields
  await TestValidator.error("non-numeric view count fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        views_count_min: "not-a-number" as any,
      },
    });
  });

  // b) Min greater than max (illogical range)
  await TestValidator.error("min > max for comments_count fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        comments_count_min: 10,
        comments_count_max: 5,
      },
    });
  });

  // c) Malformed date string in datetime field
  await TestValidator.error("malformed last_activity_from date fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        last_activity_from: "not-a-date",
      },
    });
  });

  // d) last_activity_from later than last_activity_to (reversed logic)
  await TestValidator.error("from after to for last_activity_dates fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        last_activity_from: "2025-12-31T23:59:59.000Z",
        last_activity_to: "2025-01-01T00:00:00.000Z",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that moderator post metric search with unmatched filters returns empty results.
 *
 * This test simulates a moderator using the discussion board analytic dashboard to search for post metrics (such as engagement or report counts) with filters that do not match any existing metric row. In this scenario, a randomly generated UUID is used as the post filter, guaranteeing no matches in the dataset. The system is expected to handle this gracefully — returning an empty data array and proper pagination meta-information. This verifies both the robustness of the search endpoint in handling empty results and the accuracy of pagination data when there are zero matches.
 *
 * Step-by-step process:
 * 1. Generate a random (non-existent) post UUID to use as filter
 * 2. Construct a post metrics search request with this UUID as the filter
 * 3. Execute the /discussionBoard/moderator/postMetrics PATCH API as moderator
 * 4. Confirm that the API returns an empty data result set
 * 5. Verify that pagination metadata indicates zero records and page count of 0 or 1
 */
export async function test_api_post_metrics_search_for_no_results(
  connection: api.IConnection,
) {
  // 1. Generate a non-existent (random) discussion_board_post_id filter
  const nonExistentPostId = typia.random<string & tags.Format<"uuid">>();
  const filter: IDiscussionBoardPostMetric.IRequest = {
    discussion_board_post_id: nonExistentPostId,
  };

  // 2. Search post metrics with the non-existent post ID as moderator
  const output = await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
    body: filter,
  });
  typia.assert(output);

  // 3. Confirm empty search result
