 * 1. Create a sanction as a dependency setup (sanction must exist to update)
 * 2. Update selected mutable fields: reason_text, timeline_end, active
 * 3. Validate that updates are reflected and core audit fields (updated_at) changed
 * 4. Negative: Attempt update of a non-existent sanction (should error)
 * Note: Step to update a deleted record is omitted (no API support for deletion)
 */
export async function test_api_admin_user_sanction_update_success(connection: api.IConnection) {
  // 1. Create a sanction to update
  const createInput = {
    sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(),
    sanctioning_admin_id: typia.random<string & tags.Format<"uuid">>(),
    sanction_type: "temporary_ban",
