import api from "@ORGANIZATION/PROJECT-api";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the process of changing a moderator's password via the /auth/moderator/password endpoint.
 *
 * This comprehensive test covers:
 * 1. The successful pathway where a moderator changes their password and credentials work as expected.
 * 2. Attempting to change password with incorrect old password (should fail).
 * 3. Attempting to change password with a weak (invalid) new password (should fail).
 * 4. Ensuring authentication (JWT) is required for password change requests.
 * 5. (Skipped: Testing status change scenarios, as no endpoint is available for this.)
 *
 * The workflow includes:
 * 1. Registering a new admin.
 * 2. Logging in as the admin to obtain an authentication session.
 * 3. Registering a new moderator account (using admin privileges).
 * 4. Logging in as that moderator to obtain a session/JWT.
 * 5. Successfully changing the password as moderator.
 * 6. Ensuring login fails with the old password and works with the new one.
 * 7. Failing to change password using incorrect old password.
 * 8. Failing to set a new password that is too weak (violating likely policy).
 */
export async function test_api_moderator_password_change_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegister);

  // 2. Log in as the admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(adminLogin);

  // 3. Register a new moderator using admin privileges
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorInitialPassword = RandomGenerator.alphaNumeric(20);
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorInitialPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 4. Log in as the newly created moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorInitialPassword,
    } satisfies IModerator.SignIn,
  });
  typia.assert(moderatorLogin);

  // 5. Successfully change moderator password
  const newModeratorPassword = RandomGenerator.alphaNumeric(22);
  const passwordChangeResp = await api.functional.auth.moderator.password.changePassword(connection, {
    body: {
      old_password: moderatorInitialPassword,
      new_password: newModeratorPassword,
    } satisfies IModerator.ChangePassword,
  });
  typia.assert(passwordChangeResp);
  TestValidator.predicate('password change success')(passwordChangeResp.success === true);

  // 6. Ensure moderator cannot login with old password
  await TestValidator.error('old password cannot be used for login')(async () => {
    await api.functional.auth.moderator.login.signIn(connection, {
      body: {
        email: moderatorEmail,
        password: moderatorInitialPassword,
      } satisfies IModerator.SignIn,
    });
  });

  // 7. Ensure moderator can login with new password
  const moderatorLoginNew = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: newModeratorPassword,
    } satisfies IModerator.SignIn,
  });
  typia.assert(moderatorLoginNew);
  TestValidator.equals('moderator id preserved after password change')(moderatorLogin.moderator_id)(moderatorLoginNew.moderator_id);
  TestValidator.equals('moderator email unchanged')(moderatorLogin.email)(moderatorLoginNew.email);

  // 8. Fail to change password using incorrect old password
  await TestValidator.error('incorrect old password fails')(async () => {
    await api.functional.auth.moderator.password.changePassword(connection, {
      body: {
        old_password: moderatorInitialPassword, // This is now invalid
        new_password: RandomGenerator.alphaNumeric(22),
      } satisfies IModerator.ChangePassword,
    });
  });

  // 9. Fail to set a too-weak password (likely fails basic policy)
  await TestValidator.error('weak/invalid new password rejected')(async () => {
    await api.functional.auth.moderator.password.changePassword(connection, {
      body: {
        old_password: newModeratorPassword,
        new_password: '123', // Too short/weak by usual policy
      } satisfies IModerator.ChangePassword,
    });
  });

  // Note: No API for moderator account revocation/disable is present, so status-change error scenario is skipped.
}

