import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate admin authentication and error handling for login attempts.
 *
 * This test covers both successful and failure scenarios for the /auth/admin/login endpoint:
 *
 * 1. Register a new admin account via the admin registration API.
 * 2. Log in as that admin; validate JWT issuance, admin identity fields, and header set.
 * 3. Log in again with the same credentials and confirm the process repeats and issues a new access token (admin identity matches registration).
 * 4. Attempt login with the correct email but wrong password: expect error and NO sensitive leakage.
 * 5. Attempt login with a non-existent admin email: should fail with access-denied style error (not "not found" leak).
 * 6. Attempt with inactive/suspended/revoked status is omitted (no API available for it).
 *
 * This function ensures the system never reveals if an email exists, and login flows comply with security & audit requirements.
 */
export async function test_api_admin_login_valid_and_invalid_credentials(connection: api.IConnection) {
  // 1. Register a new admin account for login tests
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword123!";
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(registration);

  // 2. Happy path: successful admin login
  const login1 = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(login1);
  TestValidator.equals("admin login email matches")(login1.email)(adminEmail);
  TestValidator.predicate("access token issued")(!!login1.access_token);
  TestValidator.predicate("refresh token issued")(!!login1.refresh_token);
  TestValidator.predicate("admin_id is present")(!!login1.admin_id);
  TestValidator.equals("admin_id matches registration")(login1.admin_id)(registration.admin_id);

  // 3. Login again to ensure new tokens and matching identity
  const login2 = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword }
  });
  typia.assert(login2);
  TestValidator.equals("repeat login email matches")(login2.email)(adminEmail);
  TestValidator.notEquals("access token re-issued")(login2.access_token)(login1.access_token);
  TestValidator.equals("admin_id remains consistent")(login2.admin_id)(registration.admin_id);

  // 4. Login with correct email but wrong password (should error)
  TestValidator.error("login fails with wrong password")(() =>
    api.functional.auth.admin.login.signIn(connection, {
      body: {
        email: adminEmail,
        password: "WrongPassword321!"
      }
    })
  );

  // 5. Login with a non-existent admin email should fail same way (no info leak)
  TestValidator.error("login fails with unknown email")(() =>
    api.functional.auth.admin.login.signIn(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "SomePassword987!"
      }
    })
  );

  // 6. Omitted: inactivation/suspension/revocation scenario (unsupported by available API)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IVoidSuccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidSuccess";

/**
 * Tests the admin logout process and session invalidation logic for /auth/admin/logout.
 *
 * This test verifies the following workflow:
 * 1. Register a new admin user via /auth/admin/register (dependency).
 * 2. Log in as the admin user via /auth/admin/login (dependency) to get valid JWTs.
 * 3. Perform /auth/admin/logout to end the admin session, assert response type is IVoidSuccess (no session data or tokens returned).
 * 4. After logout, attempt to access protected admin APIs with the previous JWT and confirm that access is denied (if the backend blacklists tokens, or otherwise check for stateless JWT policy).
 * 5. Attempt to logout again with the same (now-invalid) token and verify that the response is either a compliant IVoidSuccess or an error is handled gracefully, according to the API contract.
 * 6. (Audit log verification is omitted because there is no audit log API exposed in the SDK.)
 *
 * This test validates server-side token invalidation (if implemented), stateless JWT session handling, correct logout response, and graceful behavior on double logout attempts.
 */
export async function test_api_admin_logout_token_invalidation_and_audit(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegister);

  // 2. Login as admin to get tokens
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(adminLogin);

  // Save access token for later negative tests
  const savedAccessToken = adminLogin.access_token;

  // 3. Call /auth/admin/logout (should succeed)
  const logoutRes = await api.functional.auth.admin.logout.signOut(connection);
  typia.assert(logoutRes);

  // 4. Attempt to use the old JWT on a protected admin endpoint (simulate reuse: if stateless, may return IVoidSuccess, else may error)
  const logoutAgainConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: `Bearer ${savedAccessToken}`,
    },
  };
  await TestValidator.error("access with invalidated token is denied or gracefully handled")(
    async () => {
      await api.functional.auth.admin.logout.signOut(logoutAgainConnection);
    },
  );

  // 5. Attempt to logout again with the same (now-invalid) token
  await TestValidator.error("double logout with invalid token is rejected or compliant")(
    async () => {
      await api.functional.auth.admin.logout.signOut(logoutAgainConnection);
    },
  );

  // 6. (Audit log check omitted: no audit log endpoint available)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IValidateToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IValidateToken";

/**
 * Comprehensive validation of admin JWT token lifecycle and privilege handling via /auth/admin/validate.
 *
 * Business Purpose: To verify that the authentication system securely recognizes valid admin sessions, rejects tampered, expired, malformed, or revoked tokens, and enforces privilege checks based on admin status.
 *
 * Test Steps:
 * 1. Register a new admin account (required to ensure a unique valid subject).
 * 2. Log in with that account to obtain a fresh (valid/current) JWT token via access_token.
 * 3. Validate the fresh token using /auth/admin/validate; assert that it is valid and session data is correct.
 * 4. Attempt to validate various invalid token types:
 *    - Malformed: Broken structure (e.g., just a random string or incomplete JWT format)
 *    - Tampered: Corrupted signature (take valid token and flip a character in signature part)
 *    - Expired: (Cannot simulate expiry via API directly—describe this branch and skip code.)
 *    - Wrong claims: Valid JWT shape but e.g. different 'role' or altered subject (explain limitations if not possible)
 * 5. Simulate privilege enforcement: (Business rules call for checking suspended/revoked user status, but without an API to change admin status, skip this or describe what code would look like.)
 * 6. For each failed validation, ensure status field is not 'valid' and isValid is false; for real tokens assert isValid and status is 'valid' or equivalent.
 *
 * Outline edge-cases covered:
 * - Only implement what can be triggered via current API. If status manipulation or token expiry cannot be simulated, explain as comments.
 */
export async function test_api_admin_jwt_validation_active_and_inactive(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecureP@ss123";
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(registerResp);

  // 2. Admin login to issue a valid access token
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ILogin
  });
  typia.assert(loginResp);
  const validToken = loginResp.access_token;

  // 3. Validate a valid token
  const validValidation = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token: validToken } satisfies IValidateToken.Request
  });
  typia.assert(validValidation);
  TestValidator.predicate("valid token should be valid")(validValidation.isValid === true);
  TestValidator.equals("valid status")(validValidation.status)("valid");

  // 4a. Validate a malformed token (not even JWT structure)
  const malformedToken = "not.a.jwt";
  const malformedValidation = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token: malformedToken } satisfies IValidateToken.Request
  });
  typia.assert(malformedValidation);
  TestValidator.predicate("malformed token should be invalid")(malformedValidation.isValid === false);
  TestValidator.predicate("malformed non-valid status")(malformedValidation.status !== "valid");

  // 4b. Validate a tampered token (alter signature)
  // Take the JWT, split and mutate a char in signature
  const split = validToken.split(".");
  let tamperedToken = validToken;
  if (split.length === 3) {
    // Flip a character in the signature
    const sig = split[2];
    const mutatedSig = (sig.length > 0)
      ? sig.substring(0, sig.length - 1) + (sig[sig.length - 1] === "A" ? "B" : "A")
      : sig;
    tamperedToken = split[0] + "." + split[1] + "." + mutatedSig;
  }
  const tamperedValidation = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token: tamperedToken } satisfies IValidateToken.Request
  });
  typia.assert(tamperedValidation);
  TestValidator.predicate("tampered token invalid")(tamperedValidation.isValid === false);
  TestValidator.predicate("tampered non-valid status")(tamperedValidation.status !== "valid");

  // 4c. Expired token test cannot be performed because we cannot mint an expired JWT via API; skip.

  // 4d. Wrong claims test - if we could, e.g., mint a token with different role/subject. Not feasible with API, so skip but describe.

  // 5. Admin status suspended/revoked: No API for status change, so this cannot be simulated.

  // 6. All failed cases: status field should not be 'valid' and isValid===false (already checked above)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate successful search, advanced filtering, and pagination of discussion board post metrics as an admin.
 *
 * Business context: Admin dashboards and analytics tools need to filter and page through diverse post engagement metrics (views, comments, votes, reports, recency), often with advanced filtering and specific orderings. The test ensures search behaves correctly as real admins would use for monitoring and triage.
 *
 * Steps:
 * 1. Register a new admin, simulating a privileged dashboard user.
 * 2. Seed the system with multiple post metric records (at least 4), each tied to a unique post id and with deliberately varied counts for views, comments, votes, downvotes, reports, last activity, and creation times. This allows for meaningful filter exercises.
 * 3. Query post metrics (PATCH /discussionBoard/admin/postMetrics) with various advanced filters:
 *    - Filter by minimum and maximum view counts (views_count_min/max) to select a subset.
 *    - Filter by a specific post id to verify targeted search.
 *    - Filter by recency (last_activity_from/to) to select most/least recently active metrics.
 *    - Apply combinations of multiple filters (e.g., votes & recency & views) to confirm AND logic.
 *    - Order results by different keys (e.g., votes_up_count desc/asc), confirm result order matches params.
 *    - Test pagination: request a subset per page (limit, page), verify pagination info and non-overlapping pages.
 * 4. For each query, check:
 *    - Only metrics matching filters are returned (numeric and id constraints).
 *    - Sorting direction and field is respected.
 *    - Pagination info (current page, limit, records, pages) reflects expected state.
 *    - When using post_id or fully exclusive filters, empty result is possible and correctly paginated.
 * 5. Test several filter/sort/pagination combinations for breadth.
 *
 * Data cleanup is not required as test dataset is isolated by randomization. No emails or personal info are part of metric data.
 */
export async function test_api_post_metrics_search_success_advanced_filter_pagination(
  connection: api.IConnection,
) {
  // 1. Register admin and capture token
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "1234-Abcd"
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminRes);
  // Assign JWT - in most E2E infra, connection.headers.Authorization is set automatically
  connection.headers = { ...(connection.headers ?? {}), ...adminRes.setHeaders };

  // 2. Create several post metrics records with varied stats
  const generatedMetrics: IDiscussionBoardPostMetric[] = [];
  const now = new Date();
  for (let i = 0; i < 4; ++i) {
    // Offset time and vary stats for diversity
    const base = i * 100;
    const metric = await api.functional.discussionBoard.admin.postMetrics.create(connection, {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<'uuid'>>(),
        views_count: base + 120,
        comments_count: base + 10,
        votes_up_count: base + 7,
        votes_down_count: base + 2,
        reports_count: i,
        last_activity_at: new Date(now.getTime() - i * 24 * 60 * 60 * 1000).toISOString(),
      } satisfies IDiscussionBoardPostMetric.ICreate
    });
    typia.assert(metric);
    generatedMetrics.push(metric);
  }

  // 3. Advanced filter: min/max views
  {
    const minViews = 150;
    const maxViews = 320;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        views_count_min: minViews,
        views_count_max: maxViews,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("views_count filter matches")(row.views_count >= minViews && row.views_count <= maxViews);
    }
    // Coverage: All rows within this range
    TestValidator.equals("non-empty if matches exist")(filterRes.data.length > 0)(true);
  }

  // 4. Filter by specific post id
  {
    const targetMetric = generatedMetrics[0];
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        discussion_board_post_id: targetMetric.discussion_board_post_id
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.equals("exact post id match")(row.discussion_board_post_id)(targetMetric.discussion_board_post_id);
    }
    // Should find exactly 1 metric for this post
    TestValidator.equals("single match")(filterRes.data.length)(1);
  }

  // 5. Recency filter: last_activity_from
  {
    // Only pick most recent metric (i=0)
    const recentTS = generatedMetrics[0].last_activity_at!;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        last_activity_from: recentTS,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("recency filter")(row.last_activity_at! >= recentTS);
    }
  }

  // 6. Multi-filter (votes up + comments)
  {
    const mu = generatedMetrics[1].votes_up_count;
    const cm = generatedMetrics[1].comments_count;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        votes_up_count_min: mu,
        comments_count_min: cm,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("multi-filter and logic")(row.votes_up_count >= mu && row.comments_count >= cm);
    }
  }

  // 7. Order by votes_up_count asc
  {
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        order_by: "votes_up_count",
        order_dir: "asc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (let i = 1; i < filterRes.data.length; ++i) {
      TestValidator.predicate("ascending order")(filterRes.data[i-1].votes_up_count <= filterRes.data[i].votes_up_count);
    }
  }

  // 8. Pagination: 2 per page, page 1 then 2
  {
    const limit = 2;
    // Page 1
    const page1 = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        limit,
        page: 1,
        order_by: "views_count",
        order_dir: "desc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(page1);
    TestValidator.equals("page1.current")(page1.pagination.current)(1);
    TestValidator.equals("page1.limit")(page1.pagination.limit)(limit);
    TestValidator.predicate("page1 count <= limit")(page1.data.length <= limit);
    // Page 2
    const page2 = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        limit,
        page: 2,
        order_by: "views_count",
        order_dir: "desc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(page2);
    TestValidator.equals("page2.current")(page2.pagination.current)(2);
    TestValidator.equals("page2.limit")(page2.pagination.limit)(limit);
    // Pages do not overlap
    const ids1 = page1.data.map(x => x.id);
    const ids2 = page2.data.map(x => x.id);
    for (const id of ids1) {
      TestValidator.predicate("pagination does not overlap")(ids2.indexOf(id) === -1);
    }
  }

  // 9. Exclusive filter - no match
  {
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        views_count_min: 99999,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    TestValidator.equals("no matching rows")(filterRes.data.length)(0);
    TestValidator.equals("pagination for empty")(filterRes.pagination.records)(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate error responses from the post metric search endpoint when using invalid or out-of-bounds filters.
 *
 * This test ensures the API correctly rejects search queries with:
 * - Negative/inappropriate numeric bounds (e.g., negative counts)
 * - Invalid pagination (e.g., page < 1 or limit < 0)
 * - Ill-formatted UUIDs for ID filters
 *
 * It does **not** test non-existent fields, as those are prevented by TypeScript/type-level DTO constraints and can't be sent at runtime.
 *
 * Steps:
 * 1. Register a new admin to obtain authentication (privileged flow)
 * 2. Attempt post metric search with:
 *    - Negative views_count_min (should trigger validation error)
 *    - page = 0, limit = -10 (should trigger validation error)
 *    - Malformed UUID for discussion_board_post_id (should trigger validation error)
 * 3. For each invalid input, assert the API throws an error.
 */
export async function test_api_post_metrics_search_error_invalid_filters(connection: api.IConnection) {
  // 1. Register an admin for the privileged validation scenario
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "StrongPassword123!",
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  TestValidator.predicate("admin registration successful")(typeof adminAuth.admin_id === "string");
  TestValidator.predicate("access_token present")(typeof adminAuth.access_token === "string");
  // (SDK should automatically handle Auth; included here for clarity)
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 2. Attempt out-of-bounds / invalid filter requests
  // 2a. Negative views_count_min
  await TestValidator.error("negative views_count_min rejected")(() =>
    api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        views_count_min: -1,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    })
  );
  // 2b. Invalid pagination (page = 0, limit = -10)
  await TestValidator.error("invalid pagination rejected")(() =>
    api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        page: 0,
        limit: -10,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    })
  );
  // 2c. Malformed UUID for discussion_board_post_id
  await TestValidator.error("malformed discussion_board_post_id rejected")(() =>
    api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        discussion_board_post_id: "invalid-uuid",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate moderator access to retrieve post metrics details (analytics).
 *
 * This test covers the flow for a moderator to view all analytics for a specific post metric entry on the discussion board. It covers end-to-end setup: creates an admin, that admin registers a moderator, then seeds post metrics data tied to a post (using a fake UUID for the post, since post creation is not available here). It then logs in as the newly created moderator and retrieves that metrics record via the privileged moderator endpoint, asserting all fields are accurate and aligned with seed data.
 *
 * Steps:
 * 1. Register an admin (will be used to seed metrics and grant moderator).
 * 2. As admin, register a new moderator (capture email/pw, ensure RBAC setup).
 * 3. As admin, create a post metrics entity with known values. (Simulate post ID).
 * 4. As moderator, query details of the created post metric by ID.
 * 5. Assert all analytic/counter fields and post association fields match the values used in creation, and temporal/audit fields are present.
 */
export async function test_api_post_metrics_detail_success_as_moderator(connection: api.IConnection) {
  // 1. Register ADMIN
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassw0rd!";
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResp);

  // 2. Register MODERATOR as ADMIN
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "M0dTest!";
  const modResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(modResp);

  // 3. As ADMIN, create a metrics entity for a (simulated) post
  const simulatedPostId = typia.random<string & tags.Format<"uuid">>();
  const metricsSeed = {
    discussion_board_post_id: simulatedPostId,
