 * 2. With that admin, create a new post metrics record (for a new post) using the metrics creation endpoint, initializing all fields with known values.
 * 3. Update engagement statistics for that metrics record (views, votes, comments, etc.) and set a new timestamp for 'last_activity_at'.
 * 4. After update, verify that all intended fields are changed and that 'updated_at' has been updated while immutable metadata remains consistent. Assert that 'created_at' is not changed, 'id' is the same, and the values for updated fields match exactly the submitted ones.
 * 5. Verify that fields not updated retain their prior values.
 */
export async function test_api_post_metrics_update_success_and_audit(connection: api.IConnection) {
  // 1. Register new admin and set connection for privilege use
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "autobeTest!234";

  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // Set admin's Authorization in connection
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth.setHeaders.Authorization,
  };

  // 2. Create a post metric entity with known values
  const postId = typia.random<string & tags.Format<"uuid">>();
  const initialBody: IDiscussionBoardPostMetric.ICreate = {
    discussion_board_post_id: postId,
    views_count: 100,
    comments_count: 5,
    votes_up_count: 3,
    votes_down_count: 1,
    reports_count: 0,
    last_activity_at: new Date().toISOString(),
  };
  const createdMetric = await api.functional.discussionBoard.admin.postMetrics.create(connection, {
    body: initialBody,
  });
  typia.assert(createdMetric);
  TestValidator.equals("initial metrics created")(
    {
      discussion_board_post_id: postId,
      views_count: 100,
      comments_count: 5,
      votes_up_count: 3,
      votes_down_count: 1,
      reports_count: 0,
    }
  )({
    discussion_board_post_id: createdMetric.discussion_board_post_id,
    views_count: createdMetric.views_count,
    comments_count: createdMetric.comments_count,
    votes_up_count: createdMetric.votes_up_count,
    votes_down_count: createdMetric.votes_down_count,
    reports_count: createdMetric.reports_count,
  });

  // 3. Update engagement fields and increment last_activity_at
  const updateBody: IDiscussionBoardPostMetric.IUpdate = {
    views_count: 145,
    comments_count: 8,
    votes_up_count: 5,
    votes_down_count: 2,
    reports_count: 1,
    last_activity_at: new Date(Date.now() + 10000).toISOString(),
  };

  // Save old audit fields for comparison
  const previousUpdatedAt = createdMetric.updated_at;
  const previousCreatedAt = createdMetric.created_at;
  const updatedMetric = await api.functional.discussionBoard.admin.postMetrics.update(connection, {
    postMetricsId: createdMetric.id,
    body: updateBody,
  });
  typia.assert(updatedMetric);

  // 4. Assert updated fields and audit/versioning
  TestValidator.equals("id remains the same")(updatedMetric.id)(createdMetric.id);
  TestValidator.equals("post id remains the same")(updatedMetric.discussion_board_post_id)(createdMetric.discussion_board_post_id);
  TestValidator.equals("views_count updated")(updatedMetric.views_count)(145);
  TestValidator.equals("comments_count updated")(updatedMetric.comments_count)(8);
  TestValidator.equals("votes_up_count updated")(updatedMetric.votes_up_count)(5);
  TestValidator.equals("votes_down_count updated")(updatedMetric.votes_down_count)(2);
  TestValidator.equals("reports_count updated")(updatedMetric.reports_count)(1);
  TestValidator.equals("last_activity_at updated")(updatedMetric.last_activity_at)(updateBody.last_activity_at);
  TestValidator.equals("created_at remains unchanged")(updatedMetric.created_at)(previousCreatedAt);
  TestValidator.notEquals("updated_at incremented")(updatedMetric.updated_at)(previousUpdatedAt);
}

