    typia.assert(notification);
    return notification;
  }));

  // 3. Act as the guest: set the Authorization header for API requests
  const guestConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: guestAuthorization } };

  // 4. Notification retrieval: test filtering and pagination

  //   a. Retrieve all notifications for guest
  const allRes = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
    },
  });
  typia.assert(allRes);
  TestValidator.predicate("all notifications belong to eventTypes")(
    allRes.data.every(row => eventTypes.includes(row.event_type))
  );
  TestValidator.predicate("all notifications unread")(
    allRes.data.every(row => row.unread === true)
  );

  //   b. Event type filter: check each eventType returns only matching rows
  for (const eventType of eventTypes) {
    const r = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
      body: {
        recipient_role: "guest",
        recipient_id: guestId,
        event_type: eventType,
      },
    });
    typia.assert(r);
    TestValidator.predicate(`event_type: ${eventType}`)(
      r.data.every(row => row.event_type === eventType)
    );
  }

  //   c. Pagination test: limit and page
  const paged = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result size == 2")(paged.data.length)(2);
  TestValidator.equals("paged/limit meta")(paged.pagination.limit)(2);
  TestValidator.equals("paged/current meta")(paged.pagination.current)(1);

  //   d. Unread filter: all true
  const unreadRes = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
      unread: true,
    },
  });
  typia.assert(unreadRes);
  TestValidator.predicate("all notifications are unread")(
    unreadRes.data.every(row => row.unread === true)
  );
}

