/**
 * Validate negative-path guest notification search returns empty results when no data matches filters.
 *
 * This test ensures:
 *   - Guest authentication via /auth/guest/login, obtaining guest JWT for API calls
 *   - Search on /discussionBoard/guest/notifications endpoint using PATCH, with highly restrictive filters unlikely to match any notifications (e.g. event_type of a fictional/future name, unread: true, narrow date range)
 *   - Confirms the system handles empty-result search robustly:
 *       - output.data is an empty array
 *       - output.pagination.records is 0 (no results found)
 *       - output.pagination.pages is 0 or 1 (minimum)
 *       - All returned pagination metadata is sensible for empty set
 *
 * Steps:
 *   1. Authenticate as guest (simulate new client session, realistic user_agent and ip_address data)
 *   2. Issue PATCH request on /discussionBoard/guest/notifications with no-match filters
 *   3. Validate response type shape (typia.assert)
 *   4. Validate output.data.length === 0
 *   5. Validate output.pagination.records === 0
 *   6. Validate output.pagination.pages is 0 or 1
 *   7. Confirm pagination.current is as requested (default==1 or as set in filter)
 */
export async function test_api_guest_notification_search_no_results(
  connection: api.IConnection,
) {
  // 1. Authenticate as guest
  const guestAuth = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: `Mozilla/5.0 (compatible; E2ETestBot/${Date.now()})`,
      ip_address: "203.0.113.15",
    },
  });
  typia.assert(guestAuth);
  // Set Authorization header for guest
  connection.headers = {
    ...(connection.headers || {}),
    Authorization: guestAuth.setHeaders.Authorization,
  };

  // 2. Prepare no-match filter with types matching IDiscussionBoardNotification.IRequest (all types/tag intersection honored)
  const very_future_from = new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString() as string & tags.Format<"date-time">;
  const very_future_to = new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString() as string & tags.Format<"date-time">;
  const filter = {
    event_type: "future_event_xyz",
    recipient_role: "guest",
    unread: true,
    created_at_from: very_future_from,
    created_at_to: very_future_to,
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    recipient_id: null,
    related_entity_type: null,
  } satisfies IDiscussionBoardNotification.IRequest;

  // 3. Search for notifications as guest with negative filter
  const output = await api.functional.discussionBoard.guest.notifications.search(
    connection,
    { body: filter },
  );
  typia.assert(output);

  // 4. notifications should be empty
  TestValidator.equals("notifications empty array")(output.data.length)(0);

  // 5. No records found
  TestValidator.equals("notifications records=0")(output.pagination.records)(0);

  // 6. Pages should be 0 or 1
  TestValidator.predicate("pagination.pages is 0 or 1")(
    output.pagination.pages === 0 || output.pagination.pages === 1,
  );

  // 7. Requested page should match response metadata
  TestValidator.equals("pagination.current matches requested")(
    output.pagination.current
  )(filter.page);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
