/**
 * Validate member self-access to discussion board notification detail (happy path).
 *
 * Ensures a user who just registered (as a member) and is addressed in a notification
 * can retrieve the full notification details using the notification ID, validating all fields, including meta and unread status.
 * This asserts not only type schema compliance but also end-to-end linkage and security checks (recipient linkage).
 *
 * Workflow:
 * 1. Register new member (obtain memberId, auth token in session)
 * 2. As admin, create a notification addressed to the new member (member_id)
 * 3. As the member (with session), fetch the notification detail by ID
 * 4. Check that notification matches creation output (title, body, event_type, recipient linkage, unread=true, timestamps, etc.)
 *
 * This covers correct workflow and the integrity of notification ownership boundaries.
 */
export async function test_api_member_notification_detail_access_self_success(
  connection: api.IConnection,
) {
  // 1. Register a new member (receive public session)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberNickname = RandomGenerator.name();

  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "password1234!",
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);

  const memberId = session.member.id;

  // 2. Create notification to the above member as admin
  // (presumes connection has admin privilege or no auth required for notifications.create)
  // Use unique content for precise validation.
  const eventType = RandomGenerator.alphabets(8);
  const notifTitle = RandomGenerator.paragraph()(1);
  const notifBody = RandomGenerator.content()()();

  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: memberId,
      title: notifTitle,
      body: notifBody,
      event_type: eventType,
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notification);

  // 3. As the newly registered member, fetch the notification by its ID.
  // (JWT in session.setHeaders should link to this member)
  connection.headers = {
    ...connection.headers,
    ...session.setHeaders,
  };
  const detail = await api.functional.discussionBoard.member.notifications.at(connection, {
    notificationId: notification.id,
  });
  typia.assert(detail);

  // 4. Validate that all notification fields match creation and expectation
  TestValidator.equals("notification id matches")(detail.id)(notification.id);
  TestValidator.equals("recipient linkage matches: member_id")(detail.member_id)(memberId);
  TestValidator.equals("notification title matches")(detail.title)(notifTitle);
  TestValidator.equals("notification body matches")(detail.body)(notifBody);
  TestValidator.equals("event_type matches")(detail.event_type)(eventType);
  TestValidator.equals("unread is true for new notification")(detail.unread)(true);
  // Confirm non-membership fields are null or undefined (recipient exclusivity)
  TestValidator.equals("admin_id is null for member notification")(detail.admin_id)(null);
  TestValidator.equals("moderator_id is null for member notification")(detail.moderator_id)(null);
  TestValidator.equals("guest_id is null for member notification")(detail.guest_id)(null);
  // Timestamp/meta fields
  TestValidator.predicate("created_at valid iso")(!!Date.parse(detail.created_at));
  TestValidator.predicate("updated_at valid iso")(!!Date.parse(detail.updated_at));
}

