import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Verify that an admin account can fetch details of any notification regardless of recipient role.
 *
 * This test covers the following workflow:
 * 1. Admin registers and receives authentication (JWT/session) for subsequent API use.
 * 2. As admin, creates four notifications: one each assigned to a member, moderator, admin, and guest recipient (using proper mutually exclusive ID fields).
 * 3. For each created notification, fetches its details by id via the admin detail endpoint. Confirms:
 *    - All notification content (title, body, event_type, entity linkage fields) exactly matches creation,
 *    - The correct recipient _id key is set as intended and all others are null
 *    - unread flag is true
 *    - Creation and update timestamps are present
 * 4. Attempts to fetch a notification using a random/nonexistent id and verifies an error is thrown (basic negative-path check)
 */
export async function test_api_admin_notification_detail_access_success(connection: api.IConnection) {
  // 1. Register new admin and get authentication for API session
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signupResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signupResp);
  connection.headers = { ...(connection.headers ?? {}), ...signupResp.setHeaders };
  const adminId = signupResp.admin_id;

  // 2. Prepare four notifications with different recipient keys
  const recipientRoles = [
    { key: 'member_id',  label: 'member',    fakeId: typia.random<string & tags.Format<'uuid'>>() },
    { key: 'moderator_id', label: 'moderator', fakeId: typia.random<string & tags.Format<'uuid'>>() },
    { key: 'admin_id',   label: 'admin',     fakeId: adminId },
    { key: 'guest_id',   label: 'guest',     fakeId: typia.random<string & tags.Format<'uuid'>>() },
  ];
  const createdNotifications: { id: string; roleKey: string; expectedBody: any }[] = [];

  for (const role of recipientRoles) {
    // distinctly mark each notification content for validation
    const createBody = {
      [role.key]: role.fakeId,
      title: `AutoTest - ${role.label} - ${RandomGenerator.paragraph()(4)}`,
      body: RandomGenerator.content()(2)(30),
      event_type: 'autotest-event',
      related_entity_id: typia.random<string & tags.Format<'uuid'>>(),
      related_entity_type: 'autotest-entity-type',
    };
    const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
      body: createBody,
    });
    typia.assert(notification);
    createdNotifications.push({ id: notification.id, roleKey: role.key, expectedBody: createBody });
  }

  // 3. Fetch and validate each notification in detail by id
  for (const note of createdNotifications) {
    const fetched = await api.functional.discussionBoard.admin.notifications.at(connection, {
      notificationId: note.id,
    });
    typia.assert(fetched);
    TestValidator.equals(`event_type matches`)(fetched.event_type)(note.expectedBody.event_type);
    TestValidator.equals(`title matches`)(fetched.title)(note.expectedBody.title);
    TestValidator.equals(`body matches`)(fetched.body)(note.expectedBody.body);
    TestValidator.equals(`unread flag true`)(fetched.unread)(true);
    TestValidator.equals('related_entity_id matches')(fetched.related_entity_id)(note.expectedBody.related_entity_id);
    TestValidator.equals('related_entity_type matches')(fetched.related_entity_type)(note.expectedBody.related_entity_type);
    // Only the intended recipient key should be non-null; others null/undefined
    for (const key of ['member_id', 'moderator_id', 'admin_id', 'guest_id']) {
      if (key === note.roleKey)
        TestValidator.equals(`recipient: ${key} set`)((fetched as any)[key])(note.expectedBody[key]);
      else
        TestValidator.equals(`recipient: ${key} null/undefined`)((fetched as any)[key])(null);
    }
    TestValidator.predicate('created_at present')(!!fetched.created_at);
    TestValidator.predicate('updated_at present')(!!fetched.updated_at);
  }

  // 4. Negative: Attempt to fetch nonexistent notification, expect error
  await TestValidator.error('not found error thrown for bad id')(
    async () => {
      await api.functional.discussionBoard.admin.notifications.at(connection, {
        notificationId: typia.random<string & tags.Format<'uuid'>>(),
      });
    },
  );
}

