import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPlatformConfig";
import type { IPageIDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPlatformConfig";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validates admin search, filter, and pagination for platform configuration records.
 *
 * This test simulates an admin managing platform configuration and verifying advanced query capabilities via `/discussionBoard/admin/platformConfigs`:
 *   - Can search/filter by config_name (exact/partial), enabled status, description keywords, and date windows.
 *   - Validates that only matching records are returned for each filter scenario.
 *   - Confirms pagination works correctly (checks page, limit, total, page count, etc).
 *   - Asserts that audit trail and sensitive metadata fields are present on all results (id, config_name, config_value, enabled, version, description, created_at, updated_at, deleted_at).
 *   - Guarantees all API responses conform to schema, exposing all documented fields.
 *
 * Steps performed:
 * 1. Register a new admin account and authenticate (JWT automatically in connection context).
 * 2. As admin, create several distinct platform configuration records with varied config_name, enabled flag, descriptions, and timestamps.
 * 3. Exercise search endpoint using config_name, enabled (true/false), description keyword, and created_at window as filters.
 * 4. Assert each filter only returns matching configs.
 * 5. Validate pagination: correct page/limit mapping, result boundaries, page count, and total record estimation.
 * 6. For all result records, check inclusion/type of all required and audit/sensitive fields (including nullables).
 */
export async function test_api_platform_config_search_admin_access_with_various_filters(connection: api.IConnection) {
  // 1. Register new admin and authenticate
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16);
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);

  // 2. Create diverse platform configuration records
  const configs: IDiscussionBoardPlatformConfig[] = [];
  for (let i = 0; i < 5; ++i) {
    const rec = await api.functional.discussionBoard.admin.platformConfigs.create(connection, {
      body: {
        config_name: `feature_toggle_${i}`,
        config_value: RandomGenerator.alphaNumeric(10),
        enabled: i % 2 === 0,
        version: 1,
        description: i % 2 ? `Auxiliary Description ${i}` : `Important keyword ${i}`,
      },
    });
    typia.assert(rec);
    configs.push(rec);
  }

  // 3. Search: config_name filter (exact)
  const resultByName = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: { config_name: "feature_toggle_1" },
  });
  typia.assert(resultByName);
  TestValidator.predicate("config_name filter")(
    resultByName.data.every(r => r.config_name === "feature_toggle_1")
  );

  // 4. Search: enabled=true
  const resultEnabled = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: { enabled: true },
  });
  typia.assert(resultEnabled);
  TestValidator.predicate("enabled filter")(
    resultEnabled.data.every(r => r.enabled === true)
  );

  // 5. Search: description keyword (partial)
  const resultDescription = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: { description: "Important" },
  });
  typia.assert(resultDescription);
  TestValidator.predicate("description filter")(
    resultDescription.data.every(r => typeof r.description === "string" && r.description.includes("Important"))
  );

  // 6. Search: created_at date window
  const minTime = configs[1].created_at;
  const maxTime = configs[4].created_at;
  const resultDateRange = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: {
      created_from: minTime,
      created_to: maxTime,
    },
  });
  typia.assert(resultDateRange);
  TestValidator.predicate("created_at range filter")(
    resultDateRange.data.every(r => r.created_at >= minTime && r.created_at <= maxTime)
  );

  // 7. Pagination validation: page 2, limit 2
  const resultPaged = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(resultPaged);
  TestValidator.equals("pagination: result page 2 size 2")(resultPaged.data.length)(2);
  TestValidator.equals("pagination: current = 2")(resultPaged.pagination.current)(2);
  TestValidator.equals("pagination: limit = 2")(resultPaged.pagination.limit)(2);
  TestValidator.equals("pagination: total >= configs created")(
    resultPaged.pagination.records >= configs.length
  )(true);
  TestValidator.equals("pagination: page count")(
    resultPaged.pagination.pages
  )(
    Math.ceil(resultPaged.pagination.records / resultPaged.pagination.limit)
  );

  // 8. Check required and audit/sensitive metadata fields on all results
  for (const rec of resultPaged.data) {
    TestValidator.predicate("id is uuid")(
      typeof rec.id === "string" && rec.id.length > 0
    );
    TestValidator.predicate("config_name present")(
      typeof rec.config_name === "string"
    );
    TestValidator.predicate("config_value present")(
      typeof rec.config_value === "string"
    );
    TestValidator.predicate("enabled is boolean")(
      typeof rec.enabled === "boolean"
    );
    TestValidator.predicate("version is number")(
      typeof rec.version === "number"
    );
    TestValidator.predicate("description null or string")(
      typeof rec.description === "string" || rec.description === null || rec.description === undefined
    );
    TestValidator.predicate("created_at is ISO string")(
      typeof rec.created_at === "string" && rec.created_at.includes("T")
    );
    TestValidator.predicate("updated_at is ISO string")(
      typeof rec.updated_at === "string" && rec.updated_at.includes("T")
    );
    TestValidator.predicate("deleted_at is nullable ISO string")(
      rec.deleted_at === null || rec.deleted_at === undefined || (typeof rec.deleted_at === "string" && rec.deleted_at.includes("T"))
    );
  }
}

