  // Switch header to a dummy admin token just for test data setup
  const originalAuth = connection.headers?.Authorization;
  connection.headers = { ...(connection.headers ?? {}), Authorization: "Bearer admin-dummy-token" };
  const platformConfigs: IDiscussionBoardPlatformConfig[] = [];
  for (let i = 0; i < 6; ++i) {
