 * Validate successful creation of a discussion post by an authenticated admin with required and optional fields.
 *
 * This test covers:
 *   - Admin account creation and authentication context setup
 *   - Post creation with only required fields (title, body)
 *   - Post creation with all optional fields provided (category_id, attachments)
 *   - Post creation with attachments explicitly set to null
 *   - Validation that business fields match expectations, including status and UUID formats
 *
 * Step-by-step process:
 * 1. Register a new admin and get the issued access token for subsequent API calls.
 * 2. Create a post with only required fields; check all required properties and that optionals are omitted/null.
 * 3. Create a post with category_id and attachments specified; ensure the response reflects them.
 * 4. Create a post with attachments explicitly set to null (shows both "omitted" and explicit-null are handled).
 * 5. For each post, validate that title/body/status match input and policy; id and created_at are correctly formed.
 */
export async function test_api_post_creation_by_admin_valid_data(
  connection: api.IConnection,
) {
  // 1. Register an admin for authentication context
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPwd!123";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Add access token for admin privilege
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth.setHeaders.Authorization,
  };

  // 2. Minimal post creation (required fields only)
  const minPostInput = {
    title: RandomGenerator.paragraph()(1, 3).slice(0, 100),
    body: RandomGenerator.content()()().slice(0, 4000),
  } satisfies IDiscussionBoardPost.ICreate;
  const minPost = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: minPostInput,
  });
  typia.assert(minPost);
  TestValidator.equals("title")(minPost.title)(minPostInput.title);
  TestValidator.equals("body")(minPost.body)(minPostInput.body);
  TestValidator.predicate("status is 'active'")(minPost.status === "active");
  TestValidator.predicate("id is uuid")(/^[0-9a-fA-F\-]{36}$/.test(minPost.id));
  TestValidator.predicate("created_at is date-time")(/\d{4}-\d{2}-\d{2}T\d{2}:.+/.test(minPost.created_at));
  TestValidator.equals("category_id omitted or null")(
    typeof minPost.category_id === "undefined" || minPost.category_id === null
  )(true);
  TestValidator.equals("attachments omitted or null")(
    typeof minPost.attachments === "undefined" || minPost.attachments === null
  )(true);

  // 3. Post with all optional fields (category_id + attachments)
  // category_id is mocked by random UUID since API does not provide category creation
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const sampleAttachmentsArr = [
    "https://cdn.test.com/f/att1.jpg",
    "https://cdn.test.com/f/att2.png",
  ];
  const fullPostInput = {
    title: RandomGenerator.paragraph()(2, 4).slice(0, 100),
    body: RandomGenerator.content()()().slice(0, 4000),
    category_id: categoryId,
    attachments: JSON.stringify(sampleAttachmentsArr),
  } satisfies IDiscussionBoardPost.ICreate;
  const fullPost = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: fullPostInput,
  });
  typia.assert(fullPost);
  TestValidator.equals("title")(fullPost.title)(fullPostInput.title);
  TestValidator.equals("body")(fullPost.body)(fullPostInput.body);
  TestValidator.equals("category_id")(fullPost.category_id)(fullPostInput.category_id);
  TestValidator.equals("attachments")(fullPost.attachments)(fullPostInput.attachments);
  TestValidator.predicate("status is 'active'")(fullPost.status === "active");
  TestValidator.predicate("id is uuid")(/^[0-9a-fA-F\-]{36}$/.test(fullPost.id));
  TestValidator.predicate("created_at is date-time")(/\d{4}-\d{2}-\d{2}T\d{2}:.+/.test(fullPost.created_at));

  // 4. Post with attachments explicitly set to null
  const nullAttachmentsInput = {
    title: RandomGenerator.paragraph()(2, 4).slice(0, 100),
    body: RandomGenerator.content()()().slice(0, 4000),
    attachments: null,
  } satisfies IDiscussionBoardPost.ICreate;
  const nullAttachmentsPost = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: nullAttachmentsInput,
  });
  typia.assert(nullAttachmentsPost);
  TestValidator.equals("attachments is null")(
    typeof nullAttachmentsPost.attachments === "undefined" || nullAttachmentsPost.attachments === null
  )(true);
  TestValidator.equals("title")(nullAttachmentsPost.title)(nullAttachmentsInput.title);
  TestValidator.equals("body")(nullAttachmentsPost.body)(nullAttachmentsInput.body);
  TestValidator.predicate("status is 'active'")(nullAttachmentsPost.status === "active");
  TestValidator.predicate("id is uuid")(/^[0-9a-fA-F\-]{36}$/.test(nullAttachmentsPost.id));
  TestValidator.predicate("created_at is date-time")(/\d{4}-\d{2}-\d{2}T\d{2}:.+/.test(nullAttachmentsPost.created_at));
}

