/**
 * Validates that a member can update their own post within the allowed edit window,
 * and fails with an error if trying to update after the window expires.
 *
 * - Ensures all modifiable fields (title, body, category, attachments) are updated correctly
 * - Checks that updated_at is refreshed after edit
 * - After time window expires, verifies a further update is rejected
 * - Ensures edit rights are enforced by business policy
 *
 * Steps:
 * 1. Register a new member to obtain authentication context
 * 2. Create an initial discussion post as that member
 * 3. Update the post (change title, body, attachments) within the allowed time window
 * 4. Verify fields are updated and updated_at reflects the change
 * 5. Attempt to update after the allowed window and ensure rejection
 */
export async function test_api_member_post_update_success_within_time_window(connection: api.IConnection) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = "MyStrongPassword123!";
  const nickname = RandomGenerator.name();
  const regSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(regSession);
  TestValidator.predicate("registration returns JWT token")(!!regSession.token);

  // 2. Create a new post
  const createPostBody: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1).substring(0, 100),
    body: RandomGenerator.content()(1)().substring(0, 4000),
    attachments: JSON.stringify([
      RandomGenerator.alphaNumeric(8) + ".jpg"
    ])
  };
  const createdPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: createPostBody
  });
  typia.assert(createdPost);
  TestValidator.equals("created title matches")(createdPost.title)(createPostBody.title);
  TestValidator.equals("created body matches")(createdPost.body)(createPostBody.body);

  // 3. Update the post within the allowed edit window
  const updateInput: IDiscussionBoardPost.IUpdate = {
    title: RandomGenerator.paragraph()(1).substring(0, 100),
    body: RandomGenerator.content()(1)().substring(0, 4000),
    attachments: JSON.stringify([
      RandomGenerator.alphaNumeric(10) + ".pdf",
      RandomGenerator.alphaNumeric(8) + ".png"
    ])
  };
  const updatedPost = await api.functional.discussionBoard.member.posts.update(connection, {
    postId: createdPost.id,
    body: updateInput
  });
  typia.assert(updatedPost);
  TestValidator.equals("updated title matches")(updatedPost.title)(updateInput.title);
  TestValidator.equals("updated body matches")(updatedPost.body)(updateInput.body);
  TestValidator.notEquals("updated_at is changed")(updatedPost.updated_at)(createdPost.updated_at);

  // 4. Attempt to update after the window should expire (simulated for E2E)
  await TestValidator.error("should reject update after window expires")(
    async () => {
      await api.functional.discussionBoard.member.posts.update(connection, {
        postId: createdPost.id,
        body: {
          title: RandomGenerator.paragraph()(1).substring(0, 100)
        }
      });
    }
  );
}

