import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test that an admin can update any discussion board post, including system (audit) fields such as status for moderation purposes.
 *
 * Business context:
 * Ensures system administrators have full override and compliance powers for editing, moderating, or changing any post regardless of original author. This test covers editing all editable fields and system/moderation fields such as 'status'.
 *
 * Steps:
 * 1. Register a new admin (simulate platform bootstrap, obtain access token).
 * 2. As admin, create three posts with default status (simulate normal creation).
 * 3. Update each post as admin for various moderation cases:
 *    a. Edit content of an 'active' post (title/body fields)
 *    b. Toggle 'status' of posts between 'active'/'hidden'/'flagged' to verify admin audit control
 *    c. For each update, assert that the update applied and 'updated_at' is changed
 */
export async function test_api_admin_update_any_post_fields_and_audit(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create three posts as admin with default status
  const statuses = ["active", "hidden", "flagged"];
  const createdPosts = await ArrayUtil.asyncMap(statuses)(async (initialStatus) => {
    // New post with random title/body, attachments null
    const created = await api.functional.discussionBoard.admin.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(1).substring(0, 100),
        body: RandomGenerator.content()()(1).substring(0, 4000),
        attachments: null,
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(created);

    // If starting status is NOT active, immediately update it to test admin system override
    let updated = created;
    if (initialStatus !== "active") {
      updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: created.id,
        body: {
          status: initialStatus,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin can set post status")(updated.status)(initialStatus);
      TestValidator.predicate("updated_at is updated")(updated.updated_at !== created.updated_at);
    }
    return updated;
  });

  // 3. For each post, perform admin updates on content and system field (status), then validate
  for (const post of createdPosts) {
    // (a) Edit title/body for 'active' scenario
    if (post.status === "active") {
      const newTitle = RandomGenerator.paragraph()(1).substring(0, 100);
      const newBody = RandomGenerator.content()()(1).substring(0, 4000);
      const updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: post.id,
        body: {
          title: newTitle,
          body: newBody,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin updated title")(updated.title)(newTitle);
      TestValidator.equals("admin updated body")(updated.body)(newBody);
      TestValidator.predicate("updated_at reflects change")(updated.updated_at !== post.updated_at);
    }
    // (b) Toggle moderation/status fields
    else {
      const toggleTo = post.status === "hidden" ? "active" : "hidden";
      const updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: post.id,
        body: {
          status: toggleTo,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin toggled status")(updated.status)(toggleTo);
      TestValidator.predicate("updated_at reflects status change")(updated.updated_at !== post.updated_at);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that a member can perform a soft (logical) delete on their own post within the allowed time window.
 *
 * - Register a new member to be the author of the post.
 * - Authenticate as that member using the issued JWT after registration (auto in connection headers).
 * - Create a new post as this member with valid title, body, and (optionally) category/attachments.
 * - Delete the post with the corresponding API (soft delete, so should not be physical removal).
 * - After deletion, the post's deleted_at field in the database should be set and status changed, but post data is still retained (not returned by searches).
 * - Attempt to delete the same post again: should trigger an error or idempotent confirmation (test API and error handling).
 * - Validate that normal post search/list endpoints no longer return this post.
 * - Test that audit trail of deletion is preserved (cannot directly check audit log if no API, but deletion is verifiable via post details if accessible).
 * - Confirm that another member cannot delete others' posts (if feasible with current endpoints).
 *
 * Steps:
 * 1. Register a new member (acquires authentication context).
 * 2. Create a post as that member.
 * 3. Delete the post within allowed window (soft delete with DELETE endpoint).
 * 4. Fetch the post directly if endpoint available: expect deleted_at set and status updated (if not available, skip).
 * 5. Try to delete again: expect error or clear API response indicating no further action.
 * 6. (Optional/if endpoint available) List/search for posts in normal user context and verify soft-deleted post is omitted.
 * 7. (Optional) Register another member and verify they cannot delete the original member's post (test as per available endpoints).
 */
export async function test_api_member_post_soft_delete_within_allowed_window(connection: api.IConnection) {
  // 1. Register member
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssw0rd123!";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(session);
  // (Token is automatically in connection.headers)

  // 2. Create Post
  const title = RandomGenerator.paragraph()(1).slice(0, 100);
  const body = RandomGenerator.content()()().slice(0, 4000);
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title,
      body
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);
  TestValidator.equals("author matches session")(post.author_member_id)(session.member.id);
  TestValidator.equals("not deleted")(post.deleted_at)(null);

  // 3. Delete Post (soft delete)
  await api.functional.discussionBoard.member.posts.erase(connection, { postId: post.id });

  // 4. (No GET endpoint, so simulate by creating again and trying to delete again)
  TestValidator.error("double deletion should fail")(
    async () => {
      await api.functional.discussionBoard.member.posts.erase(connection, { postId: post.id });
    }
  );

  // 5. (No list/search endpoint given for validation; if available, would check that post is excluded.)

  // 6. (Optional): Register another member & try to delete original member's post (should fail)
  const email2 = typia.random<string & tags.Format<"email">>();
  const session2 = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: email2,
      password: "An0therPassw0rd!",
      nickname: RandomGenerator.name()
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(session2);
  TestValidator.error("cannot delete another's post")(
    async () => {
      await api.functional.discussionBoard.member.posts.erase(connection, { postId: post.id });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate deletion failure scenarios for discussion board member posts.
 *
 * This test simulates two negative cases:
 * 1. Member tries to delete a post that does not exist (should get not found).
 * 2. Member tries to delete another member's post (should get forbidden).
 * Additionally, it verifies no unrelated posts are changed after these operations.
 *
 * Test Steps:
 * 1. Register first member (deleter)
 * 2. Register second member (owner of a post)
 * 3. Second member creates a post
 * 4. First member attempts to delete an unrelated (nonexistent) post — expect not found
 * 5. First member attempts to delete the second member's post — expect forbidden
 * 6. As there is no post lookup by id, trust that the prior post is not deleted.
 */
export async function test_api_member_post_delete_nonexistent_or_unauthorized(connection: api.IConnection) {
  // 1. Register first member (deleter)
  const deleterEmail = typia.random<string & tags.Format<"email">>();
  const deleterReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: deleterEmail,
      password: "TestPassword!1",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(deleterReg);

  // 2. Register second member (owner of the post)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: "TestPassword!2",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ownerReg);

  // 3. Second member creates a post
  const ownerConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: ownerReg.setHeaders.Authorization,
    },
  };
  const postCreateInput = {
    title: "Test Post Title " + RandomGenerator.alphabets(6),
    body: "Test Post Body " + RandomGenerator.alphabets(10),
  } satisfies IDiscussionBoardPost.ICreate;
  const createdPost = await api.functional.discussionBoard.member.posts.create(ownerConnection, {
    body: postCreateInput,
  });
  typia.assert(createdPost);

  // 4. First member attempts to delete a nonexistent post id
  const deleterConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: deleterReg.setHeaders.Authorization,
    },
  };
  const fakePostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("nonexistent post should return not found")(
    () => api.functional.discussionBoard.member.posts.erase(deleterConnection, { postId: fakePostId })
  );

  // 5. First member attempts to delete second member's post
  await TestValidator.error("unauthorized post delete is forbidden")(
    () => api.functional.discussionBoard.member.posts.erase(deleterConnection, { postId: createdPost.id })
  );

  // 6. As there is no post lookup by id endpoint, we cannot confirm the post's continued existence,
  // but the above steps ensure the post was not deleted by unauthorized attempt.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdIntegrationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdIntegrationLog";

/**
 * Validate that an admin is able to successfully retrieve all information for a specific ad integration log entry.
 *
 * This test ensures that given a previously created ad integration log, an admin account can fetch its full details by ID, and all metadata, diagnostic, and event context fields are present in the result as expected.
 *
 * Steps:
 * 1. Create a new ad integration log entry using the POST endpoint, filling in all required fields with valid data.
 * 2. Retrieve the log entry using the GET endpoint with the returned ID.
 * 3. Validate that the response contains all fields and values match what was created (with appropriate server-managed fields like created_at/updated_at checked for presence and format).
 * 4. Assert the returned object validates against the expected DTO and all business fields are included.
 */
export async function test_api_ad_integration_log_get_success_by_admin(connection: api.IConnection) {
  // 1. Create a new ad integration log entry as prerequisite
  const createInput: IDiscussionBoardAdIntegrationLog.ICreate = {
    ad_channel: RandomGenerator.alphaNumeric(8),
    event_type: "impression",
    event_at: new Date().toISOString(),
    success: true,
    // Optional/context fields
    discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
    external_event_id: RandomGenerator.alphaNumeric(10),
    local_event_context: RandomGenerator.paragraph()(),
    response_payload: JSON.stringify({ result: "ok" }),
    error_code: null,
    error_message: null
  };
  const createdLog: IDiscussionBoardAdIntegrationLog = await api.functional.discussionBoard.admin.adIntegrationLogs.create(
    connection,
    { body: createInput }
  );
  typia.assert(createdLog);

  // 2. Retrieve the log entry by its ID
  const output: IDiscussionBoardAdIntegrationLog = await api.functional.discussionBoard.admin.adIntegrationLogs.at(
    connection,
    { adIntegrationLogId: createdLog.id }
  );
  typia.assert(output);

  // 3. Validate returned contents and field completeness
  TestValidator.equals("ad_channel matches")(output.ad_channel)(createInput.ad_channel);
  TestValidator.equals("event_type matches")(output.event_type)(createInput.event_type);
  TestValidator.equals("event_at matches")(output.event_at)(createInput.event_at);
  TestValidator.equals("success matches")(output.success)(createInput.success);
  TestValidator.equals("discussion_board_member_id matches")(output.discussion_board_member_id)(createInput.discussion_board_member_id);
  TestValidator.equals("external_event_id matches")(output.external_event_id)(createInput.external_event_id);
  TestValidator.equals("local_event_context matches")(output.local_event_context)(createInput.local_event_context);
  TestValidator.equals("response_payload matches")(output.response_payload)(createInput.response_payload);
  TestValidator.equals("error_code matches")(output.error_code)(createInput.error_code);
  TestValidator.equals("error_message matches")(output.error_message)(createInput.error_message);

  // Server-managed fields checks
  TestValidator.predicate("created_at is a valid ISO8601 date")(!!output.created_at && !isNaN(Date.parse(output.created_at)));
  TestValidator.predicate("updated_at is a valid ISO8601 date")(!!output.updated_at && !isNaN(Date.parse(output.updated_at)));
  if (output.deleted_at !== undefined && output.deleted_at !== null) {
    TestValidator.predicate("deleted_at is valid ISO8601 date if present")(!isNaN(Date.parse(output.deleted_at)));
  }
}

