import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRuleLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRuleLog";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate that only admin users can create rule log entries in the discussion board audit system, and that attempts by non-admins are properly forbidden and audited.
 *
 * Business context:
 * Rule log creation is restricted to admin users as a security and compliance safeguard. Proper RBAC (role-based access control) dictates that standard members, moderators, and unauthenticated guests should not be able to create or modify audit rule logs. Any such attempts must result in a 403 forbidden error, and the system should generate an audit log entry indicating the unauthorized attempt.
 *
 * Test process:
 * 1. Register a new member.
 * 2. Authenticate as the member and attempt to create a new rule log entry using valid member credentials (token provided in registration response). Expect a 403 forbidden error. Confirm no rule log is created.
 * 3. Register a new moderator via the admin assignment API (simulate admin context for test setup).
 * 4. Authenticate as the moderator (token provided in registration response) and attempt to create a rule log entry using valid moderator credentials. Expect a 403 forbidden error. Confirm no rule log is created.
 * 5. Without authentication (guest context), attempt to create a rule log entry. Expect a 403 forbidden error. Confirm no rule log is created.
 * 6. (Omitted: Confirm that forbidden attempts yield an audit entry, as this cannot be directly checked through available APIs.)
 *
 * This test verifies both RBAC enforcement and security auditing requirements for rule log creation endpoints.
 */
export async function test_api_rule_log_creation_invalid_role_forbidden_error(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "P@ssw0rd!";
  const memberNickname = RandomGenerator.name();

  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 2. Attempt to create rule log as member (should fail with 403)
  connection.headers = {
    ...connection.headers,
    Authorization: memberSession.setHeaders.Authorization,
  };
  await TestValidator.error("member forbidden to create rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.create(connection, {
      body: {
        operator_member_id: memberSession.member.id,
        rule_type: "permission_matrix",
        rule_text: "Only admins can change permissions.",
        change_type: "created",
        change_description: "Test rule log entry attempt by member",
        effective_from: new Date().toISOString(),
        effective_to: null,
        operator_admin_id: null,
      } satisfies IDiscussionBoardRuleLog.ICreate,
    });
  });

  // 3. Register a new moderator (simulate admin registration context)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongP@ss2";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 4. Attempt to create rule log as moderator (should fail with 403)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorSignUp.setHeaders.Authorization,
  };
  await TestValidator.error("moderator forbidden to create rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.create(connection, {
      body: {
        operator_member_id: null,
        operator_admin_id: null,
        rule_type: "sanction_policy",
        rule_text: "Moderator attempted rule addition.",
        change_type: "created",
        change_description: "Test rule log entry attempt by moderator",
        effective_from: new Date().toISOString(),
        effective_to: null,
      } satisfies IDiscussionBoardRuleLog.ICreate,
    });
  });

  // 5. Attempt to create rule log as guest (no auth header, should fail)
  connection.headers = Object.fromEntries(
    Object.entries(connection.headers || {}).filter(([key]) => key.toLowerCase() !== "authorization"),
  );
  await TestValidator.error("guest forbidden to create rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.create(connection, {
      body: {
        operator_member_id: null,
        operator_admin_id: null,
        rule_type: "category",
        rule_text: "Guest try rule log.",
        change_type: "created",
        change_description: "Test rule log entry attempt by guest",
        effective_from: new Date().toISOString(),
        effective_to: null,
      } satisfies IDiscussionBoardRuleLog.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRuleLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRuleLog";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test the successful update of a discussion board rule log by an admin.
 *
 * This test covers the complete business workflow:
 * 1. Register as a new admin (tests privileged access)
 * 2. Create a rule log (minimal required fields, using new admin)
 * 3. Update the rule log's mutable fields (change_description, effective_from, effective_to)
 * 4. Verifies:
 *    - Updated fields reflect the provided updates
 *    - The updated_at audit/timestamp is changed
 *    - The id and operator_admin_id fields are preserved
 *    - Structure passes type check
 */
export async function test_api_rule_log_update_success(connection: api.IConnection) {
  // 1. Register a new admin for authentication
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestP@ssw0rd";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Set Authorization for this admin context
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth.setHeaders.Authorization,
  };
  // 2. Create an initial rule log to update
  const originalRuleLog = await api.functional.discussionBoard.admin.ruleLogs.create(connection, {
    body: {
      operator_admin_id: adminAuth.admin_id,
      rule_type: "permission_matrix",
      rule_text: "Initial rule text.",
      change_type: "created",
      change_description: "Baseline RBAC policy recorded.",
      effective_from: new Date().toISOString(),
      effective_to: null,
    } satisfies IDiscussionBoardRuleLog.ICreate,
  });
  typia.assert(originalRuleLog);
  // 3. Compose updated payload
  const updateBody: IDiscussionBoardRuleLog.IUpdate = {
    change_description: "RBAC policy updated for quarterly review.",
    effective_from: new Date(Date.now() + 3600000).toISOString(), // 1hr later
    effective_to: new Date(Date.now() + 7200000).toISOString(),   // 2hrs later
  };
  // 4. Update the rule log
  const updatedRuleLog = await api.functional.discussionBoard.admin.ruleLogs.update(connection, {
    ruleLogId: originalRuleLog.id,
    body: updateBody,
  });
  typia.assert(updatedRuleLog);
  // 5. Validation of update
  TestValidator.equals("rule log id unchanged")(updatedRuleLog.id)(originalRuleLog.id);
  TestValidator.equals("operator_admin_id unchanged")(updatedRuleLog.operator_admin_id)(originalRuleLog.operator_admin_id);
  TestValidator.equals("change_description updated")(updatedRuleLog.change_description)(updateBody.change_description);
  TestValidator.equals("effective_from updated")(updatedRuleLog.effective_from)(updateBody.effective_from);
  TestValidator.equals("effective_to updated")(updatedRuleLog.effective_to)(updateBody.effective_to);
  TestValidator.notEquals("updated_at bumped")(updatedRuleLog.updated_at)(originalRuleLog.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
