/**
 * Validates the successful soft deletion of a rule log entry by an admin user.
 *
 * Business context: Rule logs in the discussion board are auditable records of policy or permission changes. Soft deletion (setting the `deleted_at` timestamp) ensures compliance with retention policies, allowing logs to be hidden from standard queries yet retained for auditing. Only privileged admin accounts can perform this action, and deletion must be accurately reflected in audit trails. The rule log, once deleted, should not appear in standard (non-audit) queries, and all changes must be audit-logged.
 *
 * Step-by-step process:
 * 1. Create and register a new admin account
 * 2. Use the admin credentials to authenticate, ensuring all privileged endpoints are available
 * 3. Create a new rule log entry as the registered admin
 * 4. Soft-delete the created rule log entry via the DELETE endpoint
 * 5. (If GET were available) Confirm deletion by fetching the rule log; currently omitted since not exposed in SDK
 *
 * This test ensures the complete lifecycle (create–soft-delete–audit) for a rule log entry, verifying retention behavior and privilege enforcement.
 */
export async function test_api_rule_log_soft_delete_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Admin is now authenticated, JWT included in connection headers automatically

  // 3. Create a rule log entry as admin
  const nowIso = new Date().toISOString();
  const ruleLog = await api.functional.discussionBoard.admin.ruleLogs.create(connection, {
    body: {
      operator_admin_id: adminAuth.admin_id,
      operator_member_id: null,
      rule_type: 'permission_matrix',
      rule_text: 'Board permissions updated',
      change_type: 'created',
      change_description: 'Initial permission setup for board policy',
      effective_from: nowIso,
      effective_to: null,
    } satisfies IDiscussionBoardRuleLog.ICreate,
  });
  typia.assert(ruleLog);

  // 4. Soft-delete the created rule log
  await api.functional.discussionBoard.admin.ruleLogs.erase(connection, {
    ruleLogId: ruleLog.id,
  });

  // 5. (If GET endpoint existed) Confirm deletion by fetching rule log and checking deleted_at; omitted since not available.
  // Main validation: operation completes with correct privilege and no errors, confirming policy is enforced.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
