/**
 * Test error handling for invalid filter parameters on external auth logs search.
 *
 * Ensures that when an admin supplies syntactically invalid or unsupported filter parameters to the external authentication logs search endpoint, the API returns validation errors, does not leak log data, and the failed search attempt could be audit-logged (if testable).
 *
 * **Steps:**
 * 1. Register a new admin to obtain credentials.
 * 2. (Implicit) Use provided JWTs for authentication—handled automatically.
 * 3. Attempt various invalid external auth log search requests, including:
 *    - Improper UUID string for member
 *    - Negative and extreme values for pagination/limit
 *    - Malformed or impossible date-time values
 *    - Empty channel string or other semantically invalid values
 * 4. For each case, verify that an error is thrown. Never receive log data object for these invalid requests.
 */
export async function test_api_external_auth_log_search_invalid_filter_error_handling(connection: api.IConnection) {
