 *
 * Workflow Steps:
 * 1. Create a parent category (required for sub-categories).
 * 2. Create the first sub-category under this parent with a distinct name.
 * 3. Attempt to create a second sub-category under the same parent using the same name.
 * 4. API call should result in a uniqueness/conflict error per business rules (NOT a successful creation, not a type error).
 * 5. Validate that the error semantics align with conflict response expectations (HTTP status and error type) – only presence of error is checked.
 */
export async function test_api_subcategory_creation_duplicate_name(connection: api.IConnection) {
  // 1. Create a parent category (top-level, no parent_id)
  const parentName: string = RandomGenerator.alphabets(8);
  const parentOrder: number = typia.random<number & tags.Type<"int32">>();
  const parent: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: parentName,
      display_order: parentOrder,
      enabled: true,
      version: 1
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(parent);

  // 2. Create the first sub-category with a unique name
  const subCatName: string = RandomGenerator.alphabets(10);
  const subCatOrder: number = typia.random<number & tags.Type<"int32">>();
  const subCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parent.id,
    body: {
      name: subCatName,
      display_order: subCatOrder,
      enabled: true,
      version: 1
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(subCategory);
  TestValidator.equals("sub-category.name == request name")(subCategory.name)(subCatName);

  // 3. Attempt to create another sub-category with the same name (should fail with uniqueness/conflict error)
  await TestValidator.error("duplicate sub-category name should result in conflict error")(async () => {
    await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
      categoryId: parent.id,
      body: {
        name: subCatName, // Intentional duplicate
        display_order: typia.random<number & tags.Type<"int32">>(),
        enabled: true,
        version: 1
      } satisfies IDiscussionBoardCategory.ICreate
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate the successful update of a discussion board sub-category's editable fields as an admin.
 *
 * This test covers the following business flow:
 * 1. Create a parent category as the root-level category (required for adding sub-categories).
 * 2. Create a sub-category under the parent category.
 * 3. Update the sub-category's properties: name, description, display_order, enabled, and icon_uri.
 * 4. Validate that all updated fields persist and are saved as expected.
 * 5. Ensure audit/versioning fields such as version and updated_at change, but created_at remains unmodified.
 * 6. Verify the sub-category's parent linkage to the parent category is unchanged.
 * 7. Confirm no cycles exist in the hierarchy as a result of the update.
 */
export async function test_api_subcategory_update_success(
  connection: api.IConnection,
) {
  // 1. Create the parent category
  const parentCategoryInput: IDiscussionBoardCategory.ICreate = {
    name: `ParentCat-${RandomGenerator.alphaNumeric(6)}`,
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
  };
  const parentCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: parentCategoryInput,
  });
  typia.assert(parentCategory);

  // 2. Create a sub-category under the parent
  const subCategoryInput: IDiscussionBoardCategory.ICreate = {
    name: `SubCat-${RandomGenerator.alphaNumeric(6)}`,
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
    parent_id: parentCategory.id,
  };
  const subCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parentCategory.id,
    body: subCategoryInput,
  });
  typia.assert(subCategory);

  // 3. Prepare update payload for editable fields
  const updatePayload: IDiscussionBoardCategory.IUpdate = {
    name: `SubCat-Updated-${RandomGenerator.alphaNumeric(4)}`,
    description: "This sub-category was updated by an automated E2E test.",
    display_order: subCategory.display_order + 10,
    enabled: false,
    icon_uri: `https://cdn.example.com/icons/icon-${RandomGenerator.alphaNumeric(8)}.png`,
  };

  // 4. Update the sub-category
  const updatedSubCategory = await api.functional.discussionBoard.admin.categories.subs.updateSubCategory(connection, {
    categoryId: parentCategory.id,
    subCategoryId: subCategory.id,
    body: updatePayload,
  });
  typia.assert(updatedSubCategory);

  // 5. Validate fields were updated
  TestValidator.equals("name updated")(updatedSubCategory.name)(updatePayload.name);
  TestValidator.equals("description updated")(updatedSubCategory.description)(updatePayload.description);
  TestValidator.equals("display_order updated")(updatedSubCategory.display_order)(updatePayload.display_order);
  TestValidator.equals("enabled updated")(updatedSubCategory.enabled)(updatePayload.enabled);
  TestValidator.equals("icon_uri updated")(updatedSubCategory.icon_uri)(updatePayload.icon_uri);

  // 6. Validate audit/versioning logic
  TestValidator.predicate("version increment/equal or updated")(
    typeof updatedSubCategory.version === "number" && updatedSubCategory.version >= subCategory.version
  );
  TestValidator.equals("parent_id remains unchanged")(updatedSubCategory.parent_id)(subCategory.parent_id);
  TestValidator.equals("created_at remains unchanged")(updatedSubCategory.created_at)(subCategory.created_at);
  TestValidator.predicate("updated_at is newer or equal")(
    new Date(updatedSubCategory.updated_at).getTime() >= new Date(subCategory.updated_at).getTime()
  );
  TestValidator.equals("not deleted")(updatedSubCategory.deleted_at)(null);
}

