import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";
import type { IPageIDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced admin search and pagination over discussion board comment abuse reports.
 *
 * This test ensures an admin can search, filter, and paginate comment reports effectively using the advanced search endpoint. It seeds multiple posts/comments, files several report records from different reporters, and manipulates report type, status, and creation window diversity. Core business behaviors and edge cases are validated:
 *
 * 1. Create several posts as prerequisites
 * 2. Add comments to those posts (enabling reporting)
 * 3. File comment reports from multiple simulated members, with varying reason_type and custom text (simulate e.g., 'spam', 'hate', 'off-topic', etc.)
 * 4. (Direct status manipulation is not possible via API so use default/status='pending')
 * 5. Search and paginate comment reports as admin:
 *    - No filter: Paginate all, check total/limit/pages logic
 *    - By specific reporter (discussion_board_member_id): Only their reports returned
 *    - By reason_type: Only matching types returned
 *    - By reported comment: Filter for specific discussion_board_comment_id
 *    - By creation window: Filter with created_from/created_to, assert correct content
 *    - By status: All should be 'pending' unless advanced workflow exists
 *    - Over-restrictive filter: No matches, empty list
 *    - Sorting by created_at ascending/descending
 * 6. Verify that data in page/data objects matches creation input (IDs, types, status, timestamps), and respect pagination meta
 *
 * Steps:
 *   - Seed multiple posts (for distinct comment targets)
 *   - Add comments to posts
 *   - File multiple reports on comments, source different members
 *   - As admin, search with various filters to validate inclusion
 *   - Check paginated responses (pagination meta and data)
 *   - Check empty result set for excessive filter
 */
export async function test_api_comment_report_admin_search_pagination_filters(
  connection: api.IConnection,
) {
  // 1. Seed prerequisite posts
  const posts = await ArrayUtil.asyncRepeat(3)(async () => {
    const post = await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.content()(50)(),
      },
    });
    typia.assert(post);
    return post;
  });

  // 2. Add comments to these posts
  const comments = await ArrayUtil.asyncMap(posts)(async (post) => {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: { body: RandomGenerator.paragraph()(8) },
    });
    typia.assert(comment);
    return comment;
  });

  // 3. File comment reports. Simulate two members' IDs as reporter context
  // Instead of separate logins, mock unique member IDs in report payloads if API allows, otherwise reports all made by test member context
  // Report with varying reason_type ('spam', 'hate', etc) and times (simulate spread via direct API if possible). All start with status 'pending'
  const reason_types = ["spam", "hate", "off-topic"];
  const reports = [];
  for (let i = 0; i < comments.length; ++i) {
    const report = await api.functional.discussionBoard.member.commentReports.create(connection, {
      body: {
        discussion_board_comment_id: comments[i].id,
        reason_type: reason_types[i % reason_types.length],
        reason_text: `Reason for ${reason_types[i % reason_types.length]}`,
      },
    });
    typia.assert(report);
    reports.push(report);
  }

  // 4. As admin, use search with various filters
  // 4-1. No filter: paginate all
  const basicSearch = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      page: 1,
      limit: 10,
    },
  });
  typia.assert(basicSearch);
  TestValidator.predicate("listing is non-empty")(basicSearch.data.length > 0);

  // 4-2. By reporter
  const reporterId = reports[0].discussion_board_member_id;
  const byReporter = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      discussion_board_member_id: reporterId,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byReporter);
  TestValidator.predicate("all match reporterId")(byReporter.data.every(r => r.discussion_board_member_id === reporterId));

  // 4-3. By reason_type
  const reasonType = reports[1].reason_type;
  const byReasonType = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      reason_type: reasonType,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byReasonType);
  TestValidator.predicate("all match reason type")(byReasonType.data.every(r => r.reason_type === reasonType));

  // 4-4. By reported comment
  const commentId = reports[2].discussion_board_comment_id;
  const byComment = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      discussion_board_comment_id: commentId,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byComment);
  TestValidator.predicate("only target comment")(byComment.data.every(r => r.discussion_board_comment_id === commentId));

  // 4-5. By creation time window (tight range, e.g. after now to next hour, should be empty)
  const now = new Date();
  const futureISO = new Date(now.getTime() + 3600 * 1000).toISOString();
  const emptyFuture = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      created_from: futureISO,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(emptyFuture);
  TestValidator.equals("empty due to future time filter")(emptyFuture.data.length)(0);

  // 4-6. By status (should all be 'pending')
  const byStatus = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      status: "pending",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byStatus);
  TestValidator.predicate("status pending only")(byStatus.data.every(r => r.status === "pending"));

  // 4-7. Sorting ASC
  const byAsc = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      order_by: "created_at",
      direction: "asc",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byAsc);
  if (byAsc.data.length > 1) {
    TestValidator.predicate("ascending order")(new Date(byAsc.data[0].created_at) <= new Date(byAsc.data[byAsc.data.length-1].created_at));
  }

  // 4-8. Sorting DESC
  const byDesc = await api.functional.discussionBoard.admin.commentReports.search(connection, {
    body: {
      order_by: "created_at",
      direction: "desc",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(byDesc);
  if (byDesc.data.length > 1) {
    TestValidator.predicate("descending order")(new Date(byDesc.data[0].created_at) >= new Date(byDesc.data[byDesc.data.length-1].created_at));
  }

  // 5. Check pagination metadata structure
  TestValidator.predicate("pagination meta exists")(!!basicSearch.pagination && typeof basicSearch.pagination.pages === "number");
}

