import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator search and pagination over comment abuse reports.
 *
 * This test verifies that moderators can effectively retrieve, filter, and paginate comment abuse reports. The flow simulates multiple members posting comments, generating reports with different statuses, reasons, and reporters, to the extent feasible by API contract. The test checks that the moderator's search endpoint returns accurate, filtered, and paginated results matching expectations for various query conditions, including edge cases and empty result enforcement.
 *
 * Steps:
 * 1. Create three discussion posts as a member.
 * 2. For each post, create two comments (total six comments).
 * 3. For each comment, submit an abuse report with varied reason_type fields (emulating realistic scenarios; reporter/member assignment is implicit in test context).
 * 4. Search as moderator for all reports (basic, unfiltered).
 * 5. Apply filter: search reports by reason_type; verify all returned items match.
 * 6. Apply filter: search reports after a recent timestamp (should be empty if strictly in the future).
 * 7. Pagination test: Use low per-page limit, check correct slices and pagination meta.
 * 8. Apply highly restrictive filter (status unlikely to exist); verify empty data set is returned.
 */
export async function test_api_comment_report_moderator_search_basic_pagination(connection: api.IConnection) {
  // Step 1: Create 3 posts as a member
  const posts = await ArrayUtil.asyncRepeat(3)(async () => {
    const post = await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(8),
        body: RandomGenerator.content()()(16),
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(post);
    return post;
  });

  // Step 2: Create 2 comments per post
  const comments: IDiscussionBoardComment[] = [];
  for (const post of posts) {
    for (let i = 0; i < 2; ++i) {
      const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
        postId: post.id,
        body: {
          body: RandomGenerator.content()()(6),
        } satisfies IDiscussionBoardComment.ICreate,
      });
      typia.assert(comment);
      comments.push(comment);
    }
  }

  // Step 3: For each comment, submit an abuse report with varied reason_type
  const reasonTypes = ["spam", "hate", "off-topic", "advertising"];
  const reports: IDiscussionBoardCommentReport[] = [];
  for (let i = 0; i < comments.length; ++i) {
    const report = await api.functional.discussionBoard.member.commentReports.create(connection, {
      body: {
        discussion_board_comment_id: comments[i].id,
        reason_type: reasonTypes[i % reasonTypes.length],
        reason_text: `Abuse/Test Report #${i + 1}`,
      } satisfies IDiscussionBoardCommentReport.ICreate,
    });
    typia.assert(report);
    reports.push(report);
  }

  // Step 4: Moderator searches for all reports (unfiltered)
  const allReports = await api.functional.discussionBoard.moderator.commentReports.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCommentReport.IRequest,
  });
  typia.assert(allReports);
  TestValidator.predicate("at least 6 reports present")(allReports.data.length >= 6);

