import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for paginated and filtered retrieval of discussion board daily statistics by an admin.
 *
 * This test validates the following:
 * 1. Basic retrieval (no filters): Ensures that a paginated list is returned matching the contract shape.
 * 2. Date range filtering: Only records between the requested dates are included in the result.
 * 3. Sorting: Verifies both ascending and descending orderings using 'order_by' and 'order_direction'.
 * 4. Pagination: Checks that different page/limit values return the correct slices, and pagination metadata is correct.
 * 5. Error handling: Invalid search criteria (date_from > date_to, negative or excessively high page) are handled with clear runtime errors.
 * 6. Privacy requirement: Only summary fields are returned for each daily stats record (DTO guarantees this by contract).
 *
 * Steps:
 * 1. Retrieve first page with no filters.
 * 2. Filter with 7-day date range.
 * 3. Sort by date ascending.
 * 4. Request second page with limit 2.
 * 5. Error test: date_from > date_to.
 * 6. Error test: negative page.
 * 7. Error test: out-of-bounds page.
 */
export async function test_api_daily_stats_search_with_filters(connection: api.IConnection) {
  // 1. Basic retrieval with no filters
  const basic = await api.functional.discussionBoard.admin.dailyStats.search(connection, {
    body: {}
  });
  typia.assert(basic);
  TestValidator.predicate("basic data are array of stats")(
    Array.isArray(basic.data) && basic.data.every(x => typeof x === "object")
  );

  // 2. Date range filter (within past 7 days)
  const dateFrom = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const dateTo = new Date().toISOString();
  const dateRange = await api.functional.discussionBoard.admin.dailyStats.search(connection, {
    body: { date_from: dateFrom, date_to: dateTo }
  });
  typia.assert(dateRange);
  for (const rec of dateRange.data) {
    const dt = new Date(rec.date_utc);
    TestValidator.predicate("stat.date_utc in range")(dt >= new Date(dateFrom) && dt <= new Date(dateTo));
  }

  // 3. Sorting (asc by date_utc)
  const asc = await api.functional.discussionBoard.admin.dailyStats.search(connection, {
    body: { order_by: "date_utc", order_direction: "asc", limit: 5 }
  });
  typia.assert(asc);
  for (let i = 1; i < asc.data.length; ++i) {
    TestValidator.predicate("ascending sort")(asc.data[i - 1].date_utc <= asc.data[i].date_utc);
  }

  // 4. Pagination: request second page
  const page2 = await api.functional.discussionBoard.admin.dailyStats.search(connection, {
    body: { page: 2, limit: 2 }
  });
  typia.assert(page2);
  TestValidator.equals("correct page")(page2.pagination.current)(2);
  TestValidator.equals("correct limit")(page2.pagination.limit)(2);

  // 5. Error case: date_from > date_to
  await TestValidator.error("invalid date range fails")(
    async () => {
      await api.functional.discussionBoard.admin.dailyStats.search(connection, {
        body: { date_from: dateTo, date_to: dateFrom }
      });
    }
  );

  // 6. Error case: negative page number
  await TestValidator.error("negative page fails")(
    async () => {
      await api.functional.discussionBoard.admin.dailyStats.search(connection, {
        body: { page: -1 }
      });
    }
  );

  // 7. Error case: out-of-bounds page
  await TestValidator.error("huge page fails")(
    async () => {
      await api.functional.discussionBoard.admin.dailyStats.search(connection, {
        body: { page: 100000 }
      });
    }
  );
}

