import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Ensure that only members can search member-only discussion board posts, and access is denied to non-authenticated or improperly authenticated users.
 *
 * Business context:
 * This test confirms strict enforcement of role-based access control for member-specific content on the discussion board. Preventing anonymous or unauthorized users from viewing or searching member-only posts protects privacy and enforces community policy.
 *
 * Step-by-step process:
 * 1. Provision a sample post using the member post creation endpoint (authenticated context, dependency satisfied).
 * 2. Attempt to search posts with a missing authentication token (simulate non-authenticated user).
 * 3. Verify that the API responds with an unauthorized/forbidden error.
 * 4. Attempt to search posts with an explicitly invalid (malformed or expired) token.
 * 5. Verify that a forbidden/unauthorized error is returned.
 */
export async function test_api_member_post_search_permission_enforcement(connection: api.IConnection) {
  // 1. Provision a sample post as a dependency
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1).substring(0, 100),
      body: RandomGenerator.content()(1)().substring(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 2. Attempt to search posts with no authentication (simulate a non-authenticated user)
  const unauthenticatedHeaders = { ...connection.headers };
  delete unauthenticatedHeaders.Authorization;
  const unauthenticatedConnection = { ...connection, headers: unauthenticatedHeaders };
  await TestValidator.error("search forbidden for unauthenticated user")(async () => {
    await api.functional.discussionBoard.member.posts.search(unauthenticatedConnection, {
      body: {},
    });
  });

  // 3. Attempt to search posts with an invalid/expired token
  const invalidHeaders = { ...connection.headers, Authorization: "Bearer INVALID.TOKEN" };
  const invalidAuthConnection = { ...connection, headers: invalidHeaders };
  await TestValidator.error("search forbidden for invalid token")(async () => {
    await api.functional.discussionBoard.member.posts.search(invalidAuthConnection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator post search with inclusive visibility and advanced filters.
 *
 * This test verifies that a moderator account is able to search and retrieve discussion board posts of every workflow status, including 'active', 'hidden', 'flagged', 'deleted', and drafts. It exercises advanced search and filter capabilities, such as searching by category, specific status, author role (member, moderator, admin), partial text for title/body, and pagination logic. Posts belonging to all visibility statuses are asserted to be discoverable only by moderators and not regular members.
 *
 * Step-by-step process:
 * 1. Register and log in a moderator, collecting the issued JWT from each step.
 * 2. Create multiple posts as a moderator, setting a variety of workflow statuses:
 *    - One with status 'active'
 *    - One with status 'hidden'
 *    - One with status 'deleted'
 *    - One with status 'flagged'
 * 3. Search all posts without filter: assert that ALL created posts are present.
 * 4. Search by each individual status (active, hidden, deleted, flagged) and assert only the corresponding post is matched.
 * 5. Search by author_moderator_id: assert only posts by the moderator appear.
 * 6. Search by partial title and partial body text, assert posts are discoverable.
 * 7. Search by category_id, assert categorization is respected.
 * 8. Confirm pagination: with page and limit params, total records and result split are verified.
 */
export async function test_api_moderator_post_search_with_inclusive_visibility_and_filters(
  connection: api.IConnection,
) {
  // 1. Moderator registration (requires unique moderator email and assigned_by_admin_email)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = "Test1234!";
  const signUpRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password
    } satisfies IModerator.SignUp
  });
  typia.assert(signUpRes);
  TestValidator.equals("returned moderator email matches")(signUpRes.email)(moderatorEmail);

  // 2. Moderator login
  const signInRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password
    } satisfies IModerator.SignIn
  });
  typia.assert(signInRes);
  TestValidator.equals("moderator login email matches")(signInRes.email)(moderatorEmail);

  // 3. Create test posts with varying statuses as the moderator
  // We'll create 4 different posts, each with a unique status and easily-searchable title/body patterns
  const statuses = ["active", "hidden", "deleted", "flagged"];
  const createdPosts = [] as IDiscussionBoardPost[];
  const categoryIds: string[] = [];
  for(const status of statuses) {
    // Category per status for categorical filtering
    const categoryId: string = typia.random<string & tags.Format<"uuid">>();
    categoryIds.push(categoryId);
    // Generate a unique title/body including the status
    const post = await api.functional.discussionBoard.moderator.posts.create(connection, {
      body: {
        title: `Test Post: ${status} ${RandomGenerator.alphabets(5)}`,
        body: `Body for status ${status} ${RandomGenerator.alphabets(7)}`,
        attachments: null,
        category_id: categoryId,
        platform_config_id: null
      } satisfies IDiscussionBoardPost.ICreate
    });
    typia.assert(post);
    // NOTE: The test assumes each created post starts as 'active'. There's no status parameter in .ICreate or a status update API, so distinction for other statuses cannot be set via public API.
    // For demonstration, store posts and the intended status
    (post as any)._testStatus = status;
    createdPosts.push(post);
  }

  // 4. Search all posts, no filter (moderator sees all their created posts)
  let out = await api.functional.discussionBoard.moderator.posts.search(connection, { body: {}});
  typia.assert(out);
  // All created post IDs should be in results
  for(const p of createdPosts) {
    TestValidator.predicate(`should find post id ${p.id}`)(out.data.some(r => r.id === p.id));
  }
  // Pagination/records count isn't guaranteed for a multi-user environment, but at least our posts must be present

  // 5. Search by moderator author id
  const moderatorId = signUpRes.moderator_id;
  const filterByAuthor = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { author_moderator_id: moderatorId } });
  typia.assert(filterByAuthor);
  for(const p of createdPosts) {
    TestValidator.predicate(`found by author_moderator_id ${p.id}`)(filterByAuthor.data.some(r => r.id === p.id));
  }

  // 6. Search by title fragment, and by body fragment
  for(const post of createdPosts) {
    const fragTitle = post.title.slice(0, 8);
    const fragBody = post.body.slice(0, 10);
    const byTitle = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { title: fragTitle } });
    typia.assert(byTitle);
    TestValidator.predicate(`should match partial title ${fragTitle}`)(byTitle.data.some(r => r.id === post.id));
    const byBody = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { body: fragBody } });
    typia.assert(byBody);
    TestValidator.predicate(`should match partial body ${fragBody}`)(byBody.data.some(r => r.id === post.id));
  }

  // 7. Search by category_id for each post
  for(let i=0; i<createdPosts.length; ++i) {
    const post = createdPosts[i];
    const categoryId = categoryIds[i];
    const byCat = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { category_id: categoryId } });
    typia.assert(byCat);
    TestValidator.predicate(`should match by category_id ${categoryId}`)(byCat.data.some(r => r.id === post.id));
  }

  // 8. Test pagination with page/limit - get first page, then second if needed
  const pageSize = 2;
  const firstPage = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { page: 1, limit: pageSize } });
  typia.assert(firstPage);
  TestValidator.equals("first page length")(firstPage.data.length)(Math.min(pageSize, createdPosts.length));
  if(createdPosts.length > pageSize) {
    const secondPage = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { page: 2, limit: pageSize } });
    typia.assert(secondPage);
    // Just check our test posts are present, not absolute length, as there might be posts from other users
    for(const p of createdPosts.slice(pageSize)) {
      TestValidator.predicate(`post present on page 2`)(secondPage.data.some(r => r.id === p.id));
    }
  }
}

