import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * E2E test verifying admin search/filter/post visibility, audit fields, and pagination robustness.
 *
 * 1. Register an admin account and login, saving the credential token into the connection object for further privileged calls.
 * 2. Create several posts as admin, using a range of statuses ('active', 'hidden', 'flagged', 'deleted'), with diverse title/body/category fields.
 *    - Use at least 2 distinct category_id values.
 *    - Use both short and long title/body text.
 *    - Some posts should be directly "deleted" (by setting status and ensuring deleted_at exists).
 *    - Ensure at least 1 post for each status type.
 * 3. For each of the following, issue a search (PATCH /discussionBoard/admin/posts) with admin credentials, verify the result type, content, and audit visibility:
 *    a. No filter (all posts, all statuses) – verify all created posts (including "deleted"/hidden/flagged) appear and audit info is present
 *    b. By status (one search per: 'active', 'hidden', 'flagged', 'deleted') – verify search only returns posts for that status
 *    c. By author_admin_id (filter by current admin user, verify only self-authored posts returned)
 *    d. By category_id (search by each used category_id, coverage only; assertion can't check content)
 *    e. Text search (partial title/body keywords, verify matches are as expected)
 * 4. Check pagination: use limit smaller than total (limit = 2), verify returned data and pagination meta, iterate over multiple pages if possible.
 * 5. Complex filter: status + category + text combined (ensure only posts matching all constraints are returned, assertion only on fields present in summary)
 * 6. Edge cases: 
 *    - Empty result (search with impossible filters)
 *    - Invalid category_id (well-formed but unused UUID)
 *    - Negative page index (expect graceful error handling, not internal crash)
 * 7. Check that result objects include extra admin-visible audit info where specification expects it (where verifiable by shape or with type assertion only).
 */
export async function test_api_admin_post_search_with_audit_scope_and_metadata(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd!";
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerResp);

  // 2. Admin login
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginResp);

  // At this point, connection.headers.Authorization is set for admin auth.

  // 3. Use two categories (minimal summaries)
  const categoryA = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: "Category A",
  } satisfies IDiscussionBoardCategory.ISummary;
  const categoryB = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: "Category B",
  } satisfies IDiscussionBoardCategory.ISummary;

  // 4. Create posts in various statuses/categories (simulate by local mutation since status can only be set by workflow/policy, not at create)
  const postSpecs = [
    { status: "active", category: categoryA, title: "Active Post" },
    { status: "hidden", category: categoryA, title: "Hidden Post" },
    { status: "flagged", category: categoryB, title: "Flagged Post" },
    { status: "deleted", category: categoryB, title: "Deleted Post" },
  ];
  const createdPosts: IDiscussionBoardPost[] = [];
  for (const spec of postSpecs) {
    const post = await api.functional.discussionBoard.admin.posts.create(connection, {
      body: {
        title: spec.title,
        body: `Body for ${spec.title}`,
        category_id: spec.category.id,
        attachments: null,
      },
    });
    typia.assert(post);
    // Simulate status and deleted_at as local mock, since API does not provide direct status mutation
    if (spec.status !== "active") {
      post.status = spec.status;
      if (spec.status === "deleted") post.deleted_at = new Date().toISOString() as string & tags.Format<"date-time">;
    }
    createdPosts.push(post);
  }

  // 5. Search - no filter (admin gets all statuses)
  let result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: {},
  });
  typia.assert(result);
  TestValidator.predicate("all statuses returned as admin")(
    result.data.find((x) => x.status === "deleted" && x.title === "Deleted Post") !== undefined,
  );

  // 6. Search by status
  for (const status of ["active", "hidden", "flagged", "deleted"]) {
    result = await api.functional.discussionBoard.admin.posts.search(connection, {
      body: { status },
    });
    typia.assert(result);
    TestValidator.predicate(`only ${status} posts returned`)(
      result.data.every((x) => x.status === status),
    );
  }

  // 7. Search by author_admin_id (should get only posts authored by this admin)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { author_admin_id: registerResp.admin_id },
  });
  typia.assert(result);
  TestValidator.predicate("posts for this admin only")(
    result.data.every((x) => x.author_admin_id === registerResp.admin_id),
  );

  // 8. Search by category_id (assertion skipped, as 'category' in ISummary is an empty object)
  for (const cat of [categoryA, categoryB]) {
    result = await api.functional.discussionBoard.admin.posts.search(connection, {
      body: { category_id: cat.id },
    });
    typia.assert(result);
    // Can't check result.data[x].category.id, as ISummary.category is '{}'; assertion omitted
  }

  // 9. Text search (partial title, partial body)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { title: "Active" },
  });
  typia.assert(result);
  TestValidator.predicate("title search finds correct post")(
    result.data.some((x) => x.title.includes("Active")),
  );

  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { body: "Body for Hidden" },
  });
  typia.assert(result);
  TestValidator.predicate("body search finds hidden post")(
    result.data.some((x) => x.title === "Hidden Post"),
  );

  // 10. Pagination test (limit < total)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { limit: 2, sort_by: "created_at", sort_order: "asc" },
  });
  typia.assert(result);
  TestValidator.equals("pagination.limit")(result.pagination.limit)(2);
  TestValidator.predicate("pagination has <=2 data")(result.data.length <= 2);

  // 11. Multi-filter: status, category, title text (assertion only on present fields)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: {
      status: "active",
      category_id: categoryA.id,
      title: "Active",
    },
  });
  typia.assert(result);
  TestValidator.predicate("complex filter")(
    result.data.every(
      (x) => x.status === "active" && x.title.includes("Active"),
    ),
  );
  // Do not check x.category.id

  // 12. Edge: Impossible filter (empty)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { status: "active", category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("no match empty array")(result.data.length)(0);

  // 13. Edge: Invalid category_id (well-formed UUID)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("invalid category no match")(result.data.length)(0);

  // 14. Edge: Negative page index (expect graceful error)
  await TestValidator.error("negative page index error")(
    async () => {
      await api.functional.discussionBoard.admin.posts.search(connection, {
        body: { page: -1 },
      });
    },
  );

  // 15. Verify audit info (where distinguishable by type/structure only)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate permission enforcement for the admin-only discussion board post search endpoint.
 *
 * This test ensures that ONLY users with the admin role can access the PATCH /discussionBoard/admin/posts endpoint.
 * Access attempts from users with the moderator role, member role, and unauthenticated session must all be rejected with a forbidden error.
 * The test also ensures that no privileged information is accidentally leaked in error responses to unauthorized users.
 *
 * Steps:
 * 1. Register a moderator account, simulating a real moderator user (requires a fake admin email for registration).
 * 2. Register a member account, simulating a normal user.
 * 3. As moderator, attempt to search admin posts (should fail with forbidden).
 * 4. As member, attempt to search admin posts (should fail with forbidden).
 * 5. With no authentication (unauthenticated session), attempt the search (should fail with forbidden or unauthorized).
 * 6. On each denial, confirm that no post data is returned and response does not contain information leak.
 */
export async function test_api_admin_post_search_permission_enforcement_for_non_admins(
  connection: api.IConnection,
) {
  // 1. Register a moderator account
  const fakeAdminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test$12345";
  const moderatorSignUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: fakeAdminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUpResp);
  const moderatorToken = moderatorSignUpResp.setHeaders.Authorization;

  // Reset connection headers for member registration
  connection.headers = Object.fromEntries(
    Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization"),
  );

  // 2. Register a member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "StrongMemberPW!1";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberToken = memberSession.setHeaders.Authorization;

  // 3. Moderator attempts admin post search (should be forbidden)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorToken,
  };
  await TestValidator.error("moderator cannot access admin-only post search")(
    async () => {
      await api.functional.discussionBoard.admin.posts.search(connection, {
        body: {},
      });
    },
  );

  // 4. Member attempts admin post search (should be forbidden)
  connection.headers = {
    ...connection.headers,
    Authorization: memberToken,
  };
  await TestValidator.error("member cannot access admin-only post search")(
    async () => {
      await api.functional.discussionBoard.admin.posts.search(connection, {
        body: {},
      });
    },
  );

  // 5. Unauthenticated (no token) attempts admin post search (should be forbidden/unauthorized)
  connection.headers = Object.fromEntries(
    Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization"),
  );
  await TestValidator.error("unauthenticated cannot access admin-only post search")(
    async () => {
      await api.functional.discussionBoard.admin.posts.search(connection, {
        body: {},
      });
    },
  );
}

