 *
 * This test ensures:
 * - Authenticated members can view the full detail (author, category, title, body, attachments, etc.) for a post by postId.
 * - Only posts with status 'active' and not soft-deleted are accessible to members.
 * - Author/member profile is present and correct.
 * - All required fields (category, title, body, attachments, status, timestamps) are present and correct.
 * - Field-level validation on post details.
 *
 * **Steps:**
 * 1. Register a member (who will be the post author and the viewer for this test)
 * 2. Login to obtain an authenticated session
 * 3. Create an 'active' post as this member (with attachments)
 * 4. Retrieve the post by its postId using the authenticated session
 * 5. Validate all detail fields, presence of author profile, category, content, status, and timestamps; ensure the post is not soft-deleted
 */
export async function test_api_member_post_read_individual_active_post_detail(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Password!1";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname,
    },
  });
  typia.assert(session);

  // 2. Login with the same member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(login);

  // 3. Create an active post as the logged-in member
  const attachmentsArr = [
    {
      fileUri: "https://assets.example.com/" + typia.random<string & tags.Format<"uuid">>() + ".png",
      description: "Sample image screenshot",
    },
  ];
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      attachments: JSON.stringify(attachmentsArr),
    },
  });
  typia.assert(post);
  TestValidator.equals("status is active")(post.status)("active");
  TestValidator.predicate("not soft-deleted")(post.deleted_at === null || post.deleted_at === undefined);

  // 4. Retrieve the post by its id
  const detail = await api.functional.discussionBoard.member.posts.at(connection, {
    postId: post.id,
  });
  typia.assert(detail);
  // 5. Field-level and business logic validation
  TestValidator.equals("post id matches")(detail.id)(post.id);
  TestValidator.equals("title matches")(detail.title)(post.title);
  TestValidator.equals("body matches")(detail.body)(post.body);
  TestValidator.equals("attachments match")(detail.attachments)(post.attachments);
  TestValidator.equals("status is active")(detail.status)("active");
  TestValidator.predicate("not soft-deleted")(detail.deleted_at === null || detail.deleted_at === undefined);
  TestValidator.equals("author_member_id present")(typeof detail.author_member_id === "string")(true);
  TestValidator.equals("category present")(typeof detail.category === "object" && !!detail.category.id)(true);
  TestValidator.predicate("created_at string")(typeof detail.created_at === "string");
  TestValidator.predicate("updated_at string")(typeof detail.updated_at === "string");
}

