import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Test access enforcement for member post retrieval endpoint – only authenticated members may access.
 *
 * This test ensures the /discussionBoard/member/posts/{postId} endpoint denies access for:
 *  - Guests (JWT obtained via /auth/guest/login)
 *  - Requests with an invalid (malformed/corrupted) JWT
 *  - Requests without any Authorization header
 *
 * This verifies proper forbidden error enforcement for sensitive member-only data, ensuring API security policy.
 *
 * Steps:
 * 1. Generate a random (likely non-existent) post UUID to use as a target.
 * 2. Obtain a guest JWT by calling the guest login endpoint.
 * 3. Attempt to access the member post using the guest JWT and expect access to be denied.
 * 4. Attempt to access the member post using a clearly invalid JWT and expect access to be denied.
 * 5. Attempt to access the member post with no Authorization header and expect access to be denied.
 */
export async function test_api_member_post_read_permission_enforcement_guest_or_invalid_jwt(
  connection: api.IConnection,
) {
  // 1. Prepare random post UUID (test assumes post absence is not distinguishable from forbidden)
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 2. Obtain a guest JWT (simulate guest user session)
  const guestAuth = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: "E2E-Guest-Test-Agent",
      ip_address: "127.0.0.1",
    },
  });
  typia.assert(guestAuth);

  // 3. Attempt access as a guest (should be forbidden)
  const guestConn = {
    ...connection,
    headers: { ...(connection.headers ?? {}), Authorization: guestAuth.token },
  };
  await TestValidator.error("guest access should be forbidden")(() =>
    api.functional.discussionBoard.member.posts.at(guestConn, { postId }),
  );

  // 4. Attempt access with an invalid JWT
  const invalidConn = {
    ...connection,
    headers: { ...(connection.headers ?? {}), Authorization: "Bearer INVALID.JWT.TOKEN" },
  };
  await TestValidator.error("invalid JWT should be forbidden")(() =>
    api.functional.discussionBoard.member.posts.at(invalidConn, { postId }),
  );

  // 5. Attempt access with no Authorization header
  const connNoAuth = { ...connection, headers: { ...connection.headers ?? {} } };
  delete connNoAuth.headers.Authorization;
  await TestValidator.error("no auth header should be forbidden")(() =>
    api.functional.discussionBoard.member.posts.at(connNoAuth, { postId }),
  );
}

