/**
 * Test updating an existing permission matrix (RBAC entry) as an admin and verify all changes and audit fields are correctly applied.
 *
 * 1. Register a new admin via /auth/admin/register (precondition for authentication)
 * 2. Log in as the registered admin via /auth/admin/login to obtain an access token in the connection
 * 3. Create a new permission matrix entry via /discussionBoard/admin/permissionMatrices (serves as baseline for update)
 * 4. Update the permission matrix with new allowed/action/resource values via /discussionBoard/admin/permissionMatrices/{permissionMatrixId}
 * 5. Validate the returned permission matrix contains the correct id and reflects all the updated fields
 * 6. Ensure audit fields (created_at, updated_at) are correctly managed: updated_at changes, created_at is preserved
 * 7. Validate any other business rules: uniqueness, type safety, all response types
 */
export async function test_api_permission_matrix_update_success(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResponse = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IDiscussionBoardAdmin.ICreate,
    },
  );
  typia.assert(adminSignUpResponse);

  // 2. Admin login
  const adminSignInResponse = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IDiscussionBoardAdmin.ILogin,
    },
  );
  typia.assert(adminSignInResponse);

  // 3. Create original permission matrix
  const origPermissionCreate: IDiscussionBoardPermissionMatrix.ICreate = {
    role_name: "admin",
    resource: "post",
    action: "read",
    allowed: false,
    effective_from: new Date().toISOString(),
    effective_to: null,
  };
  const createdMatrix =
    await api.functional.discussionBoard.admin.permissionMatrices.create(
      connection,
      {
        body: origPermissionCreate,
      },
    );
  typia.assert(createdMatrix);

  // 4. Update permission matrix with new values
  const updateBody: IDiscussionBoardPermissionMatrix.IUpdate = {
    allowed: true,
    resource: "comment",
    action: "write",
  };
  const updatedMatrix =
    await api.functional.discussionBoard.admin.permissionMatrices.update(
      connection,
      {
        permissionMatrixId: createdMatrix.id,
        body: updateBody,
      },
    );
  typia.assert(updatedMatrix);

  // 5. Validate the matrix id matches
  TestValidator.equals("permission matrix id matches")(
    updatedMatrix.id,
  )(createdMatrix.id);
  // 6. Validate updated fields
  TestValidator.equals("allowed updated")(updatedMatrix.allowed)(true);
  TestValidator.equals("resource updated")(updatedMatrix.resource)("comment");
  TestValidator.equals("action updated")(updatedMatrix.action)("write");
  // Unchanged fields
  TestValidator.equals("role_name unchanged")(
    updatedMatrix.role_name,
  )(createdMatrix.role_name);
  // 7. Audit fields: created_at must be unchanged, updated_at must advance
  TestValidator.equals("created_at unchanged")(
    updatedMatrix.created_at,
  )(createdMatrix.created_at);
  TestValidator.predicate("updated_at advanced")(
    typeof updatedMatrix.updated_at === "string" &&
      updatedMatrix.updated_at > createdMatrix.updated_at,
  );
  // 8. Soft deletion untouched
  TestValidator.equals("deleted_at still null or same")(
    updatedMatrix.deleted_at,
  )(createdMatrix.deleted_at ?? null);
  // 9. Other fields (effectivity windows) preserved unless explicitly changed
  TestValidator.equals("effective_from unchanged")(
    updatedMatrix.effective_from,
  )(createdMatrix.effective_from);
  TestValidator.equals("effective_to unchanged")(
    updatedMatrix.effective_to,
  )(createdMatrix.effective_to ?? null);
}

