    ...connection,
    headers: Object.fromEntries(Object.entries(connection.headers || {}).filter(([k]) => k.toLowerCase() !== "authorization")),
  };
  await TestValidator.error("forbidden: guest cannot erase via admin endpoint")(
    async () =>
      api.functional.discussionBoard.admin.commentReports.erase(guestConnection, {
        commentReportId: report.id,
      }),
  );
}

