 * 2. As this member, create a new discussion post (required for commenting).
 * 3. On the created post, submit an initial comment.
 * 4. Immediately update that comment's body field with new content (within edit window).
 * 5. Validate the API correctly returns the updated comment object:
 *    - The body is updated.
 *    - The updated_at timestamp is newer than the original.
 *    - The id, post_id, and author_member_id remain unchanged.
 *    - Comment audit and relation fields are properly preserved.
 *    - No fields for moderator/admin authorship are present (null).
 *
 * This ensures the comment editing API enforces author, edit-policy, and audit integrity.
 */
export async function test_api_comment_update_by_member_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    nickname: RandomGenerator.name(),
    avatar_uri: null,
  };
  const memberSession = await api.functional.auth.member.register.signUp(connection, { body: memberInput });
