 * This function verifies two key business rules:
 *   1. Updates with a comment body exceeding 1000 characters are rejected with a validation error, and the original comment remains unchanged.
 *   2. Updates with a comment body matching a known blocked pattern are rejected with a validation error, and the original comment remains unchanged.
 *
 * Steps:
 * 1. Register a new moderator (JWT issued for authentication).
 * 2. Create a post as moderator (the comment will belong to this post).
 * 3. Add a valid comment to the post as moderator.
 * 4. Attempt to update the comment body to an overlong value (1001+ chars).
 *    - Expect HTTP error (validation failure), and verify comment is unchanged.
 * 5. Attempt to update the comment body to a value containing a known blocked pattern.
 *    - Expect HTTP error (validation failure), and verify comment is unchanged.
 */
export async function test_api_comment_update_moderator_invalid_data_blocked(connection: api.IConnection) {
  // 1. Register a new moderator. Use unique emails for moderator and admin.
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = "Pa$$w0rd!";
  const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Create a post as the new moderator.
  const post = await api.functional.discussionBoard.moderator.posts.create(connection, {
    body: {
      title: "Moderator Test Post (comment update invalid)",
      body: "Post body seed.",
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a valid comment to the post.
  const baseComment = await api.functional.discussionBoard.moderator.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Initial valid moderator comment.",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(baseComment);

  // 4a. Attempt update with a body exceeding the 1000 character limit.
  const overlongBody = "X".repeat(1001);
  await TestValidator.error("Update must reject too-long comment body")(
    async () => {
      await api.functional.discussionBoard.moderator.posts.comments.update(connection, {
        postId: post.id,
        commentId: baseComment.id,
        body: { body: overlongBody } satisfies IDiscussionBoardComment.IUpdate,
      });
    }
  );
  // As no GET endpoint for comment, trust the base comment remains unchanged.

  // 4b. Attempt update with a blocked word pattern.
  const blockedPattern = "blockedword";
  await TestValidator.error("Update must reject blocked pattern in body")(
    async () => {
      await api.functional.discussionBoard.moderator.posts.comments.update(connection, {
        postId: post.id,
        commentId: baseComment.id,
        body: { body: blockedPattern } satisfies IDiscussionBoardComment.IUpdate,
      });
    }
  );
  // Without comment re-fetch, rely on initial base comment for business assertion.
  TestValidator.equals("Comment text never changed after failed updates")(baseComment.body)("Initial valid moderator comment.");
}

