 *
 * This test covers authorization boundaries for notification search within the administration context. It ensures that only users with admin privileges may access the admin-level notification search endpoint with PATCH. Non-admin roles—member, moderator, and unauthenticated guests—must all be denied, and their access attempts logged for auditing. The scenario involves registering a member account, registering an admin (so the admin may assign a moderator), and using those credentials to simulate unauthorized access attempts. Guest/anonymous access is tested by making the call without credentials.
 *
 * Steps:
 * 1. Register an admin (for test setup, not for positive case here)
 * 2. Register a member and obtain session
 * 3. Register a moderator (with association to the admin) and obtain session
 * 4. Attempt to PATCH /discussionBoard/admin/notifications as:
 *     a. Member (should fail: forbidden/unauthorized)
 *     b. Moderator (should fail: forbidden/unauthorized)
 *     c. Guest (unauthenticated: should fail unauthorized)
 * 5. Confirm all failures are access denied (i.e., error is thrown)
 */
export async function test_api_notification_admin_search_forbidden_for_non_admin_roles(connection: api.IConnection) {
  // 1. Register an admin (setup for assignment)
  const adminEmail = typia.random<string & tags.Format<"email">>();
