  // 3. Register a moderator account (must assign using the admin's email)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModeratorPw!234";
  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorRegister);

  /**
   * Helper function to assert forbidden/unauthorized access for a given connection.
   * Uses TestValidator.error to ensure API call results in error and thus forbidden.
   */
  async function assertForbiddenCall(testConnection: api.IConnection, note: string) {
    await TestValidator.error(note)(async () => {
      await api.functional.discussionBoard.admin.notifications.search(testConnection, {
