  // 4b. Moderator (non-admin) attempts admin notification search (forbidden)
  const moderatorConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: moderatorRegister.setHeaders.Authorization,
    },
  };
  await assertForbiddenCall(moderatorConnection, "moderator forbidden on admin notification search");

  // 4c. Guest (no auth header) attempts admin notification search (unauthorized)
  await assertForbiddenCall(connection, "guest unauthorized on admin notification search");
}

