import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test PATCH /discussionBoard/moderator/notifications with filters that guarantee no matching records.
 *
 * Ensures the API returns an empty notification result set with correct pagination metadata (records=0, data length=0) and does not produce errors or unexpected outputs.
 *
 * Workflow:
 * 1. Register and authenticate a new moderator (dependency: only admin can assign/register a moderator).
 * 2. As this moderator, call the notifications search endpoint with filters that will not match any records (e.g., fake event_type and random recipient_id, with a future-only date window).
 * 3. Verify: (a) response type per contract, (b) data array is empty, (c) pagination records==0 and pages==0 or 1, (d) no error thrown.
 * 4. Assert using strict type validation and curried TestValidator APIs.
 */
export async function test_api_notification_moderator_search_filter_no_result(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new moderator (precondition: only admin can assign moderators)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.moderator.register.signUp(
    connection,
    {
      body: {
        email: moderatorEmail,
        assigned_by_admin_email: adminEmail,
        password: moderatorPassword,
      } satisfies IModerator.SignUp,
    },
  );
  typia.assert(signUpResponse);
  // Moderator is now authenticated for subsequent requests.

  // 2. Search for notifications with a filter that is guaranteed to match no records.
  // Use a nonsense event_type and a random recipient_id (UUID) never used, and a date range in the far future.
  const unmatchableFilter: IDiscussionBoardNotification.IRequest = {
    event_type: "fake_type_" + RandomGenerator.alphaNumeric(8), // nonsensical event_type not present in system
    recipient_id: typia.random<string & tags.Format<"uuid">>(), // random UUID, never assigned
    created_at_from: "2100-01-01T00:00:00.000Z", // far future, no records should exist
    created_at_to: "2100-12-31T23:59:59.999Z",
    recipient_role: "moderator",
    page: 1,
    limit: 10,
    unread: null,
    related_entity_type: null,
  };
  const output = await api.functional.discussionBoard.moderator.notifications.search(
    connection,
    { body: unmatchableFilter },
  );
  typia.assert(output);

  // 3. Validate: (a) type, (b) data is empty, (c) pagination.records/pages correct.
  TestValidator.equals("data array is empty")(output.data)([]);
  TestValidator.equals("zero records")(output.pagination.records)(0);
  TestValidator.predicate("pages is 0 or 1")(output.pagination.pages === 0 || output.pagination.pages === 1);
  TestValidator.equals("pagination limit")(output.pagination.limit)(unmatchableFilter.limit);
  TestValidator.equals("pagination current page")(output.pagination.current)(unmatchableFilter.page);
}

