/**
 * Test reporting a non-existent or deleted comment as a member should result in error.
 *
 * This test covers two negative scenarios for comment reporting:
 * 1. Attempting to report a completely random (non-existing) comment ID.
 * 2. Attempting to report a comment that was created and then deleted (soft deletion).
 *
 * The API should respond with a not-found or validation error for both cases, and must not create a report record.
 *
 * **Workflow:**
 * 1. Register a new discussion board member
 * 2. Log in as the member to obtain valid session
 * 3. Create a post (to serve as the parent for comments)
 * 4. Create a comment under the post
 * 5. Delete (soft-delete) the created comment
 * 6. Attempt to report a random non-existent comment ID — expect error
 * 7. Attempt to report the soft-deleted comment — expect error
 */
export async function test_api_member_comment_report_comment_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = "1234!@Test";
  const nickname: string = RandomGenerator.alphaNumeric(8);
