    body: {
      email,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });

  // 2. Log in as the member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardMember.ILogin,
  });

  // 3. Create a post
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1, 3),
        body: RandomGenerator.content()()(1, 5),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Create a comment under the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(
    connection,
    {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(1, 2),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 5. Delete the created comment (soft delete)
  await api.functional.discussionBoard.member.posts.comments.erase(
    connection,
    {
      postId: post.id,
      commentId: comment.id,
    },
  );

  // 6. Attempt to report a random, non-existent comment ID
