import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator update of comment report status and resolution actions.
 *
 * This E2E test covers the workflow for handling comment abuse reports as a moderator:
 *
 * 1. Register a moderator (requires admin email), then log in to obtain moderator session.
 * 2. Register and log in as a member; this member will create a post and a comment to be reported.
 * 3. As the member, create a new discussion board post.
 * 4. As the member, comment on the created post.
 * 5. As the member, submit a comment report against their own comment.
 * 6. Switch to moderator account, and update the status of the report to 'in_review', add resolution notes, and set handler.
 * 7. Update again to 'action_taken' with updated notes, confirming workflow status transitions and audit fields are correct.
 * 8. Attempt to update an already "finalized" (action_taken or rejected) comment report to verify modifications are rejected.
 * 9. (Edge) Attempt to update a non-existent or deleted report and confirm error response.
 * 10. At each update, verify status, resolution, handler, and audit fields are changed as expected, and only allowed transitions proceed.
 */
export async function test_api_moderator_comment_report_update_resolution_by_moderator(connection: api.IConnection) {
  // 1. Register moderator and login (moderator workflow)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPassword!1";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorSignUp);
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);

  // 2. Register and login member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPassword!2";
  const memberNickname = RandomGenerator.name();
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    },
  });
  typia.assert(memberSignUp);
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberLogin);

  // 3. As member, create post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().substring(0, 100),
      body: RandomGenerator.content()()().substring(0, 4000),
    },
  });
  typia.assert(post);

  // 4. As member, create comment on the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Reported comment content " + RandomGenerator.alphaNumeric(8),
    },
  });
  typia.assert(comment);

  // 5. As member, report the comment
  const commentReport = await api.functional.discussionBoard.member.commentReports.create(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      reason_type: "spam",
      reason_text: "Contains spam or promotional material.",
    },
  });
  typia.assert(commentReport);

  // 6. Switch to moderator context (token injection)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorLogin.setHeaders.Authorization,
  };

  // 7. Moderator updates report to in_review
  const updatedInReview = await api.functional.discussionBoard.moderator.commentReports.update(connection, {
    commentReportId: commentReport.id,
    body: {
      status: "in_review",
      resolution_message: "Reviewing reported comment.",
      handler_admin_id: moderatorSignUp.moderator_id,
    },
  });
  typia.assert(updatedInReview);
  TestValidator.equals("Report status after in_review")(updatedInReview.status)("in_review");
  TestValidator.equals("Handler assigned")(updatedInReview.handler_admin_id)(moderatorSignUp.moderator_id);
  TestValidator.equals("Resolution message")(updatedInReview.resolution_message)("Reviewing reported comment.");

  // 8. Moderator updates report to action_taken
  const actionTakenMessage = "Action taken against comment.";
  const updatedActionTaken = await api.functional.discussionBoard.moderator.commentReports.update(connection, {
    commentReportId: commentReport.id,
    body: {
      status: "action_taken",
      resolution_message: actionTakenMessage,
      handler_admin_id: moderatorSignUp.moderator_id,
    },
  });
  typia.assert(updatedActionTaken);
  TestValidator.equals("Report status after action_taken")(updatedActionTaken.status)("action_taken");
