import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Moderator paginated analytics search for user metrics with filters and data setup.
 *
 * This test validates the end-to-end workflow where a moderator searches for user metrics analytics
 * with pagination and filters. All dependencies are set up:
 * 1. A moderator is registered using a random moderator and admin email.
 * 2. Multiple members are registered for metrics population.
 * 3. User metric analytics entities are initialized for each member (as admin).
 *
 * Then, as the moderator, the test performs a paginated PATCH search over user metrics with filters:
 * - Paginates (page 1, limit 3), sorted by reputation descending.
 * - Filters on reputation_score_min.
 *
 * Test asserts:
 * - Pagination metadata is present and correct.
 * - Returned entities array length matches pagination parameters.
 * - All user metrics fields are present and correctly typed.
 * - At least one result matches the filter (reputation_score >= min).
 * - No admin-only restriction blocks result for moderator.
 */
export async function test_api_user_metrics_search_by_moderator_success(connection: api.IConnection) {
  // 1. Register a moderator (assign random admin and moderator email)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const modSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: "TestModPass!234",
    } satisfies IModerator.SignUp,
  });
  typia.assert(modSignUp);

  // 2. Register multiple members
  const memberSessions: IDiscussionBoardMember.ISession[] = await ArrayUtil.asyncRepeat(5)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const session = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password: "UserPass#1234",
        nickname: RandomGenerator.alphaNumeric(8),
        avatar_uri: null,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(session);
    return session;
  });

  // 3. For each member, create user metric analytics (as admin)
  const now = Date.now();
  for (const session of memberSessions) {
    await api.functional.discussionBoard.admin.userMetrics.create(connection, {
      body: {
        discussion_board_member_id: session.member.id,
        posts_count: typia.random<number & tags.Type<"int32">>(),
        comments_count: typia.random<number & tags.Type<"int32">>(),
        votes_up_given_count: typia.random<number & tags.Type<"int32">>(),
        votes_down_given_count: typia.random<number & tags.Type<"int32">>(),
        reports_made_count: typia.random<number & tags.Type<"int32">>(),
        reputation_score: typia.random<number & tags.Type<"int32">>(),
        last_activity_at: new Date(now - 3600*1000*Math.floor(Math.random()*48)).toISOString(),
      } satisfies IDiscussionBoardUserMetric.ICreate,
    });
  }

  // 4. As moderator, perform paginated search with filter
  const minReputation = 0;
  const limit = 3;
  const page = 1;
  const resp = await api.functional.discussionBoard.moderator.userMetrics.search(connection, {
    body: {
      page,
      limit,
      reputation_score_min: minReputation,
      order_by: "reputation_score",
      order_direction: "desc",
    } satisfies IDiscussionBoardUserMetric.IRequest,
  });
  typia.assert(resp);

  // 5. Pagination validations
  TestValidator.predicate("pagination present")(!!resp.pagination && typeof resp.pagination.current === "number");
  TestValidator.equals("pagination current page")(resp.pagination.current)(page);
  TestValidator.equals("pagination limit")(resp.pagination.limit)(limit);
  TestValidator.predicate("pagination count <= limit")(resp.data.length <= limit);
  TestValidator.predicate("pagination records logic")(resp.pagination.records >= resp.data.length);
  TestValidator.predicate("pagination pages logic")(resp.pagination.pages >= 1);

  // 6. Validate user metrics returned
  for (const userMetric of resp.data) {
    typia.assert(userMetric);
    TestValidator.predicate("has id")(!!userMetric.id);
    TestValidator.predicate("has discussion_board_member_id")(!!userMetric.discussion_board_member_id);
    TestValidator.predicate("has posts count")(typeof userMetric.posts_count === "number");
    TestValidator.predicate("has comments count")(typeof userMetric.comments_count === "number");
    TestValidator.predicate("has votes counts")(typeof userMetric.votes_up_given_count === "number" && typeof userMetric.votes_down_given_count === "number");
    TestValidator.predicate("has reports_made_count")(typeof userMetric.reports_made_count === "number");
    TestValidator.predicate("has reputation_score")(typeof userMetric.reputation_score === "number");
    TestValidator.predicate("has created_at/updated_at")(!!userMetric.created_at && !!userMetric.updated_at);
    // Optional property
    TestValidator.predicate("last_activity_at nullable")(userMetric.last_activity_at === null || typeof userMetric.last_activity_at === "string");
  }

  // 7. At least one entry passes minReputation filter
  TestValidator.predicate("at least one returned passes min reputation")(
    resp.data.some(m => m.reputation_score >= minReputation)
  );

  // 8. Confirm result not restricted to admin-only for moderator
  // (If forbidden, API would error; else, all entries visible)
  TestValidator.predicate("moderator result visibility")(Array.isArray(resp.data));
}

