 * 7. As the moderator user, attempt to soft-delete the comment using the admin endpoint: expect 403 forbidden.
 *
 * This verifies RBAC for admin-only comment deletion functionality.
 */
export async function test_api_admin_comment_soft_delete_unauthorized_role(connection: api.IConnection) {
