/**
 * Validate searching and paginating post vote records filtered by both member ID and post ID, ensuring only the correct vote(s) are returned.
 *
 * This test covers the following business scenario:
 *   1. Registers an admin user and a regular member (the voter).
 *   2. Member creates a forum post.
 *   3. Member upvotes the created post.
 *   4. Member also creates and votes on a second post (ensuring non-matched votes exist).
 *   5. Admin uses the /discussionBoard/admin/postVotes search API, filtering on both the member's ID and the first post's ID.
 *   6. Verifies that only the expected vote is present in search results, and extra noise votes are excluded.
 *
 * Steps:
 *   1. Register an admin
 *   2. Register a member (the upvoter)
 *   3. As member, create the target post
 *   4. As member, upvote that post
 *   5. As member, create a second post and upvote it (to test exclusion)
 *   6. Switch to admin identity in the connection
 *   7. Search by both member ID and post ID using admin API
 *   8. Assert that only the specific vote record is returned, with correct member, post, and is_upvote properties
 */
export async function test_api_admin_post_vote_search_by_member_and_post(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adm1n!" + RandomGenerator.alphaNumeric(8);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminReg);

  // 2. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Mb3r!" + RandomGenerator.alphaNumeric(8);
  const memberNickname = RandomGenerator.name();
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberReg);
  const memberId = memberReg.member.id;

  // 3. Member creates the target post
  const postTitle = RandomGenerator.paragraph()().slice(0, 90);
  const postBody = RandomGenerator.content()()().slice(0, 3900);
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Upvote that post
  const vote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_upvote: true,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(vote);

  // 5. As member, create a noise post & upvote it (control for filter exclusion)
  const noisePost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().slice(0, 90),
      body: RandomGenerator.content()()().slice(0, 3900),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(noisePost);
  const noiseVote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: noisePost.id,
      is_upvote: true,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(noiseVote);

  // 6. Switch to admin (by setting the Authorization header from adminReg)
  connection.headers = { ...connection.headers, Authorization: adminReg.setHeaders.Authorization };

  // 7. Admin searches for votes filtered by both memberId and postId (should find only the intended vote)
  const result = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      discussion_board_member_id: memberId,
      discussion_board_post_id: post.id,
      page: 1 as 1,
      limit: 10 as 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(result);

  // 8. Assertions for business correctness
  TestValidator.equals("votes count should be 1")(result.pagination.records)(1);
  TestValidator.equals("returned data length")(result.data.length)(1);
  const returnedVote = result.data[0];
  TestValidator.equals("vote.member matches")(returnedVote.discussion_board_member_id)(memberId);
  TestValidator.equals("vote.post matches")(returnedVote.discussion_board_post_id)(post.id);
  TestValidator.equals("vote is an upvote")(returnedVote.is_upvote)(true);
}

