import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate admin search for post votes supports pagination and handles invalid filters robustly.
 *
 * This test ensures that the admin post vote search endpoint correctly processes pagination requests and deals robustly with invalid filter parameters (non-existent memberId or postId). It validates that the API does not crash, break pagination, or behave unexpectedly, and that it returns either an empty result or an appropriate error (not a transport or server error) when filters do not match existing records.
 *
 * 1. Register a new admin user to obtain authorization.
 * 2. Attempt to search for post votes with a non-existent discussion_board_member_id filter.
 * 3. Confirm the API returns an empty result set and valid pagination metadata, without errors or instabilities.
 * 4. Attempt to search for post votes with a non-existent discussion_board_post_id filter.
 * 5. Confirm the API again returns an empty result, correct pagination metadata, and no errors.
 * 6. Optionally, try invalid pagination parameters (e.g., page=1000000) and confirm robust empty handling or appropriate validation.
 *
 * All responses must pass type assertion and API must remain stable for all scenarios.
 */
export async function test_api_admin_post_vote_search_pagination_and_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminAuth: IDiscussionBoardAdminAuthResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Set admin JWT header for authorization
  connection.headers = { ...connection.headers, ...adminAuth.setHeaders };

  // 2. Search with a non-existent member ID filter
  const outputByMember: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputByMember);
  TestValidator.equals("empty results - memberId")(outputByMember.data.length)(0);
  TestValidator.predicate("valid pagination - memberId")(outputByMember.pagination !== undefined && outputByMember.pagination.current === 1);

  // 3. Search with a non-existent post ID filter
  const outputByPost: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputByPost);
  TestValidator.equals("empty results - postId")(outputByPost.data.length)(0);
  TestValidator.predicate("valid pagination - postId")(outputByPost.pagination !== undefined && outputByPost.pagination.current === 1);

  // 4. Search with an absurdly high page number to confirm stable pagination/empty results
  const outputHighPage: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      page: 1000000,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputHighPage);
  TestValidator.predicate("no crash on high page")(outputHighPage.data.length === 0 || outputHighPage.pagination.current === 1000000);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";
import type { IPageIDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator's ability to filter and paginate post vote records by vote type (upvote or downvote).
 *
 * Business context: Moderators need to filter vote actions (upvotes or downvotes) for audit/tracking/community management, ensuring the analytics/search functionality returns only relevant vote records and correct pagination metadata for the query. This test covers positive and negative votes, ensuring the filter parameter 'is_upvote' controls behavior as intended.
 *
 * Test Steps (End-to-End Workflow):
 * 1. Register a moderator (for search capability).
 * 2. Register a member (to author and vote on discussion board posts).
 * 3. Member creates a post.
 * 4. Member votes (upvote) on the first post.
 * 5. Member creates and downvotes a second post.
 * 6. Moderator fetches votes with 'is_upvote' true – only upvotes should be found.
 * 7. Moderator fetches votes with 'is_upvote' false – only downvotes should be found.
 * 8. Each response and result set is validated: All returned records match the filter, and the expected vote is present, while the opposite type is absent.
 *
 * Note: Since no separate login endpoint is available for moderator role, the moderator's JWT token is taken directly from the sign-up response.
 */
export async function test_api_moderator_post_vote_search_by_vote_type(connection: api.IConnection) {
  // 1. Register moderator: get JWT from sign-up response
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderatorPW123!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword
    } satisfies IModerator.SignUp
  });
  typia.assert(moderatorSignUp);

  // 2. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "memberPW123!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSession);

  // 3. Member creates first post
  connection.headers = { Authorization: `Bearer ${memberSession.token}` };
  const post1 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      attachments: null
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post1);

  // 4. Member casts an upvote on post1
  const upvote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post1.id,
      is_upvote: true
    } satisfies IDiscussionBoardPostVote.ICreate
  });
  typia.assert(upvote);

  // 5. Member creates and downvotes a second post
  const post2 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      attachments: null
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post2);
  const downvote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post2.id,
      is_upvote: false
    } satisfies IDiscussionBoardPostVote.ICreate
  });
  typia.assert(downvote);

  // 6. Switch to moderator: use JWT/token from sign-up response
  connection.headers = { Authorization: moderatorSignUp.setHeaders.Authorization };

  // 7. Moderator queries all upvotes (is_upvote: true)
  const upvoteSearch = await api.functional.discussionBoard.moderator.postVotes.search(connection, {
    body: { is_upvote: true, page: 1, limit: 10 }
  });
  typia.assert(upvoteSearch);
  TestValidator.predicate("all results are upvotes")(upvoteSearch.data.every(vote => vote.is_upvote === true));
  TestValidator.equals("upvote vote exists")(
    upvoteSearch.data.some(vote => vote.id === upvote.id)
  )(true);
  TestValidator.equals("downvote vote not present")(
    upvoteSearch.data.some(vote => vote.id === downvote.id)
  )(false);

  // 8. Moderator queries all downvotes (is_upvote: false)
  const downvoteSearch = await api.functional.discussionBoard.moderator.postVotes.search(connection, {
    body: { is_upvote: false, page: 1, limit: 10 }
  });
  typia.assert(downvoteSearch);
  TestValidator.predicate("all results are downvotes")(downvoteSearch.data.every(vote => vote.is_upvote === false));
  TestValidator.equals("downvote vote exists")(
    downvoteSearch.data.some(vote => vote.id === downvote.id)
  )(true);
  TestValidator.equals("upvote vote not present")(
    downvoteSearch.data.some(vote => vote.id === upvote.id)
  )(false);
}

