 *
 * Steps:
 * 1. Register a new moderator (to receive a moderator JWT).
 * 2. Register a regular member.
 * 3. Use the member session to attempt a moderator-only search -- expect access denied error.
 * 4. Use the moderator session to perform the search -- expect normal result (paginated, no error).
 */
export async function test_api_moderator_post_vote_search_access_control(connection: api.IConnection) {
  // 1. Register a moderator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestModPW!23";
  const moderatorResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResp);

  // 2. Register a regular member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestMemberPW!23";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Member tries to search post votes (should be forbidden)
  connection.headers = { ...connection.headers, Authorization: memberSession.setHeaders.Authorization };
  await TestValidator.error("member search forbidden")(() =>
    api.functional.discussionBoard.moderator.postVotes.search(connection, {
      body: {},
