  // 4. Moderator performs post vote search (should succeed)
  connection.headers = { ...connection.headers, Authorization: moderatorResp.setHeaders.Authorization };
  const searchResult = await api.functional.discussionBoard.moderator.postVotes.search(connection, {
    body: {},
  });
  typia.assert(searchResult);
  TestValidator.predicate("paginated vote search result structure")(
    typeof searchResult.pagination === "object" && Array.isArray(searchResult.data)
  );
