import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate error handling for double soft-delete attempts by a moderator on a discussion board post.
 *
 * Business context:
 * Moderators must not be able to soft-delete (logically delete) the same post more than once. This test validates that when a post has already been soft-deleted, any further delete attempts return a clear error (such as an error status or message), ensuring data integrity and proper feedback mechanisms for moderators.
 *
 * Step-by-step process:
 * 1. Register a new moderator, receiving a valid moderator JWT for authentication.
 * 2. Create a post as the authenticated moderator (the post should be active on creation).
 * 3. Perform a DELETE (soft-delete) action on the post by its postId as the moderator (post is logically deleted, deleted_at is set, status updated e.g. to 'deleted').
 * 4. Attempt to DELETE the same post again as the moderator.
 * 5. Validate that the second delete operation returns an error, confirming the post cannot be deleted twice and the API returns the correct error semantics.
 */
export async function test_api_post_soft_delete_by_moderator_already_deleted_post(connection: api.IConnection) {
  // 1. Register a moderator (and gain authorization as that moderator)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = "$Test12345!";

  const signUpResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpResponse);

  // SDK should update the connection's Authorization header. Use moderator token to act as moderator from now on.

  // 2. Create a post as moderator
  const createdPost = await api.functional.discussionBoard.moderator.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      // Minimal create; no attachments, platform_config_id, or category_id for this test.
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(createdPost);

  // 3. Soft-delete the post (first delete)
  await api.functional.discussionBoard.moderator.posts.erase(connection, {
    postId: createdPost.id,
  });

  // 4. Attempt to delete the same post again — should return an error
  await TestValidator.error("Post cannot be deleted twice")(() =>
    api.functional.discussionBoard.moderator.posts.erase(connection, {
      postId: createdPost.id,
    })
  );
}

