/**
 * Validate admin soft-delete (logical removal) of a discussion board post.
 *
 * This test ensures:
 * - An admin can register and authenticate.
 * - The admin can create a post.
 * - The admin can soft-delete their own post.
 * - The post is correctly marked as deleted in status and audit fields (including 'deleted_at'), but this can't be validated post-deletion due to lack of fetch APIs.
 * - The deleted post is no longer available in typical listings (not implemented, as index/search endpoints are not provided).
 * - The post remains reviewable by moderator/admin-privilege endpoints (simulate by fetching as admin again if there was an endpoint; omitted since listing/fetch-by-id for deleted posts doesn't exist).
 * - Audit fields reflect the deletion (deleted_at updated, status set as 'deleted'), as much as can be inferred by lack of error on erase.
 * - The operation completes without errors and is fully logged by status change as implied by scenario and API contract.
 *
 * Steps:
 * 1. Register a new admin (receive access token and identity).
 * 2. As admin, create a new post (capture postId).
 * 3. Soft-delete the post with the admin's authorization.
 * 4. Validate business flow as far as API allows (direct post state after deletion cannot be fetched, so assert by lack of error).
 */
export async function test_api_post_soft_delete_by_admin_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234abcd";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // The registration should set the access token in connection.headers via SDK, so subsequent requests are admin-privileged

  // 2. Create a post as admin
  const postCreate: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1).slice(0, 100), // Ensure max 100 chars
    body: RandomGenerator.content()()(1).slice(0, 4000), // Ensure max 4000 chars
    attachments: null,
    category_id: null,
    platform_config_id: null,
  };

  const post = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: postCreate,
  });
  typia.assert(post);

  TestValidator.equals("Post title")(post.title)(postCreate.title);
  TestValidator.equals("Post body")(post.body)(postCreate.body);
  TestValidator.equals("Not deleted after creation")(post.deleted_at)(null);
  TestValidator.equals("Active status after creation")(post.status)("active");
  TestValidator.equals("Admin authored")(typeof post.author_admin_id === "string")(true);

  // 3. Admin soft-deletes the post
  await api.functional.discussionBoard.admin.posts.erase(connection, {
    postId: post.id,
  });
  // 4. There is no endpoint provided to fetch a post after deletion or list posts with status filters in the current API set; we must limit our verification to assumptions based on SDK output.
  // This test therefore verifies that the erase operation completes without error, and initial expectations about post state after creation are satisfied.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate error condition for repeated soft-deletion of a discussion board post by an admin.
 *
 * This test ensures that if an admin tries to delete a post in the discussion board which has already been soft-deleted (logical removal), the API returns a clear error response (e.g., not found or already deleted).
 * The business rule is that admins may only delete existing, non-deleted posts; second or repeated delete attempts should not succeed and must produce a business error.
 *
 * Step-by-step process:
 * 1. Register a new admin to obtain authorization, using /auth/admin/register.
 * 2. Create a new post as the admin via /discussionBoard/admin/posts (must set title and body to meet validation rules).
 * 3. Perform a soft-delete of the post using /discussionBoard/admin/posts/{postId} DELETE (should succeed).
 * 4. Attempt another soft-delete on the same post (should fail), validating that an error is thrown indicating post is already deleted or not found.
 * 5. Use TestValidator.error to confirm proper error handling for the redundant delete operation.
 */
export async function test_api_post_soft_delete_by_admin_already_deleted_post(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = "TestPassword123!";
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRes);
  // At this point, connection.headers.Authorization is set for the admin

  // 2. Create a new post as the admin
  const post = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: {
      title: "Integration test for redundant soft delete",
      body: "This post will be created and deleted to validate redundant soft-deletion error handling.",
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Perform initial (successful) soft-delete
  await api.functional.discussionBoard.admin.posts.erase(connection, {
    postId: post.id,
  });

  // 4. Attempt to soft-delete AGAIN (should result in an error)
  await TestValidator.error("Redundant soft-deletion must fail")(
    async () => {
      await api.functional.discussionBoard.admin.posts.erase(connection, {
        postId: post.id,
      });
    },
  );
}

