/**
 * Validate successful retrieval of a single comment by its commentId and postId.
 *
 * This test covers the following end-to-end workflow on the discussion board:
 * 1. Register a new member (to own posts and comments)
 * 2. Create a new post as the registered member
 * 3. Write a top-level comment under the post
 * 4. Optionally, create a reply thread comment (child comment) under the first comment
 * 5. Retrieve the comment (either top-level or reply) using its unique commentId and its parent postId
 * 6. Assert that the returned comment matches the created comment (body, author, parent ID, status, etc.)
 * 7. Verify that the comment can be viewed by the author
 * 8. (Optionally) Test that deleted/hidden comments cannot be seen by unauthorized users (skipped here due to lack of multi-role support in provided APIs)
 *
 * The test ensures all major fields are returned, referential integrity is kept, and authorship is respected. It only tests what is technically possible with the provided SDK and DTOs.
 */
export async function test_api_comment_retrieval_success(connection: api.IConnection) {
  // 1. Register a new member (they will be the author of posts/comments)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "p@ssw0rd!";
  const memberNickname = RandomGenerator.name();
  const signUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
