  // 2. Create a new post as this member
  const postCreateBody = {
    title: RandomGenerator.paragraph()(50),
    body: RandomGenerator.content()()(150),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.member.posts.create(connection, { body: postCreateBody });
  typia.assert(post);

  // 3. Write a top-level comment
  const commentBody = {
    body: RandomGenerator.paragraph()(30),
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentBody
  });
  typia.assert(comment);

  // 4. Create a reply (child) comment
  const replyBody = {
    body: RandomGenerator.content()()(20),
    thread_parent_comment_id: comment.id
  } satisfies IDiscussionBoardComment.ICreate;
  const reply = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: replyBody
  });
  typia.assert(reply);

  // 5. Retrieve the top-level comment by postId and commentId
