 * Business Context:
 * Moderators need to be able to view subcategory details for moderation and navigation, but must not see admin-only audit data or sensitive fields. This test ensures the moderator role can retrieve the required details, that all key taxonomy fields are present, and that data access is correct.
 *
 * Steps:
 * 1. Admin creates a parent category (simulating as the current user).
 * 2. Admin creates a subcategory linked to that parent.
 * 3. An admin assigns and registers a new moderator account.
 * 4. The test switches to the moderator context (injects Authorization JWT from sign-up response).
 * 5. Moderator fetches the subcategory details for validation.
 *
 * Validation:
 * - The returned subcategory contains all mandatory fields, is linked to the parent, and matches values.
 * - Optional fields (description, icon_uri, deleted_at) are absent (null/undefined) by default.
 * - The response does not expose admin-only audit fields (none given in schema).
 */
export async function test_api_moderator_subcategory_detail_success(connection: api.IConnection) {
  // 1. Admin creates the parent category
  const categoryName = RandomGenerator.alphabets(12);
  const adminCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      enabled: true,
      display_order: 1,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(adminCategory);

  // 2. Admin creates a sub-category under the parent
