  TestValidator.equals("subcategory id")(result.id)(adminSubCategory.id);
  TestValidator.equals("parent id")(result.parent_id)(adminCategory.id);
  TestValidator.equals("enabled")(result.enabled)(true);
  TestValidator.equals("name")(result.name)(subCategoryName);
  TestValidator.equals("display order")(result.display_order)(2);
  TestValidator.equals("version")(result.version)(1);
  TestValidator.equals("deleted_at is null")(result.deleted_at)(null);
  TestValidator.predicate("created_at valid")(typeof result.created_at === "string" && !!Date.parse(result.created_at));
  TestValidator.predicate("updated_at valid")(typeof result.updated_at === "string" && !!Date.parse(result.updated_at));
  // Optional fields default check
  TestValidator.predicate("description not present or null")(result.description === null || result.description === undefined);
  TestValidator.predicate("icon_uri not present or null")(result.icon_uri === null || result.icon_uri === undefined);

  // (No audit-fields leak since schema does not expose any; SDK strips them.)

  // Optionally restore previous Authorization token if this matters for test suite isolation
  if (prevAuth !== undefined)
    connection.headers["Authorization"] = prevAuth;
  else if (connection.headers)
    delete connection.headers["Authorization"];
}

