/**
 * Validate email verification reset on member email update.
 *
 * Business context: When a member updates their email address, the `email_verified`
 * status must be reset regardless of inbound value (i.e., any update to the email requires
 * re-verification for security reasons). This test ensures proper enforcement of that business rule.
 *
 * Steps:
 * 1. Register a new member with unique email, password, nickname
 * 2. Authenticate as the member (registration issues a session token)
 * 3. Update the member's email address using the member PUT endpoint
 * 4. Assert that:
 *    - Output email is updated to the new value
 *    - email_verified is reset to false
 *    - Member ID is not changed
 *    - Nickname remains unchanged
 * 5. (Business note) Email verification workflow itself is out-of-scope of this E2E test and is not validated here.
 */
export async function test_api_member_profile_self_update_email_requires_verification(
  connection: api.IConnection,
) {
  // 1. Register a new member with random credentials
  const originalEmail = typia.random<string & tags.Format<"email">>();
  let newEmail = typia.random<string & tags.Format<"email">>();
  // Ensure emails differ in case of random collision
  while (newEmail === originalEmail) {
    newEmail = typia.random<string & tags.Format<"email">>();
  }
  const password = "P@ssw0rd!";
  const nickname = RandomGenerator.name();

  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: originalEmail,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
