  const memberId = registration.member.id;

  // Check initial state: email and verified status
  TestValidator.equals("Initial email verified is false")(registration.member.email_verified)(false);
  TestValidator.equals("Initial email matches")(registration.member.email)(originalEmail);

  // 2. Update the email address via endpoint
