  TestValidator.equals("Email verification reset")(updated.email_verified)(false);
  TestValidator.equals("Member ID unchanged")(updated.id)(memberId);
  TestValidator.equals("Nickname unchanged")(updated.nickname)(nickname);

  // Note: The external email verification workflow (e.g., confirmation email,
  // code entry by user) is initiated at the system level and is not in-scope for
  // this API E2E test (cannot be validated here).
}

