  connection.headers = { ...connection.headers, Authorization: ownerRegister.setHeaders.Authorization };

  // 4. First member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().slice(0, 50),
