 *
 * This test sequence confirms that a member can change their own vote on a comment (for example, from upvote to downvote), and that the change is accurately persisted and reflected by the API.
 *
 * Business context: Comment votes are an important mechanism for discussion engagement and sentiment analytics. To prevent vote fraud or abuse, only the owner of a comment vote should be able to update their own vote. This test checks for correct ownership permissions and verifies that the update propagates as expected in the returned data.
 *
 * Test Steps:
 * 1. Register a new member account and obtain authenticated session (register + token acquisition)
 * 2. Create a discussion post as the member
 * 3. Add a comment to the created post (member as the author)
 * 4. Member casts an upvote on their own comment
 * 5. Member updates their comment vote to a downvote via the update endpoint
 * 6. Assert that the vote's new value is reflected in the response and ownership constraints are preserved
 */
export async function test_api_comment_vote_update_by_owner_success(connection: api.IConnection) {
  // 1. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Passw0rd!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
