import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test the idempotent behavior of comment vote deletion.
 *
 * This test verifies that deleting a comment vote is idempotent: deleting a vote once removes it, and repeating the delete returns either a not-found or a no-op but does not error. This ensures that users can safely retry deletion without risk of 500 errors or inconsistent state.
 *
 * 1. Register as a new member and authenticate for session.
 * 2. Create a discussion board post as this member.
 * 3. Add a comment to this post as the same member.
 * 4. Cast a vote (upvote or downvote) on the created comment as this member.
 * 5. Delete the created comment vote by its ID (should succeed: normal deletion).
 * 6. Attempt to delete the same comment vote a second time; expect idempotent API behavior (either not-found or silent success; must not throw a 500 error).
 */
export async function test_api_comment_vote_delete_idempotency(connection: api.IConnection) {
  // 1. Register as a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Passw0rd!";
  const memberNickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);

  // 2. Create a discussion board post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1, 5),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment as this member
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Nice article!",
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Create a vote on the comment
  const vote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      is_upvote: RandomGenerator.pick([true, false]),
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(vote);

  // 5. Delete the vote (should remove successfully)
  await api.functional.discussionBoard.member.commentVotes.erase(connection, {
    commentVoteId: vote.id,
  });

  // 6. Attempt to delete again; must not cause unexpected (server) error
  let secondDeleteFailed = false;
  try {
    await api.functional.discussionBoard.member.commentVotes.erase(connection, {
      commentVoteId: vote.id,
    });
  } catch (error) {
    // Allow idempotent 404/not found or similar business error,
    // but fail if it's an unexpected error code (e.g., 500 internal)
    if (error && typeof error === "object" && "status" in error && (error.status === 404 || error.status === 400)) {
      // Acceptable: already deleted
      secondDeleteFailed = true;
    } else {
      throw error; // Unacceptable: rethrow if not known business error
    }
  }
  // If API returns silent success, both idempotent and not-found deletion are valid. If you want to assert, use:
  // TestValidator.predicate("Second delete is idempotent or not-found")(secondDeleteFailed === true || secondDeleteFailed === false);
}

