/**
 * Validate that the admin report search endpoint robustly handles filters leading to empty results or invalid parameters.
 *
 * This test ensures the endpoint:
 * - Returns empty data (pagination and result array) for non-matching filters (such as random UUIDs, non-existent status, unregistered reasons, and out-of-range dates).
 * - Properly throws errors for requests with invalid input such as page below 1, limit below 1, badly formatted dates, or non-UUID strings where UUID is required.
 *
 * Steps:
 * 1. Register a member (to ensure data context exists).
 * 2. Create a discussion board post as that member.
 * 3. Admin searches for post reports with random/mismatched filters and expects empty array and zero records.
 * 4. Admin searches using obviously invalid filter values for error scenarios: page below minimum, limit below minimum, malformed dates, and malformed UUIDs.
 */
export async function test_api_post_report_search_admin_empty_results_and_error_handling(connection: api.IConnection) {
  // 1. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password: "Test1234!@#",
      nickname: RandomGenerator.name(),
      avatar_uri: null
    }
  });
  typia.assert(session);

  // 2. Create a post as the registered member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      category_id: null,
      platform_config_id: null,
      title: RandomGenerator.alphaNumeric(16),
      body: RandomGenerator.paragraph()(),
      attachments: null
    }
  });
  typia.assert(post);

  // 3. Admin searches for post reports with non-matching filters (random UUIDs, fake status/reason values, out-of-range dates)
  const emptyResult = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
      handler_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "nonexistent-reason",
      status: "resolved-not-a-status",
      created_from: "2000-01-01T00:00:00.000Z",
      created_to: "2000-01-02T00:00:00.000Z",
      order_by: "created_at",
      direction: "asc",
      page: 1,
      limit: 10
    }
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result data")(emptyResult.data)([]);
  TestValidator.equals("empty result size")(emptyResult.pagination.records)(0);

  // 4. Admin searches for post reports with intentionally invalid input (should throw errors)
  await TestValidator.error("page too small")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 0, // invalid (minimum is 1)
        limit: 10
      }
    })
  );

  await TestValidator.error("limit too small")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 0 // invalid (minimum is 1)
      }
    })
  );

  await TestValidator.error("bad date format")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
        created_from: "notadate"
      }
    })
  );

  await TestValidator.error("bad uuid")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
        discussion_board_post_id: "this-is-not-a-uuid"
      }
    })
  );
}

