 *
 * Steps:
 * 1. Register a new member (the reporter)
 * 2. As that member, create a discussion post
 * 3. As that member, report the post for abuse with a reason code/text
 * 4. As an admin (assuming test environment auto-enables admin), retrieve the post report's detail using its ID
 * 5. Validate that all key fields—ID, reporter, post, reason, status, timestamps, handler/admin, and all audit/resolution data—are correctly returned and appear consistent with previous steps
 */
export async function test_api_post_report_detail_retrieval_success(
  connection: api.IConnection,
) {
