      body: {
        email: memberEmail,
        password: memberPassword,
        nickname: memberNickname,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberSession);

  // 2. As member, create a post
  connection.headers = {
    ...connection.headers,
    Authorization: memberSession.setHeaders.Authorization,
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(12).slice(0, 100), // max 100 chars
        body: RandomGenerator.content()()().slice(0, 4000), // max 4000 chars
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
