import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validates that a moderator can search and list discussion board categories using various filters and pagination.
 *
 * Business context:
 * This test ensures that, after an admin creates multiple categories (with enabled/disabled and parent/child scenarios), a moderator can authenticate and run searches with advanced filters and pagination, only retrieving categories and fields they are permitted to access.
 *
 * Steps:
 * 1. Generate a fake admin email to assign moderator role.
 * 2. Admin creates several categories:
 *    - Root enabled category
 *    - Subcategory enabled (child of root)
 *    - Root disabled category
 *    - Disabled subcategory (child of disabled root)
 *    - Unique-named category for substring filter
 * 3. Register moderator account, using above admin email as assigner.
 * 4. Apply moderator's JWT (from setHeaders) to connection for subsequent privileged calls.
 * 5. As moderator, search categories by:
 *    - parent_id (filter subcategories)
 *    - enabled
 *    - disabled
 *    - partial name
 *    - pagination size
 * 6. Assert search results match the expected filters, and paginated returns are consistent with query.
 */
export async function test_api_category_search_moderator_success(
  connection: api.IConnection,
) {
  // 1. Generate a fake admin email
  const adminEmail = typia.random<string & tags.Format<"email">>();

  // 2. Admin creates categories
  // 2a. Root enabled category
  const rootCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "RootCategory_ENABLED",
      display_order: 1,
      enabled: true,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(rootCategory);

  // 2b. Subcategory enabled under root
  const subCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "SubCategory_ENABLED",
      display_order: 2,
      enabled: true,
      version: 1,
      parent_id: rootCategory.id,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(subCategory);

  // 2c. Root disabled category
  const disabledRoot = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "RootCategory_DISABLED",
      display_order: 3,
      enabled: false,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(disabledRoot);

  // 2d. Disabled subcategory under disabled root
  const disabledSub = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "SubCategory_DISABLED",
      display_order: 4,
      enabled: false,
      version: 1,
      parent_id: disabledRoot.id,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(disabledSub);

  // 2e. Special name test category for partial filter
  const specialName = `SpecialSearch_${RandomGenerator.alphabets(8)}`;
  const specialCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: specialName,
      display_order: 5,
      enabled: true,
      version: 1,
      description: "Used for partial name filter",
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(specialCategory);

  // 3. Register moderator (admin email is assigner)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "testP@ssw0rd";
  const moderator = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderator);
  connection.headers = {
    ...connection.headers,
    ...moderator.setHeaders,
  };

  // 4a. Filter by parent_id (should return exactly the subCategory)
  const resultByParent = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      parent_id: rootCategory.id,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resultByParent);
  TestValidator.predicate("returns only subCategory with parent_id = rootCategory.id")(resultByParent.data.length === 1 && resultByParent.data[0].id === subCategory.id);

  // 4b. Filter for enabled=true (all results enabled)
  const resultEnabled = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      enabled: true,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resultEnabled);
  TestValidator.predicate("all categories enabled")(resultEnabled.data.every((c) => c.enabled));

  // 4c. Filter for enabled=false (all results disabled)
  const resultDisabled = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      enabled: false,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resultDisabled);
  TestValidator.predicate("all categories disabled")(resultDisabled.data.every((c) => !c.enabled));

  // 4d. Filter by partial name (should yield specialCategory)
  const partial = specialName.substring(0, 6);
  const resultByName = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      name: partial,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resultByName);
  TestValidator.predicate("should return at least one with specialName")(resultByName.data.some((c) => c.name === specialName));

  // 4e. Pagination test: limit to two per page
  const resultPaginated = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(resultPaginated);
  TestValidator.predicate("pagination size <= limit")(resultPaginated.data.length <= 2 && resultPaginated.pagination.limit === 2);
}

