 *
 * 1. Register two distinct admin accounts, each with unique email and secure password
 * 2. Using session authenticated as each admin, retrieve profile details for the target adminId
 * 3. Validate that all required schema fields (id, email, assigned_at, revoked_at, status, created_at, updated_at, deleted_at) are present and correctly correspond to the registered admin
 * 4. Confirm that sensitive fields (e.g., password, access_token, refresh_token) are not present in the admin profile response
 * 5. Check that each profile response strictly matches the admin queried by UUID (id and email)
 *
 * Note: This test focuses on happy path, not error or unauthorized access (handled in other test cases).
 */
export async function test_api_admin_detail_retrieve_success(
  connection: api.IConnection,
) {
