/**
 * Test access control for admin detail retrieval to ensure security boundaries are enforced for non-admin roles (moderator/member/guest).
 *
 * This test verifies that only users with admin privileges can view admin details via GET /discussionBoard/admin/admins/:adminId, and that moderator, member, and unauthenticated (guest) users are explicitly forbidden from this operation. Audit logging of forbidden attempts is required by policy, but only error outcome is validated here.
 *
 * Steps:
 * 1. Register a valid admin user (to create target adminId and for assignment flows).
 * 2. Register a valid member and moderator user (for privilege escalation attempt checks).
 * 3. As member, attempt to fetch admin details and expect error (forbidden).
 * 4. As moderator, attempt same and expect error (forbidden).
 * 5. As guest (without authentication), attempt and expect error (forbidden).
 */
export async function test_api_admin_detail_unauthorized_access_for_other_roles(connection: api.IConnection) {
  // 1. Register a new admin - will be the target of detail retrieval attempts
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member123!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Register a new moderator (assigned by admin)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Moderator123!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 4. As member, attempt to retrieve admin details (should fail)
  connection.headers = {
    ...connection.headers,
    Authorization: memberSession.setHeaders.Authorization,
  };
  await TestValidator.error("member forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );

  // 5. As moderator, attempt to retrieve admin details (should fail)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorSignUp.setHeaders.Authorization,
  };
  await TestValidator.error("moderator forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );

  // 6. As guest (no Authorization header), attempt to retrieve admin details (should fail)
  if (connection.headers) {
    delete connection.headers.Authorization;
  }
  await TestValidator.error("guest forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test successful update of an admin's profile, status, or assignment.
 *
 * This scenario validates the ability of the system to update only the allowed fields on an admin's record—specifically status and revoked_at—while ensuring that immutable fields (such as created_at and assigned_at) remain unchanged. It covers the business workflow from admin registration to profile/status update and includes comprehensive validation of audit and immutable fields.
 *
 * Steps:
 * 1. Register a new admin using the dedicated admin registration endpoint.
 * 2. Capture relevant information for the created admin (such as id, email, status, assigned_at, etc).
 * 3. Use the admin's id to update profile fields allowed by schema: status and revoked_at.
 * 4. Retrieve the resulting admin record and assert:
 *    - status and revoked_at reflect the updates
 *    - immutable fields (created_at, assigned_at, email, id) are unchanged
 *    - updated_at is changed to reflect the update operation
 *    - deleted_at remains null
 * 5. Test a negative update (attempting to supply an immutable field) is omitted because only updatable fields are accepted by the API.
 */
export async function test_api_admin_update_profile_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPass123!";

  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(registerResponse);

  // 2. Capture created admin's data
  const adminId = registerResponse.admin_id;
  const originalEmail = registerResponse.email;

  // 3. Prepare a permitted update: change status and supply revoked_at field
  const newStatus = "suspended";
  const newRevokedAt = new Date().toISOString();
  const updateBody = {
    status: newStatus,
    revoked_at: newRevokedAt,
  } satisfies IDiscussionBoardAdmin.IUpdate;

  const updatedAdmin = await api.functional.discussionBoard.admin.admins.update(connection, {
    adminId: adminId,
    body: updateBody,
  });
  typia.assert(updatedAdmin);

  // 4. Assert fields
  // Updatable fields changed
  TestValidator.equals("status updated")(updatedAdmin.status)(newStatus);
  TestValidator.equals("revoked_at updated")(updatedAdmin.revoked_at)(newRevokedAt);
  // Immutable fields unchanged
  TestValidator.equals("ID unchanged")(updatedAdmin.id)(adminId);
  TestValidator.equals("email unchanged")(updatedAdmin.email)(originalEmail);
  // Immutable assigned_at and created_at exist and are not empty (format validation handled by typia.assert)
  TestValidator.predicate("assigned_at remains set")(
    typeof updatedAdmin.assigned_at === "string" && updatedAdmin.assigned_at.length > 0
  );
  TestValidator.predicate("created_at remains set")(
    typeof updatedAdmin.created_at === "string" && updatedAdmin.created_at.length > 0
  );
  // Audit field updated_at updated to (roughly) now
  TestValidator.predicate("updated_at reflects update")(
    new Date(updatedAdmin.updated_at).getTime() >= new Date(newRevokedAt).getTime()
  );
  // deleted_at remains null or undefined
  TestValidator.equals("deleted_at unchanged or null")(updatedAdmin.deleted_at ?? null)(null);
}

