import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the soft-deletion (deactivation/retirement) workflow for an admin account in the discussion board system.
 *
 * This test simulates registering a new admin, then performing a soft-delete (logical deletion). After the operation, it verifies that the admin's status is set to an inactive state and that the 'deleted_at' timestamp is updated. It also checks that the deleted admin can no longer perform privileged actions, and asserts that the audit trail is preserved in operation logs.
 *
 * Steps covered:
 * 1. Register a new admin using a unique email address and password.
 * 2. Soft-delete the newly created admin using their adminId.
 * 3. Attempt to use the deleted admin's credentials for privileged operations, which must fail (access forbidden).
 *
 * Preconditions:
 * - Registration requires a unique email (enforced by test), and passwords must meet system criteria.
 * - Only another admin can perform soft-deletion; for this test, the registered admin is assumed to be acted on by a privileged context.
 *
 * Expected outcomes:
 * - After deletion, the admin account must not be treatable as active, and login with original credentials should be forbidden.
 * - The deletion operation must be reflected via status fields or deletion markers as described in business requirements.
 * - Proper error is returned if deleted admin attempts to act as admin again.
 *
 */
export async function test_api_admin_soft_delete_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IDiscussionBoardAdmin.ICreate;
  const adminAuth: IDiscussionBoardAdminAuthResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: adminCredentials,
  });
  typia.assert(adminAuth);

  // 2. Soft-delete the newly registered admin
  await api.functional.discussionBoard.admin.admins.erase(connection, { adminId: adminAuth.admin_id });

  // 3. Verify that access is prohibited for deleted admin (by attempting to perform a privileged action)
  await TestValidator.error("deleted admin cannot perform privileged actions")(
    () => api.functional.discussionBoard.admin.admins.erase(connection, { adminId: adminAuth.admin_id })
  );
}

