import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that only admins can perform soft-deletion of another admin.
 *
 * This test ensures that the soft-delete (deactivation) action on a discussion board admin account is restricted solely to users with admin privileges. Attempts to perform this action using a moderator or a regular member role must be forbidden and result in errors, while successful deletion is logged for compliance.
 *
 * Steps:
 * 1. Register an initial admin (AdminA) and store its credentials.
 * 2. Register a second admin (AdminB) to act as a target for deletion, and store its user ID.
 * 3. Have AdminA soft-delete AdminB successfully.
 * 4. Register a moderator account assigned by AdminA.
 * 5. Switch session to that moderator and attempt to delete AdminB — expect forbidden error.
 * 6. Register a regular member account.
 * 7. Switch session to that member and attempt to delete AdminB — expect forbidden error.
 */
export async function test_api_admin_soft_delete_by_non_admin_forbidden(connection: api.IConnection) {
  // Step 1: Register AdminA
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAPassword = "TestPassword1!";
  const adminA = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminAEmail,
      password: adminAPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminA);

  // Step 2: Register AdminB (target for deletion)
  const adminBEmail = typia.random<string & tags.Format<"email">>();
  const adminBPassword = "TestPassword2!";
  const adminB = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminBEmail,
      password: adminBPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminB);

  // Switch session to AdminA (should already be adminA, but ensure context)
  connection.headers = { ...connection.headers, Authorization: adminA.setHeaders.Authorization };

  // Step 3: AdminA soft-deletes AdminB
  await api.functional.discussionBoard.admin.admins.erase(connection, {
    adminId: adminB.admin_id,
  });

  // Step 4: Register Moderator (assigned by AdminA)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModeratorPass1!";
  const moderator = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: adminAEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderator);
  // Switch session to Moderator
  connection.headers = { ...connection.headers, Authorization: moderator.setHeaders.Authorization };

  // Step 5: Moderator attempts to soft-delete AdminB (should fail)
  await TestValidator.error("moderator forbidden on admin erase")(async () => {
    await api.functional.discussionBoard.admin.admins.erase(connection, {
      adminId: adminB.admin_id,
    });
  });

  // Step 6: Register Member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "MemberPass1!";
  const member = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);
  // Switch session to Member
  connection.headers = { ...connection.headers, Authorization: member.setHeaders.Authorization };

  // Step 7: Member attempts to soft-delete AdminB (should fail)
  await TestValidator.error("member forbidden on admin erase")(async () => {
    await api.functional.discussionBoard.admin.admins.erase(connection, {
      adminId: adminB.admin_id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate public accessibility of a published discussion board post by guests.
 *
 * This test ensures that when a member creates a post (which defaults to 'active' status and is not soft-deleted),
 * the post can be retrieved by its unique postId even by unauthenticated (guest) users. All primary, visible fields
 * should be returned for a valid published post—verifying the system's compliance with public access requirements
 * for open discussion boards. The scenario covers full data preparation (register, post creation), disables authentication
 * to emulate guest retrieval, and performs full field-level validation as well as status checks.
 *
 * Steps validated:
 * 1. Register a new member to enable post creation.
 * 2. Create a post as the authenticated member and capture its postId.
 * 3. Emulate a guest (unauthenticated) request by removing authentication from the connection headers.
 * 4. Retrieve the post details as a guest and confirm:
 *    - The post is accessible.
 *    - All public fields (id, title, body, author_member_id, status, timestamps, etc.) match and are present.
 *    - The status is 'active' and the post is not soft-deleted.
 *    - No forbidden/not found errors are generated for a valid post.
 */
export async function test_api_post_detail_public_access(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberNickname = RandomGenerator.name();
  const registerRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "pw" + RandomGenerator.alphaNumeric(8),
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(registerRes);
  const memberId = registerRes.member.id;

  // 2. Create post as member
  const postTitle = RandomGenerator.paragraph()().substring(0, 100);
  const postBody = RandomGenerator.content()()().substring(0, 4000);
  const createRes = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(createRes);
  TestValidator.equals("created post should have status active")(createRes.status)("active");
  TestValidator.equals("created post not soft deleted")(createRes.deleted_at)(null);
  const postId = createRes.id;

  // 3. Remove authentication to create guest connection
  const guestConnection = { ...connection, headers: { ...(connection.headers ?? {}) } };
  if ("Authorization" in guestConnection.headers) delete guestConnection.headers.Authorization;

  // 4. Guest retrieves the post details using /discussionBoard/posts/{postId}
  const postRes = await api.functional.discussionBoard.posts.at(guestConnection, { postId });
  typia.assert(postRes);

  // 5. Field verification for public visibility and integrity
  TestValidator.equals("public get returns same postId")(postRes.id)(postId);
  TestValidator.equals("public get returns status active")(postRes.status)("active");
  TestValidator.equals("public get not soft deleted")(postRes.deleted_at)(null);
  TestValidator.equals("public get matches title")(postRes.title)(postTitle);
  TestValidator.equals("public get matches body")(postRes.body)(postBody);
  TestValidator.equals("public get author linkage")(postRes.author_member_id)(memberId);
  TestValidator.predicate("created_at exists")(!!postRes.created_at);
  TestValidator.predicate("updated_at exists")(!!postRes.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that posts with status 'hidden' or 'deleted' cannot be accessed by unauthorized users (guest or regular members).
 *
 * This test covers discussion board content visibility and API access control workflows as follows:
 *
 * 1. Register a normal discussion board member (acquire authentication token in connection).
 * 2. As the member, create a new post ('active' status by default).
 * 3. Simulate admin context (by clearing connection headers) and update the post's status to 'hidden'.
 * 4. Attempt to fetch the hidden post as a guest (no Authorization header) — should raise not found or forbidden error.
 * 5. Attempt to fetch as a regular member (with token) — should also raise error.
 * 6. As admin, update status to 'deleted'.
 * 7. Test access as guest (again) and member (again) — both must fail.
 *
 * Notes:
 * - The admin session is simulated by clearing the connection.headers so no member token is present, matching API auth patterns.
 * - If the admin endpoint supports pure fetch (i.e., GET as admin), positive control could be checked, but here, all core negative controls are validated.
 */
export async function test_api_post_detail_hidden_post_access_denied(connection: api.IConnection) {
  // 1. Register a discussion board member (simulate member registration/login)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const password = "_Test1234!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password,
      nickname: RandomGenerator.name(),
    },
  });
  typia.assert(memberSession);

  // 2. As the member, create a new post ('active' status)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 3. Simulate admin context (no Authorization header) to update post status to 'hidden'
  const adminConnection = { ...connection, headers: {} };
  const hiddenPost = await api.functional.discussionBoard.admin.posts.update(adminConnection, {
    postId: post.id,
    body: { status: "hidden" },
  });
  typia.assert(hiddenPost);

  // 4. Attempt to fetch hidden post as guest (no Authorization header)
  await TestValidator.error("hidden post cannot be fetched as guest")(
    async () => {
      await api.functional.discussionBoard.posts.at(adminConnection, { postId: post.id });
    },
  );

  // 5. Attempt to fetch as regular member
  await TestValidator.error("hidden post cannot be fetched as member")(
    async () => {
      await api.functional.discussionBoard.posts.at(connection, { postId: post.id });
    },
  );

  // 6. As admin, update post status to 'deleted'
  const deletedPost = await api.functional.discussionBoard.admin.posts.update(adminConnection, {
    postId: post.id,
    body: { status: "deleted" },
  });
  typia.assert(deletedPost);

  // 7. Fetch as guest again (should fail)
  await TestValidator.error("deleted post cannot be fetched as guest")(
    async () => {
      await api.functional.discussionBoard.posts.at(adminConnection, { postId: post.id });
    },
  );

  // Fetch as member again (should fail)
  await TestValidator.error("deleted post cannot be fetched as member")(
    async () => {
      await api.functional.discussionBoard.posts.at(connection, { postId: post.id });
    },
  );
}

