import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate the creation of a new discussion board post by a registered member.
 *
 * This test verifies that a member can create a post with all valid required information (title, body), and that optional fields (category_id, attachments) are handled. Ensures returned post matches expectations, including status 'active', correct member linkage, and schema compliance.
 *
 * Steps:
 * 1. Register a new member using the registration endpoint and establish authentication context.
 * 2. Using the authenticated session, create a new discussion post supplying valid title and body.
 * 3. Assert the post is created with the correct status, proper author_member_id, and all required fields. Validate audit/status rules (status, timestamps, etc).
 */
export async function test_api_member_post_creation_success(
  connection: api.IConnection,
) {
  // 1. Register a new member and obtain authentication context
  const email = typia.random<string & tags.Format<"email">>();
  const password = "ValidPass123!";
  const nickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
    },
  });
  typia.assert(memberSession);

  // 2. Create new discussion post as authenticated member
  const postTitle = RandomGenerator.paragraph()(1).substring(0, 100); // max 100 chars
  const postBody = RandomGenerator.content()()().substring(0, 4000); // max 4000 chars
  const createInput = {
    title: postTitle,
    body: postBody,
  } satisfies IDiscussionBoardPost.ICreate;
  const createdPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: createInput,
  });
  typia.assert(createdPost);

