  TestValidator.equals("author_member_id matches")(createdPost.author_member_id)(memberSession.member.id);
  TestValidator.equals("status is active")(createdPost.status)("active");
  TestValidator.equals("title matches")(createdPost.title)(postTitle);
  TestValidator.equals("body matches")(createdPost.body)(postBody);
  TestValidator.predicate("created_at is present and ISO string")(
    typeof createdPost.created_at === "string" && !isNaN(Date.parse(createdPost.created_at))
  );
  TestValidator.predicate("updated_at is present and ISO string")(
    typeof createdPost.updated_at === "string" && !isNaN(Date.parse(createdPost.updated_at))
  );
  TestValidator.equals("deleted_at is null or undefined")(createdPost.deleted_at ?? null)(null);
}

