 * Test Steps:
 * 1. Register a new moderator account (simulate admin assigning role).
 * 2. Use the authenticated moderator session to create a discussion post. Specify title, body, a random category UUID, and a JSON string of attachments.
 * 3. Validate that the created post contains:
 *    - The expected title/body/category/attachments
 *    - author_moderator_id populated (matching newly registered moderator)
 *    - Correct status (e.g., 'active' or platform default for moderators)
 *    - Audit fields (created_at, updated_at) are present and valid
 *    - No author_member_id or author_admin_id is set
 */
export async function test_api_moderator_post_creation_success(
  connection: api.IConnection
) {
  // 1. Register moderator (simulate admin assignment)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const password = "test-Moder@tor123";
  const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password
    } satisfies IModerator.SignUp
  });
  typia.assert(signUpResp);
  // Use new session for all subsequent requests
  const moderatorConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signUpResp.setHeaders.Authorization
    }
  };

  // 2. Prepare post creation payload with required and optional fields
  const postPayload: IDiscussionBoardPost.ICreate = {
    title: "Discussion test title " + RandomGenerator.alphaNumeric(6),
    body: RandomGenerator.paragraph()().substring(0, 1200),
    category_id: typia.random<string & tags.Format<"uuid">>(), // random category ref
    attachments: JSON.stringify([
      "https://files.example.com/abc-1.jpg",
      "https://files.example.com/xyz-2.pdf"
    ])
  };
  // 3. Create the post as moderator
