import { SwaggerCustomizer } from "@nestia/core";
import { ExecutionContext, createParamDecorator } from "@nestjs/common";
import { Singleton } from "tstl";

import { moderatorAuthorize } from "../providers/authorize/moderatorAuthorize";

/**
 * Parameter decorator for authorizing moderator users.
 *
 * Usage (in Controller):
 * ```ts
 * someAction(@ModeratorAuth() moderator: ModeratorPayload) { ... }
 * ```
 * Injects an authenticated ModeratorPayload after validating JWT and DB.
 */
