import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { AdminPayload } from "../../decorators/payload/AdminPayload";

/**
 * Authenticate and authorize an admin via JWT and DB check.
 *
 * @param request HTTP request containing the Authorization header.
 * @returns Authenticated AdminPayload if valid; throws if not.
 */
export async function adminAuthorize(request: {
  headers: { authorization?: string }
}): Promise<AdminPayload> {
  const payload: AdminPayload = jwtAuthorize({ request }) as AdminPayload;

  if (payload.type !== "admin") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  const admin = await MyGlobal.prisma.discussion_board_admins.findFirst({
    where: {
      id: payload.id,
      deleted_at: null,
      revoked_at: null,
      status: "active",
    },
  });

  if (admin === null) {
    throw new ForbiddenException("You're not enrolled or no longer active.");
  }

  return payload;
}

