/**
 * Retrieve a flexible, paginated list of posts from the discussion board for admins.
 * Supports comprehensive filtering, text search, time window, sorting and paging. Only soft-deleted posts are excluded.
 * Returns category info per post, as available.
 *
 * @param props - Request properties containing the authenticated admin and filter/paging options.
 * @param props.admin - The authenticated admin (must be valid and active).
 * @param props.body - Filter, search, sort, and paging options (IDiscussionBoardPost.IRequest).
 * @returns Paginated post summaries (IPageIDiscussionBoardPost.ISummary), with audit metadata, category info if available, and robust null handling.
 * @throws {Error} If authentication fails or operation encounters a system error.
 */
export async function patch__discussionBoard_admin_posts(
  props: { admin: AdminPayload; body: IDiscussionBoardPost.IRequest }
): Promise<IPageIDiscussionBoardPost.ISummary> {
  const { admin, body } = props;

  const page: number = body.page && body.page > 0 ? body.page : 1;
  const limit: number = body.limit && body.limit > 0 ? body.limit : 20;
  const skip: number = (page - 1) * limit;

  const where = {
    deleted_at: null,
    ...(body.category_id !== undefined && body.category_id !== null && { category_id: body.category_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.author_member_id !== undefined && body.author_member_id !== null && { author_member_id: body.author_member_id }),
    ...(body.author_moderator_id !== undefined && body.author_moderator_id !== null && { author_moderator_id: body.author_moderator_id }),
    ...(body.author_admin_id !== undefined && body.author_admin_id !== null && { author_admin_id: body.author_admin_id }),
    ...(body.title !== undefined && body.title !== null && {
      title: { contains: body.title, mode: "insensitive" as const }
    }),
    ...(body.body !== undefined && body.body !== null && {
      body: { contains: body.body, mode: "insensitive" as const }
    }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
      (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined && body.created_at_from !== null && {
              gte: body.created_at_from,
            }),
            ...(body.created_at_to !== undefined && body.created_at_to !== null && {
              lte: body.created_at_to,
            }),
          }
        }
      : {}),
    ...((body.updated_at_from !== undefined && body.updated_at_from !== null) ||
      (body.updated_at_to !== undefined && body.updated_at_to !== null)
      ? {
          updated_at: {
            ...(body.updated_at_from !== undefined && body.updated_at_from !== null && {
              gte: body.updated_at_from,
            }),
            ...(body.updated_at_to !== undefined && body.updated_at_to !== null && {
              lte: body.updated_at_to,
            }),
          }
        }
      : {}),
  };

  const allowedSortFields = ["created_at", "updated_at", "title"];
  const sortField = body.sort_by && allowedSortFields.includes(body.sort_by) ? body.sort_by : "created_at";
  const sortOrder = body.sort_order === "asc" || body.sort_order === "desc" ? body.sort_order : "desc";

  const [posts, count] = await Promise.all([
    MyGlobal.prisma.discussion_board_posts.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip,
      take: limit,
      select: {
        id: true,
        title: true,
        status: true,
        category_id: true,
        author_member_id: true,
        author_moderator_id: true,
        author_admin_id: true,
        created_at: true,
        updated_at: true
      },
    }),
    MyGlobal.prisma.discussion_board_posts.count({ where }),
  ]);

  // Unique category_ids extraction, forcibly typed as string[] for Prisma matcher
  const categoryIds: string[] = Array.from(new Set(posts.map(p => p.category_id).filter((x): x is string => typeof x === "string")));
  let categoryMap: Record<string, IDiscussionBoardCategory.ISummary> = {};
  if (categoryIds.length > 0) {
    const categories = await MyGlobal.prisma.discussion_board_categories.findMany({
      where: { id: { in: categoryIds } },
      select: { id: true, name: true, icon_uri: true }
    });
    categoryMap = Object.fromEntries(
      categories.map(c => [c.id, { id: c.id, name: c.name, icon_uri: c.icon_uri ?? null }])
    );
  }

  // Compose out
  const data = posts.map(post => ({
    id: post.id,
    title: post.title,
    category:
      post.category_id && categoryMap[post.category_id]
        ? categoryMap[post.category_id]
        : {},
    status: post.status,
    author_member_id: post.author_member_id ?? null,
    author_moderator_id: post.author_moderator_id ?? null,
    author_admin_id: post.author_admin_id ?? null,
    created_at: toISOStringSafe(post.created_at),
    updated_at: toISOStringSafe(post.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: count,
      pages: Math.ceil(count / limit),
    },
    data,
  };
}

