 * @param props - { member: MemberPayload, body: IDiscussionBoardPost.ICreate }
 * @returns IDiscussionBoardPost including generated id, resolved category, & audit fields.
 * @throws {Error} If category_id is given but does not exist or is not enabled.
 */
export async function post__discussionBoard_member_posts(
  props: {
    member: MemberPayload;
    body: IDiscussionBoardPost.ICreate;
  }
): Promise<IDiscussionBoardPost> {
  const { member, body } = props;

  if (!body.category_id) {
    throw new Error("category_id is required by API design (response expects category object)");
