  };

  // Run query and count in parallel (no intermediate variables, inlines only)
  const [rows, records] = await Promise.all([
    MyGlobal.prisma.discussion_board_email_logs.findMany({
      where,
      orderBy: { sent_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        recipient_email: true,
        email_type: true,
        subject: true,
        sent_at: true,
        delivery_status: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_email_logs.count({ where }),
  ]);

